window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0052", [{"word":"exploratory","ipa_uk":"/ɪkˈsplɒrətəri/","ipa_us":"/ɪkˈsplɔːrətɔːri/","definition_zh":"探索性的；勘探的；试探性的","definition_en":"intended to search out, investigate or test something whose outcome is not yet known","core_image":"一个人举着火把走进尚未绘制的洞穴，边走边把路线记在纸上","scene":"The team ran an exploratory survey before committing money to the full excavation.","sceneCN":"这里 exploratory 是「探索性的、摸底性质的」（第 1 个义项：为了先弄清情况而做的调查）；句意：团队在投入全部开挖资金之前先做了一次探索性勘测。图中可辨识物件：火把、洞穴入口、测绘图、标记桩。","pos":[{"tag":"adj.","zh":"探索性的；勘探的；试探性的"}],"collocations":[{"phrase":"exploratory study","zh":"探索性研究"},{"phrase":"exploratory drilling","zh":"勘探性钻探"},{"phrase":"exploratory talks","zh":"探索性会谈"},{"phrase":"exploratory surgery","zh":"探查性手术"},{"phrase":"exploratory data analysis","zh":"探索性数据分析"},{"phrase":"exploratory phase","zh":"探索阶段"}],"forms":[{"label":"比较级","form":"more exploratory"},{"label":"最高级","form":"most exploratory"}],"derivatives":[{"word":"explore","pos":"v.","zh":"探索；勘探；探究"},{"word":"exploration","pos":"n.","zh":"探索；勘探；探究"},{"word":"explorer","pos":"n.","zh":"探索者；探险家"},{"word":"explorative","pos":"adj.","zh":"探索性的（与 exploratory 近义，更少用）"},{"word":"unexplored","pos":"adj.","zh":"未探索的；未勘探的"}],"senses":[{"no":"01","title":"Searching out the unknown","titleCN":"探索性的：先去弄明白","definition":"done in order to find out what exists or what is happening, before any final decision is made","definitionCN":"为了先弄清存在什么、正在发生什么而做的，尚未作出最终决定","example":"An exploratory visit to the site revealed two problems the report had missed.","exampleCN":"对现场的一次探索性走访发现了报告漏掉的两个问题。","why":"explorare in Latin means 'to search out'. The -ory suffix marks a purpose, so an exploratory action exists for the sake of searching, not for the sake of a result.","whyCN":"拉丁语 explorare 意为“搜出、查明”。-ory 后缀标记用途，所以 exploratory 的行为是为“查”本身而存在，不是为某个既定结果服务。"},{"no":"02","title":"Probing the ground","titleCN":"勘探的：先打孔看看地下","definition":"relating to the search for oil, minerals or water under the ground","definitionCN":"与寻找地下石油、矿产或水有关的","example":"Exploratory wells are cheap compared with the wells that actually produce oil.","exampleCN":"与真正出油的井相比，勘探井的成本很低。","why":"Mining and oil use the same word because the search happens before extraction. The hole is a question, not yet an answer.","whyCN":"采矿与石油业沿用同一个词，因为“找”发生在“采”之前。那个钻孔是一个问题，还不是答案。"},{"no":"03","title":"Tentative, not final","titleCN":"试探性的：先走一步看反应","definition":"acting as a first cautious step whose results will decide whether to continue","definitionCN":"作为谨慎的第一步、由结果决定是否继续的","example":"The company sent an exploratory email rather than a formal offer.","exampleCN":"公司发了一封试探性的邮件，而不是正式报价。","why":"A tentative step keeps the door open. The word borrows the miner's caution: you test the ground before you build on it.","whyCN":"试探性的一步保留了退路。这个词借用了矿工的谨慎：先试地下，再在上面动工。"},{"no":"04","title":"Medical probing","titleCN":"探查性的：打开看看里面怎么了","definition":"describing surgery or a clinical trial carried out to find the cause or the safe dose","definitionCN":"指为查明病因或安全剂量而进行的手术或临床试验","example":"Exploratory surgery showed that the pain came from a small adhesion.","exampleCN":"探查性手术显示疼痛来自一处小的粘连。","why":"Medicine borrows the mining image directly: the body is opened to look, because scans have not explained enough.","whyCN":"医学直接借用了采矿的意象：扫描没能解释清楚，于是打开身体去看。"},{"no":"05","title":"Learning by discovery","titleCN":"探索式学习的：让学生自己找到答案","definition":"describing teaching in which learners investigate a question instead of receiving the answer","definitionCN":"指让学习者自行探究问题、而不是直接接受答案的教学方式","example":"The exploratory lesson began with a question and no textbook page.","exampleCN":"这堂探索式课程从一个问题开始，没有对应的课本页。","why":"Here the search moves inside the classroom: the student repeats the original act of finding out, and the finding is the lesson.","whyCN":"这里“找”移到了教室内部：学生重复了最初那个“查明”的动作，而查到的过程本身就是课。"},{"no":"06","title":"Statistics: open-ended analysis","titleCN":"探索性数据分析的：先看数据长什么样","definition":"in statistics, describing analysis that looks for patterns before a specific hypothesis is fixed","definitionCN":"统计学上指在确定假设之前先寻找数据模式的分析","example":"Exploratory analysis found a cluster of outliers in the northern stations.","exampleCN":"探索性分析在北部站点发现了一簇离群值。","why":"Exploratory data analysis reverses the usual order: instead of testing a guess, it lets the data suggest the guess, which is again a search outward.","whyCN":"探索性数据分析颠倒了通常顺序：不是检验某个猜想，而是让数据提出猜想，仍然是向外搜找。"},{"no":"07","title":"First-round talks","titleCN":"探索性会谈：先摸摸对方底线","definition":"describing early discussions whose purpose is to discover whether agreement is possible","definitionCN":"指目的在于探明能否达成协议的早期磋商","example":"Exploratory talks resumed in Geneva after a three-month pause.","exampleCN":"探索性会谈在中断三个月后于日内瓦重启。","why":"Diplomacy uses exploratory for talks that are not yet negotiations. Nothing is conceded; the only product is information.","whyCN":"外交上用 exploratory 指还算不上谈判的会谈：不作让步，唯一的产出是信息。"},{"no":"08","title":"Testing the environment","titleCN":"试探行为的：伸出一只脚试试水深","definition":"in animal and human behaviour, describing actions that gather information about a new setting","definitionCN":"在动物与人类行为研究中，指为获取新环境信息而做的动作","example":"Exploratory behaviour in the young rats increased when the cage was new.","exampleCN":"笼子换成新的时，幼鼠的探索行为增加了。","why":"Behavioural science keeps the physical image: an organism reaches out, touches, retreats, and maps the space by movement.","whyCN":"行为科学保留了身体意象：生物伸手、触碰、退回，用移动把空间画成地图。"}],"etymology":{"intro":{"en":"Exploratory comes from Latin explorare 'to search out, investigate', built on ex- 'out' plus plorare 'to cry out'. The image is a hunter shouting while searching. English added -ory to make the adjective.","cn":"exploratory 来自拉丁语 explorare“搜出、调查”，由 ex-“向外”加 plorare“呼喊”构成。意象是猎人在搜寻时大声呼喊。英语加上 -ory 构成形容词。"},"items":[{"era":"LATIN PLORARE","en":"plorare meant 'to cry out, wail'. Its further origin is uncertain; some scholars connect it with pluere 'to rain', but this is a guess and should be marked source uncertain.","cn":"plorare 意为“大声喊、哭喊”。其更深来源不确定，有学者把它与 pluere“下雨”联系起来，但这只是推测，应标注“来源不确定”。"},{"era":"LATIN EXPLORARE","en":"ex- 'out' plus plorare produced explorare, 'to cry out while searching', hence 'to search out, examine'. The shout is the signal that someone is looking.","cn":"ex-“向外”加 plorare 构成 explorare，意为“一边搜寻一边呼喊”，引申为“搜出、检查”。喊声就是“有人在找”的信号。"},{"era":"LATIN EXPLORATOR","en":"explorator was a scout or spy, the person who went ahead to see what was there. The noun keeps the human agent of the search.","cn":"explorator 是侦察兵、探子，先行去看情况的人。这个名词保留了“搜寻”的执行者。"},{"era":"ENGLISH -ORY","en":"English builds exploratory on the stem explorat- plus -ory, from Latin -orius 'serving for'. The adjective appears in the 17th century, first in religious and then in scientific writing.","cn":"英语以 explorat- 词干加 -ory（来自拉丁 -orius“用于……”）构成 exploratory。该形容词出现于 17 世纪，最早见于宗教写作，随后进入科学写作。"},{"era":"SCIENTIFIC AND MEDICAL USE","en":"From the 19th century exploratory spreads to surgery, drilling and field surveys, where the search must happen before any commitment.","cn":"19 世纪起，exploratory 扩展到外科、钻探与野外勘测，这些场合都必须先搜寻、后投入。"},{"era":"DATA AND DIPLOMACY","en":"In the 20th century the word reaches statistics and diplomacy, naming analysis and talks that deliberately avoid a fixed conclusion.","cn":"20 世纪，这个词进入统计学与外交领域，指刻意不预设结论的分析与会谈。"}]},"similar":{"note":{"en":"The look-alike group shares the ex- or -plor- shape but not always the same root; the near-meaning group shares the idea of a first, cautious step.","cn":"形近组共享 ex- 或 -plor- 的外形，但未必同根；近义组都含“先走一步、谨慎试探”的意思。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"explorative","ipa":"/ɪkˈsplɒrətɪv/","tag":"same root, -ive suffix","definition":"another adjective from the same verb, meaning 'tending to explore'. It describes a quality, while exploratory describes a purpose.","definitionCN":"同一动词派生的另一形容词，意为“有探索倾向的”。它描述性质，而 exploratory 描述用途。"},{"word":"exploration","ipa":"/ˌekspləˈreɪʃn/","tag":"same root, noun","definition":"the act of searching or travelling to find out. The noun names the activity; the adjective names what the activity is for.","definitionCN":"探索、勘探的行为。名词命名活动本身；形容词命名活动的用途。"},{"word":"exploitative","ipa":"/ɪkˈsplɔɪtətɪv/","tag":"different root: plicare","definition":"taking unfair advantage of people or resources. It looks close because of ex- and -or-, but exploit comes from Latin explicare 'unfold', not from plorare.","definitionCN":"剥削性的；利用他人或资源的。它因 ex- 与 -or- 而形近，但 exploit 来自拉丁 explicare“展开”，并非 plorare。"}]},{"heading":"NEAR MEANING","entries":[{"word":"investigative","ipa":"/ɪnˈvestɪɡətɪv/","tag":"focused on finding facts","definition":"concerned with discovering facts, often formally. It stresses method and evidence, while exploratory stresses the open, unfinished stage.","definitionCN":"调查性的；重在查明事实，常带正式色彩。它强调方法与证据，而 exploratory 强调开放、未定型的阶段。"},{"word":"preliminary","ipa":"/prɪˈlɪmɪnəri/","tag":"comes first","definition":"coming before the main part as preparation. It marks order, not necessarily search.","definitionCN":"初步的；作为主要部分之前的准备。它标记顺序，不一定含“搜寻”之意。"},{"word":"tentative","ipa":"/ˈtentətɪv/","tag":"cautious and provisional","definition":"done or said in a cautious way, ready to be changed. It describes hesitation, while exploratory describes the information being sought.","definitionCN":"试探性的；谨慎且可更改的。它描述犹豫，而 exploratory 描述被搜寻的信息。"},{"word":"pilot","ipa":"/ˈpaɪlət/","tag":"small-scale first run","definition":"used as an adjective for a small trial that tests whether a larger plan will work. It is close to exploratory but implies a planned full version to follow.","definitionCN":"试点性的；以小规模试验检验更大计划是否可行。它接近 exploratory，但暗含之后有计划的完整版本。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"ex- 'out' + plorare 'cry out': the explorer is the one who shouts outward while looking.","cn":"ex-“向外”+ plorare“呼喊”：探索者就是一边向外喊、一边找的人。"},{"en":"exploration, explore and explorer all keep the same stem, so the family is learned as one block.","cn":"exploration、explore、explorer 共享同一词干，可以整块记忆。"},{"en":"exploratory talks and exploratory drilling are both first steps that produce information, not final products.","cn":"exploratory talks 与 exploratory drilling 都是产出信息、不产出成品的第一步。"},{"en":"exploratory surgery is literally opening the body to look, which is the clearest picture of the word.","cn":"exploratory surgery 字面上就是打开身体去看，是这个词最清楚的画面。"},{"en":"The opposite situation is a confirmatory study, which tests a claim already fixed; exploratory looks before the claim exists.","cn":"反面的情形是 confirmatory study（确证性研究），检验已经固定的主张；exploratory 则是在主张出现之前先看。"}],"abstract":[{"en":"Think of a lantern sweeping across a cave wall: the beam does not build anything, it only shows what is there.","cn":"想象一盏灯扫过洞壁：光束不建造任何东西，只是把已有的东西照出来。"},{"en":"Think of a hand testing the temperature of water with one finger before the whole body enters.","cn":"想象先用一根手指试水温，然后整个身体才下水。"},{"en":"Think of a map that is still mostly blank, with a dotted line marking where someone has already walked.","cn":"想象一张大半空白的地图，只有一条虚线标出已经走过的路。"}]},"examples":[{"en":"The ministry funded an exploratory project to see whether the soil could hold a dam.","cn":"该部门资助了一个探索性项目，看看这土壤能否承住一座水坝。"},{"en":"After two exploratory meetings, both sides agreed to draft a real treaty.","cn":"经过两次探索性会谈，双方同意起草一份正式条约。"},{"en":"Exploratory analysis is useful precisely because it does not decide the answer in advance.","cn":"探索性分析之所以有用，恰恰因为它不预先决定答案。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“往外铺路”——ex（向外）+ plor（铺路的“铺”音近）：先向外铺一条小路，边走边看 → exploratory 探索性的","word":"exploratory"},"root":"拉丁 explorare“搜出、调查”（ex-“向外”+ plorare“呼喊”，plorare 的更深来源不确定）；explorat- 词干 + -ory“用于……的”。","sensesIntro":{"en":"Eight senses share one motion: a person moves outward into unmapped ground, and the moving itself is the point.","cn":"八个义项共享一个动作：人向外走进尚未绘图的地方，而“走”本身就是目的。"},"semanticMap":{"core":{"en":"CORE IMAGE: a lantern moving into an unmapped cave.","cn":"核心意象：一盏灯移进尚未绘图的洞穴。"},"chain":["SEARCH OUT","PROBE THE GROUND","TEST CAUTIOUSLY","OPEN THE BODY","LEARN BY FINDING","LOOK BEFORE THE CLAIM"],"branches":[{"senses":"01 · 02","en":"SEARCH AND SURVEY: the general search and the miner's test hole are the same outward movement, one on land and one under it.","cn":"搜寻与勘测：一般性探索与矿工的试孔是同一个向外动作，一个在地面，一个在地下。"},{"senses":"03 · 07","en":"CAUTIOUS FIRST STEP: an exploratory email and exploratory talks both buy information before commitment.","cn":"谨慎的第一步：试探性邮件与探索性会谈，都在投入之前先换取信息。"},{"senses":"04","en":"MEDICAL PROBE: surgery that opens the body to look is the literal version of the same search.","cn":"医学探查：为看清楚而打开身体的手术，是同一搜寻的字面版本。"},{"senses":"05","en":"LEARNING: discovery-based teaching moves the search inside the learner, who repeats the original act.","cn":"学习：发现式教学把搜寻移进学习者内部，让他重复最初的动作。"},{"senses":"06 · 08","en":"OPEN-ENDED INQUIRY: data analysis and animal exploration both gather patterns before any hypothesis is fixed.","cn":"开放式探究：数据分析与动物探索都在固定假设之前先收集模式。"}]},"affixes":{"intro":{"en":"Exploratory is a Latin stem with the English suffix -ory. The ex- prefix is still readable as 'out', while -ory marks purpose; -tion and -er build the noun family.","cn":"exploratory 是拉丁词干加英语后缀 -ory。ex- 前缀仍可读作“向外”，-ory 标记用途；-tion 与 -er 构成名词族。"},"latinIntro":{"en":"The family grows from plorare 'cry out' through explorare 'search out' to explorator 'scout'. The stem appears as explor- in English.","cn":"这个词族从 plorare“呼喊”经 explorare“搜出”生长到 explorator“侦察者”。英语中词干作 explor-。"},"items":[{"word":"explore","structure":"ex- (out) + plorare (cry out)","meaning":"to search out; to travel through for discovery","meaningCN":"探索；勘探（ex-“向外”+ plorare“呼喊”）","example":"They explored the cave for three days.","exampleCN":"他们花了三天探索那个洞穴。"},{"word":"exploration","structure":"explorat- + -ion (action noun)","meaning":"the act of searching or surveying","meaningCN":"探索；勘探（-ion 构成行为名词）","example":"Exploration of the seabed began last spring.","exampleCN":"海底勘探于去年春天开始。"},{"word":"explorer","structure":"explor- + -er (person noun)","meaning":"a person who explores","meaningCN":"探索者；探险家（-er 构成施事名词）","example":"The explorer mapped the river's upper course.","exampleCN":"这位探险家绘制了那条河的上游。"},{"word":"explorative","structure":"explorat- + -ive (tendency)","meaning":"having a tendency to explore","meaningCN":"有探索倾向的（-ive 表性质）","example":"The study used an explorative design with open questions.","exampleCN":"该研究采用了带开放问题的探索性设计。"},{"word":"unexplored","structure":"un- (not) + explored","meaning":"not yet searched or mapped","meaningCN":"未被探索的（un-“未”+ explored）","example":"Much of the cave remains unexplored.","exampleCN":"洞中很大一部分仍未勘探。"},{"word":"exploratory","structure":"explorat- + -ory (serving for)","meaning":"serving the purpose of searching","meaningCN":"探索性的（-ory“用于……”）","example":"The exploratory phase lasted six weeks.","exampleCN":"探索阶段持续了六周。"},{"word":"explorator","structure":"explorat- + -or (agent noun)","meaning":"a scout or investigator, now rare","meaningCN":"侦察者；调查者（-or 施事名词，现罕用）","example":"The old texts call the scout an explorator.","exampleCN":"古籍把侦察兵称作 explorator。"},{"word":"exploratively","structure":"explorative + -ly (manner adverb)","meaning":"in a searching manner","meaningCN":"以探索的方式（-ly 构成方式副词）","example":"She asked the question exploratively rather than as a challenge.","exampleCN":"她以探索的口吻提问，而不是在挑衅。"}],"latinEntries":[{"word":"plorare","structure":"plorare (to cry out)","meaning":"to cry out, wail","meaningCN":"呼喊；哭喊（更深来源不确定）"},{"word":"explorare","structure":"ex- (out) + plorare (cry out)","meaning":"to search out, investigate","meaningCN":"搜出；调查"},{"word":"explorator","structure":"explorare + -or (agent)","meaning":"a scout, a spy","meaningCN":"侦察者；探子"},{"word":"exploratus","structure":"past participle of explorare","meaning":"having been searched out","meaningCN":"已被查明的（explorare 的过去分词）"}]}},{"word":"exposure","ipa_uk":"/ɪkˈspəʊʒə(r)/","ipa_us":"/ɪkˈspoʊʒər/","definition_zh":"暴露；接触；曝光；揭露；风险敞口","definition_en":"the state of being left open to something, or the act of bringing something into contact with light, risk, media or experience","core_image":"一个人站在没有遮挡的空地上，风、光和雨都直接打在身上","scene":"Long-term exposure to fine dust raised the workers' risk of lung disease.","sceneCN":"这里 exposure 是「暴露、接触」（第 1 个义项：身体长期处于某种环境之中）；句意：长期接触细粉尘提高了工人患肺病的风险。图中可辨识物件：口罩、粉尘云、车间通风管、监测仪。","pos":[{"tag":"n.","zh":"暴露；接触；曝光；揭露；风险敞口"}],"collocations":[{"phrase":"exposure to","zh":"暴露于；接触"},{"phrase":"prolonged exposure","zh":"长期暴露"},{"phrase":"media exposure","zh":"媒体曝光度"},{"phrase":"exposure time","zh":"曝光时间"},{"phrase":"financial exposure","zh":"金融风险敞口"},{"phrase":"exposure of a scandal","zh":"丑闻的揭露"}],"forms":[{"label":"复数","form":"exposures"}],"derivatives":[{"word":"expose","pos":"v.","zh":"使暴露；揭露；使接触"},{"word":"exposed","pos":"adj.","zh":"暴露的；无遮蔽的"},{"word":"exposé","pos":"n.","zh":"揭露性文章；曝光报道"},{"word":"overexposure","pos":"n.","zh":"曝光过度；过度曝光"},{"word":"underexposure","pos":"n.","zh":"曝光不足"}],"senses":[{"no":"01","title":"Left open to harm","titleCN":"暴露于：身体没有遮挡地处在危险中","definition":"the state of being in contact with something harmful, such as chemicals, radiation or disease","definitionCN":"与化学品、辐射或疾病等有害物接触的状态","example":"Exposure to lead can damage a child's developing brain.","exampleCN":"接触铅会损害儿童发育中的大脑。","why":"exponere means 'to put out'. Exposure is the state of having been put out where the harm can reach you, with no wall in between.","whyCN":"exponere 意为“放出去”。exposure 就是被放到伤害够得着的地方，中间没有墙。"},{"no":"02","title":"Contact that teaches","titleCN":"接触：在环境里泡出来的经验","definition":"the experience of meeting an idea, language or culture, especially over time","definitionCN":"接触某种观念、语言或文化的经历，尤指长期接触","example":"Children who get early exposure to two languages learn both without effort.","exampleCN":"早期接触两种语言的儿童会毫不费力地学会两种语言。","why":"The same openness that is dangerous for a toxin is valuable for a language: what surrounds you enters you. Only the object of exposure changes.","whyCN":"对毒素危险的“敞开”，对语言却很有价值：包围你的东西会进入你。变的只是被暴露的对象。"},{"no":"03","title":"Photography: light on film","titleCN":"曝光：让光在胶片上留下痕迹","definition":"the amount of light allowed to reach film or a sensor, or the act of allowing it","definitionCN":"允许到达胶片或传感器的光量，或让光到达的行为","example":"A two-second exposure turned the moving cars into streaks of light.","exampleCN":"两秒曝光把行驶的车变成了光带。","why":"Photography keeps the literal sense: the film is exposed, left open to light. Too much light and the image burns; too little and nothing appears.","whyCN":"摄影保留了字面义：胶片被“敞开”给光。光太多画面烧白，太少什么也不出现。"},{"no":"04","title":"Public attention","titleCN":"曝光度：被很多人看见","definition":"the amount of attention a person or product receives from the public or media","definitionCN":"个人或产品从公众或媒体获得的关注量","example":"The young pianist gained national exposure after one televised concert.","exampleCN":"这位年轻钢琴家在一场电视音乐会后获得了全国性的曝光。","why":"Media exposure treats the person like the film: being seen by many is being lit by many lamps. Attention is the light.","whyCN":"媒体曝光把人当成胶片：被很多人看见，就是被很多盏灯照着。注意力就是光。"},{"no":"05","title":"Unmasking a secret","titleCN":"揭露：把藏起来的事拿出来","definition":"the act of making a secret, crime or lie visible to the public","definitionCN":"把秘密、罪行或谎言公开示众的行为","example":"The exposure of the fake invoices forced the director to resign.","exampleCN":"假发票被揭露后，那位主管被迫辞职。","why":"Here the word turns active: someone drags a hidden thing into the light. The direction reverses, but the image of light remains.","whyCN":"这里词义转为主动：有人把藏着的东西拖到光下。方向反了，光的意象仍在。"},{"no":"06","title":"Finance: risk exposure","titleCN":"风险敞口：可能被市场伤到的部分","definition":"the amount of money or value that could be lost if a market or borrower fails","definitionCN":"如果市场或借款人出问题、可能损失的资金或价值量","example":"The bank reduced its exposure to the housing market before prices fell.","exampleCN":"银行在房价下跌前降低了对楼市的敞口。","why":"Finance borrows the body image: part of the balance sheet is left uncovered, standing in the open where a loss can hit it.","whyCN":"金融借用了身体意象：资产负债表的一部分没有被遮住，站在空地上，亏损可以打到它。"},{"no":"07","title":"Weather: bodily exposure","titleCN":"受冻：在户外没有遮蔽","definition":"the condition of being left without shelter in cold or bad weather","definitionCN":"在寒冷或恶劣天气中没有遮蔽的状态","example":"The climbers died of exposure before the rescue team arrived.","exampleCN":"登山者在救援队到达前死于失温。","why":"Old medical reports say a patient died of exposure, meaning the weather reached the body directly. Shelter is the absence of exposure.","whyCN":"旧时病历说病人死于 exposure，意思是天气直接作用到身体。有遮蔽就是没有 exposure。"},{"no":"08","title":"Geology: visible rock","titleCN":"露头：岩层露在地表","definition":"a place where rock or soil lies open at the surface and can be seen","definitionCN":"岩石或土壤出露地表、可以被看到的地方","example":"The road cut created a clean exposure of three rock layers.","exampleCN":"开山修路剖出了三层岩石的清晰露头。","why":"Geology speaks of an exposure because the ground has been uncovered. The hidden layer is now open to the air, exactly as the verb describes.","whyCN":"地质学说的 exposure，指地面被揭开。原本隐藏的岩层现在敞开在空气中，正是动词描绘的状态。"},{"no":"09","title":"Architecture: which way it faces","titleCN":"朝向：房子哪一面受光","definition":"the direction in which a building or slope faces the sun, wind or weather","definitionCN":"建筑物或坡面朝向太阳、风或天气的方向","example":"A southern exposure keeps the kitchen warm through the winter.","exampleCN":"朝南的朝向让厨房整个冬天都暖和。","why":"The oldest architectural sense is simply which side is left open to the sky. A house with a southern exposure is a house whose south wall is uncovered.","whyCN":"最古老的建筑义项就是哪一面敞开对着天空。朝南的房子，就是南墙没有遮拦的房子。"}],"etymology":{"intro":{"en":"Exposure is an English noun built on expose, which comes from Latin exponere 'to put out'. The Latin verb joins ex- 'out' to ponere 'to place', so exposure is literally the state of being placed outside.","cn":"exposure 是英语名词，建立在 expose 之上，而 expose 来自拉丁 exponere“放出去”。这个拉丁动词把 ex-“向外”与 ponere“放置”合在一起，因此 exposure 字面上就是“被放到外面”的状态。"},"items":[{"era":"LATIN PONERE","en":"ponere meant 'to put, place'. Its past participle positus gives English position, positive and deposit; the same root appears in impose and compose, but with different prefixes.","cn":"ponere 意为“放置”。其过去分词 positus 生出英语 position、positive、deposit；同一词根也见于 impose、compose，但前缀不同。"},{"era":"LATIN EXPONERE","en":"ex- 'out' plus ponere gives exponere 'to put out, set forth'. It could mean both 'to expose' and 'to explain', because explaining sets an idea out where others can see it.","cn":"ex-“向外”加 ponere 构成 exponere“放出去、摆出来”。它既可指“暴露”，也可指“解释”，因为解释就是把想法摆出来给人看。"},{"era":"ENGLISH EXPOSE","en":"English takes the French form exposer and makes expose in the 16th century. The verb keeps the double life: to expose a child to danger, and to expose a lie.","cn":"英语在 16 世纪借法语 exposer 形成 expose。这个动词保留了双重生命：让孩子暴露于危险，以及揭露一个谎言。"},{"era":"ENGLISH -URE","en":"Exposure is expose plus -ure, from Latin -ura, marking a resulting state. The noun is formed inside English rather than inherited whole from Latin.","cn":"exposure 是 expose 加 -ure（来自拉丁 -ura，标记结果状态）。这个名词是在英语内部构成的，而不是整词从拉丁继承。"},{"era":"PHOTOGRAPHIC SENSE","en":"In the 19th century photography gives exposure its technical sense: the film is exposed to light for a measured time.","cn":"19 世纪摄影赋予 exposure 技术义：胶片在计量的时间内暴露于光。"},{"era":"FINANCIAL SENSE","en":"In the 20th century finance extends the word to money left uncovered by hedging, the modern risk exposure.","cn":"20 世纪金融把该词扩展到未被对冲保护的资金，即现代的风险敞口。"}]},"similar":{"note":{"en":"The look-alike group shares ex- or the -pos- shape; the near-meaning group all involve being touched by something outside oneself.","cn":"形近组共享 ex- 或 -pos- 的外形；近义组都涉及“被外部事物触及”。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"exposition","ipa":"/ˌekspəˈzɪʃn/","tag":"same root, -ition noun","definition":"a full explanation of an idea, or a public exhibition. It comes from the same exponere but stresses setting out in words, not leaving open to harm.","definitionCN":"详细阐述，或公开展览。它同出 exponere，但强调用文字摆出来，而非暴露于伤害。"},{"word":"exposé","ipa":"/ˌekspəʊˈzeɪ/","tag":"same root, French form","definition":"a report that reveals a scandal. It is the active, unmasking side of exposure, borrowed back from French.","definitionCN":"揭露丑闻的报道。它是 exposure 中主动揭发的一面，从法语借回。"},{"word":"expenditure","ipa":"/ɪkˈspendɪtʃə/","tag":"different root: pendere","definition":"money that is spent. It looks similar because of ex-, but comes from ex- plus pendere 'weigh, pay', not from ponere 'place'.","definitionCN":"支出；花费。它因 ex- 而形近，但来自 ex- 加 pendere“称量、支付”，并非 ponere“放置”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"vulnerability","ipa":"/vʌlnərəˈbɪləti/","tag":"openness to harm","definition":"the quality of being easily hurt or attacked. It stresses weakness, while exposure stresses contact with a specific agent.","definitionCN":"易受伤害或攻击的性质。它强调脆弱，而 exposure 强调与特定因素的接触。"},{"word":"contact","ipa":"/ˈkɒntækt/","tag":"touching or meeting","definition":"the state of touching or communicating. It is neutral, while exposure often carries risk or intensity.","definitionCN":"接触或联系的状态。它中性，而 exposure 常带风险或强度。"},{"word":"publicity","ipa":"/pʌbˈlɪsəti/","tag":"public attention","definition":"attention given by the media. It covers the media sense of exposure but not its photographic or medical senses.","definitionCN":"媒体给予的关注。它覆盖 exposure 的媒体义，但不含摄影或医学义。"},{"word":"disclosure","ipa":"/dɪsˈkləʊʒə(r)/","tag":"making known","definition":"the act of making information public. It matches the unmasking sense but is usually deliberate and official.","definitionCN":"公开信息的行为。它对应“揭露”义，但通常是有意且正式的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"ex- 'out' + ponere 'place': exposure is being placed outside, where things can reach you.","cn":"ex-“向外”+ ponere“放置”：exposure 就是被放到外面，让东西够得着你。"},{"en":"expose, exposed, exposure, exposé share the same -pos- stem and the same idea of uncovering.","cn":"expose、exposed、exposure、exposé 共享 -pos- 词干，也共享“揭开”的意思。"},{"en":"Photography makes the word physical: exposure time is literally how long the film stays open to light.","cn":"摄影让这个词变得具体：exposure time 就是胶片对光敞开多久。"},{"en":"Financial exposure and bodily exposure are one image: the part left uncovered is the part that can be hurt.","cn":"金融敞口与身体暴露是同一个意象：没有遮住的部分，就是可能受伤的部分。"},{"en":"Note the pair: exposure to a language is good, exposure to lead is bad; the word itself is neutral.","cn":"记住这一对：接触语言是好事，接触铅是坏事；词本身是中性的。"}],"abstract":[{"en":"Think of a wall with one brick missing: the wind finds exactly that gap.","cn":"想象一堵墙缺了一块砖：风偏偏从那个缺口进来。"},{"en":"Think of a photographic plate laid under an open sky, slowly recording every minute of light.","cn":"想象一块感光板摊在开阔天空下，慢慢记录每一分钟的光。"},{"en":"Think of a spotlight swung onto a hidden corner of a room: what was private becomes public.","cn":"想象一盏聚光灯扫到房间的暗角：原本私密的东西变成了公开的。"}]},"examples":[{"en":"Workers were given masks to reduce their exposure to the solvent.","cn":"工人们领到口罩，以减少对溶剂的接触。"},{"en":"The scandal received little exposure until a local paper published the letters.","cn":"直到一家地方报纸刊出那些信件，这桩丑闻才获得少量曝光。"},{"en":"A long exposure made the stars appear as short arcs.","cn":"长时间曝光让星星变成了短短的弧线。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“一克斯剖热”——把东西剖（po）开放在外（ex）面，热（ure）气就散出来 → exposure 暴露、曝光","word":"exposure"},"root":"拉丁 exponere“放出去”（ex-“向外”+ ponere“放置”），英语加 -ure 构成名词；ponere 的过去分词 positus 也是 position、positive 的词源。","sensesIntro":{"en":"Nine senses share one state: something is placed outside its shelter, and whatever is outside can now reach it.","cn":"九个义项共享一个状态：某物被放到遮蔽之外，于是外面的东西就能触及它。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person standing uncovered in an open field.","cn":"核心意象：一个人没有遮蔽地站在空地上。"},"chain":["LEFT OPEN","TOUCHED BY HARM","TOUCHED BY EXPERIENCE","RECEIVING LIGHT","SEEN BY MANY","BROUGHT INTO THE OPEN"],"branches":[{"senses":"01 · 06 · 07","en":"HARM: chemical, financial and weather exposure all leave a part uncovered where loss can enter.","cn":"伤害：化学品、金融与严寒的 exposure，都留下一块没有遮住的地方让损失进来。"},{"senses":"02","en":"LEARNING: contact with a language or culture uses the same openness for gain instead of loss.","cn":"学习：接触语言或文化，把同样的“敞开”用于获得而非损失。"},{"senses":"03 · 04 · 09","en":"LIGHT: film, media attention and a south-facing wall are all surfaces left open to light.","cn":"光：胶片、媒体关注与朝南的墙面，都是对光敞开的表面。"},{"senses":"05","en":"UNMASKING: exposure of a secret reverses the direction, dragging a hidden thing into the light.","cn":"揭露：秘密的 exposure 反转方向，把藏起来的东西拖到光下。"},{"senses":"08","en":"GEOLOGY: an exposure of rock is ground uncovered, the literal state the noun names.","cn":"地质：岩石的 exposure 是地面被揭开，正是名词命名的字面状态。"}]},"affixes":{"intro":{"en":"Exposure is expose plus -ure. The ex- prefix means 'out' and is still transparent; -ure marks a state or result, and the -pos- stem carries the meaning 'place'.","cn":"exposure 是 expose 加 -ure。ex- 前缀意为“向外”且仍然透明；-ure 标记状态或结果，-pos- 词干承载“放置”之义。"},"latinIntro":{"en":"The Latin family grows from ponere 'place' through exponere 'put out'. English relatives include expose, expose, exposition, composition and impose, each with a different prefix.","cn":"这个拉丁词族从 ponere“放置”经 exponere“放出去”生长。英语同族词包括 expose、exposition、composition、impose，各自前缀不同。"},"items":[{"word":"expose","structure":"ex- (out) + ponere (place)","meaning":"to leave uncovered; to reveal","meaningCN":"使暴露；揭露（ex-“向外”+ ponere“放置”）","example":"Do not expose the sample to direct sunlight.","exampleCN":"不要让样本直接暴露在阳光下。"},{"word":"exposed","structure":"expose + -ed (past participle)","meaning":"left without shelter or protection","meaningCN":"无遮蔽的；暴露的（-ed 过去分词）","example":"The exposed slope lost its soil within a year.","exampleCN":"裸露的坡面一年内就流失了土壤。"},{"word":"exposure","structure":"expose + -ure (state noun)","meaning":"the state of being left open","meaningCN":"暴露；曝光（-ure 状态名词）","example":"Exposure to noise above 85 decibels damages hearing.","exampleCN":"接触 85 分贝以上的噪声会损害听力。"},{"word":"exposition","structure":"exposit- + -ion (action noun)","meaning":"a full explanation; a public show","meaningCN":"阐述；展览（-ion 行为名词，来自 exponere 的另一支）","example":"The first chapter is a clear exposition of the theory.","exampleCN":"第一章是对该理论的清晰阐述。"},{"word":"exposé","structure":"French exposé, past participle of exposer","meaning":"a revealing report","meaningCN":"揭露性报道（法语过去分词借入）","example":"The exposé named three companies in the illegal trade.","exampleCN":"这篇揭露报道点名了三家参与非法贸易的公司。"},{"word":"overexposure","structure":"over- (too much) + exposure","meaning":"too much light or too much publicity","meaningCN":"曝光过度；过度曝光（over-“过多”）","example":"Overexposure turned the white wall into a flat grey.","exampleCN":"曝光过度把白墙变成了一片灰。"},{"word":"underexposure","structure":"under- (too little) + exposure","meaning":"too little light reaching the film","meaningCN":"曝光不足（under-“过少”）","example":"Underexposure hid the details in the shadow.","exampleCN":"曝光不足让阴影里的细节消失了。"},{"word":"exposable","structure":"expose + -able (capable of being)","meaning":"able to be exposed or revealed","meaningCN":"可暴露的；可揭发的（-able“能够被……”）","example":"Only part of the archive is exposable under the law.","exampleCN":"根据法律，只有部分档案可以公开。"}],"latinEntries":[{"word":"ponere","structure":"ponere (to place)","meaning":"to put, place, set","meaningCN":"放置；安放"},{"word":"exponere","structure":"ex- (out) + ponere (place)","meaning":"to put out, set forth","meaningCN":"放出去；摆出来；解释"},{"word":"expositus","structure":"past participle of exponere","meaning":"having been put out","meaningCN":"已被放出的（exponere 的过去分词）"},{"word":"positio","structure":"posit- + -io (action noun)","meaning":"a placing, a position","meaningCN":"放置；位置"}]}},{"word":"externality","ipa_uk":"/ˌekstɜːˈnæləti/","ipa_us":"/ˌekstɜːrˈnæləti/","definition_zh":"外部性；外部效应；外在性","definition_en":"an effect of an activity that falls on people who did not choose to bear it; also the quality of being outward or external","core_image":"工厂烟囱的烟越过围墙，落在邻居的晾衣绳上","scene":"The factory's pollution is a negative externality that the nearby residents pay for.","sceneCN":"这里 externality 是「外部性、外部成本」（第 1 个义项：成本落到交易之外的第三方）；句意：工厂的污染是一种负外部性，代价由附近居民承担。图中可辨识物件：烟囱、围墙、晾衣绳、口罩。","pos":[{"tag":"n.","zh":"外部性；外部效应；外在性"}],"collocations":[{"phrase":"negative externality","zh":"负外部性"},{"phrase":"positive externality","zh":"正外部性"},{"phrase":"internalize externalities","zh":"使外部性内部化"},{"phrase":"network externality","zh":"网络外部性"},{"phrase":"environmental externality","zh":"环境外部性"},{"phrase":"externality cost","zh":"外部性成本"}],"forms":[{"label":"复数","form":"externalities"}],"derivatives":[{"word":"external","pos":"adj.","zh":"外部的；外来的"},{"word":"externally","pos":"adv.","zh":"外部地；从外面"},{"word":"externalize","pos":"v.","zh":"使外化；把……归因于外部"},{"word":"externalization","pos":"n.","zh":"外化；外部化"},{"word":"externalism","pos":"n.","zh":"外在主义"}],"senses":[{"no":"01","title":"Economics: a cost pushed onto others","titleCN":"负外部性：成本落到旁观者身上","definition":"in economics, a cost of a transaction that is borne by people who are not part of it","definitionCN":"经济学上指交易的成本由并未参与交易的人承担","example":"Air pollution from the plant is a negative externality for the whole valley.","exampleCN":"工厂造成的空气污染对整个山谷来说是一种负外部性。","why":"The word names what stays 'external' to the price. The buyer and seller settle their account, and the cost that escapes the account lands on a third party.","whyCN":"这个词命名的是被留在价格“之外”的东西。买卖双方结清自己的账，逃出账本的成本落在第三方身上。"},{"no":"02","title":"Economics: a benefit given away","titleCN":"正外部性：好处漏给了别人","definition":"in economics, a benefit of an activity that others receive without paying for it","definitionCN":"经济学上指活动的收益被他人无偿获得","example":"Vaccination creates a positive externality by protecting people who were not vaccinated.","exampleCN":"接种疫苗产生正外部性，保护了没有接种的人。","why":"The mechanism is the same as with costs, only the sign flips. Something crosses the boundary of the deal, and those outside gain instead of lose.","whyCN":"机制与成本完全相同，只是符号翻转。有东西越过交易的边界，外面的人因此得利而非受损。"},{"no":"03","title":"The concept in policy","titleCN":"外部效应：政策要处理的那部分","definition":"the general concept used in policy when private choices produce public consequences","definitionCN":"政策讨论中使用的总称，指私人选择产生公共后果","example":"The report treats congestion as an externality that road pricing could correct.","exampleCN":"报告把拥堵视为一种可通过道路定价纠正的外部效应。","why":"Once named, the externality becomes an object of policy. The word shifts from a description of harm to a thing that can be measured, taxed or regulated.","whyCN":"一旦被命名，外部性就成了政策对象。这个词从“伤害的描述”变成可测量、可征税、可监管的“东西”。"},{"no":"04","title":"Network externality","titleCN":"网络外部性：用的人越多越有价值","definition":"the effect by which a product becomes more useful to each user as the number of users grows","definitionCN":"产品随着用户数量增加而对每个用户更有用的效应","example":"A messaging app shows a strong network externality: its value rises with every new user.","exampleCN":"通讯应用表现出很强的网络外部性：每多一个用户，它的价值就上升。","why":"Here the external effect is between users rather than bystanders. Each new user benefits the others without intending to, which is the same 'outside the deal' logic.","whyCN":"这里的外部效应发生在用户之间而非旁观者之间。每个新用户无意中让其他人受益，仍是“交易之外”的逻辑。"},{"no":"05","title":"Philosophy: outwardness","titleCN":"外在性：只看得见外表","definition":"the quality of being outward or concerned only with external appearances","definitionCN":"外在的性质，或只关注外部表象的状态","example":"The essay criticizes the externality of a life judged only by possessions.","exampleCN":"这篇文章批评那种只以财物评判人生的外在性。","why":"This older sense is not economic at all: externality is the state of belonging to the outside. The economic sense is a specialized child of the same idea.","whyCN":"这个较早的义项与经济无关：externality 是“属于外部”的状态。经济义只是同一观念的一个专门分支。"},{"no":"06","title":"External circumstances","titleCN":"外部事物：身外的一切条件","definition":"things outside a person or system that affect it but are not part of it","definitionCN":"位于个人或系统之外、会影响它却不属于它的事物","example":"The plan assumed stable prices and ignored externalities such as drought.","exampleCN":"该计划假定价格稳定，忽略了干旱之类的外部因素。","why":"The plural here simply means outside conditions. What matters is the boundary: these things act on the system from beyond its edge.","whyCN":"这里的复数只是“外部条件”。关键在于边界：这些事物从边界之外作用于系统。"},{"no":"07","title":"Internalizing them","titleCN":"内部化：把外部成本收回账本","definition":"the process of making those outside costs part of the producer's own accounts, as through a tax","definitionCN":"通过税收等手段让外部成本进入生产者自己账本的过程","example":"A carbon tax is a way of internalizing a climate externality.","exampleCN":"碳税是把气候外部性内部化的一种方式。","why":"The phrase internalize an externality contains the whole story: something outside is brought inside the boundary of the accounts, where prices can see it.","whyCN":"internalize an externality 这个说法包含了整个故事：把外面的东西带进账本的边界，让价格看得见它。"},{"no":"08","title":"Spillover between neighbours","titleCN":"邻里外溢：围墙挡不住的效应","definition":"any local side effect of one actor's activity on nearby people or property","definitionCN":"某一行为者活动对附近的人或财产造成的任何局部副作用","example":"Noise from the late shift is a neighbourhood externality nobody priced.","exampleCN":"夜班噪音是一种没人定过价的邻里外部性。","why":"The everyday version is the smoke over the fence. No economist is needed to see it: one person's activity leaves the property and lands on another's.","whyCN":"日常版本就是越过围墙的烟。不需要经济学家也能看见：一个人的活动离开自己的地盘，落到别人的地盘上。"}],"etymology":{"intro":{"en":"Externality is external plus -ity. External comes from Latin externus 'outward', built on exter 'outside', which itself is a comparative form of ex 'out of'. The economic sense is a modern specialization.","cn":"externality 是 external 加 -ity。external 来自拉丁 externus“向外的”，建立在 exter“外面”之上，而 exter 又是 ex“出自”的比较级形式。经济义是现代专门化的结果。"},"items":[{"era":"LATIN EX","en":"ex meant 'out of, from'. It is the source of the English prefix ex- and of many prepositions in Romance languages.","cn":"ex 意为“出自、从”。它是英语前缀 ex- 以及诸多罗曼语介词之源。"},{"era":"LATIN EXTER","en":"exter was an adjective meaning 'outward, on the outside', comparative in form. It described what lies beyond a boundary.","cn":"exter 是形容词，意为“向外的、在外的”，形式上为比较级。它描述边界之外的东西。"},{"era":"LATIN EXTERNUS","en":"externus 'outward, foreign' develops from exter. Latin also had exterus and the adverb foris 'out of doors' as parallel ways to say 'outside'.","cn":"externus“向外的、外来的”由 exter 发展而来。拉丁语还有 exterus 以及副词 foris“在门外”，都是表达“外面”的并行方式。"},{"era":"ENGLISH EXTERNAL","en":"English external appears in the 15th century through Late Latin externalis. It contrasts with internal, and the pair still organizes much academic vocabulary.","cn":"英语 external 于 15 世纪经晚期拉丁 externalis 进入。它与 internal 相对，这一对词至今组织着大量学术词汇。"},{"era":"ENGLISH -ITY","en":"The suffix -ity comes from Latin -itas and turns an adjective into a quality noun. Externality therefore means 'the quality of being external' before it means anything economic.","cn":"后缀 -ity 来自拉丁 -itas，把形容词变成性质名词。因此 externality 在获得经济含义之前，意思是“外在的性质”。"},{"era":"ECONOMIC SENSE","en":"The economic use grows in the late 19th and 20th centuries, when economists needed a name for effects that escape the price of a transaction. The exact first use is disputed, so it is marked source uncertain.","cn":"经济用法在 19 世纪末至 20 世纪发展起来，经济学家需要一个名称来指逃出交易价格的影响。确切最早用例存有争议，故标“来源不确定”。"}]},"similar":{"note":{"en":"The look-alike group shares the exter- shape but includes one word from a completely different root; the near-meaning group all name effects that reach beyond the immediate parties.","cn":"形近组共享 exter- 外形，但其中一个是完全不同词根；近义组都指超出直接当事人之外的影响。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"external","ipa":"/ɪkˈstɜːnl/","tag":"same root, adjective","definition":"coming from or belonging to the outside. It is the base adjective; externality is the abstract noun built on it.","definitionCN":"外部的；外来的。它是基础形容词，externality 是在其上构成的抽象名词。"},{"word":"externally","ipa":"/ɪkˈstɜːnəli/","tag":"same root, adverb","definition":"in an outward way, or by an outside agent. It modifies an action, while externality names a thing or quality.","definitionCN":"外部地；从外部。它修饰动作，而 externality 命名事物或性质。"},{"word":"eternality","ipa":"/ɪˌtɜːˈnæləti/","tag":"different root: aeternus","definition":"the state of lasting forever. It sounds almost identical but comes from Latin aeternus 'eternal', not from exter 'outside'.","definitionCN":"永恒性。它读音几乎相同，但来自拉丁 aeternus“永恒的”，并非 exter“外面”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"spillover","ipa":"/ˈspɪləʊvə(r)/","tag":"effect crossing a border","definition":"an effect that spreads from one area or group into another. It is the everyday image behind externality.","definitionCN":"从一领域或群体扩散到另一领域的影响。它是 externality 背后的日常意象。"},{"word":"side effect","ipa":"/ˈsaɪd ɪˈfekt/","tag":"unintended consequence","definition":"an unintended result of an action, usually unwanted. It is broader and need not involve a third party.","definitionCN":"行为的非预期结果，通常不受欢迎。它范围更广，不必涉及第三方。"},{"word":"by-product","ipa":"/ˈbaɪ prɒdʌkt/","tag":"secondary output","definition":"something produced as a secondary result. It points to the output itself, while externality points to who bears it.","definitionCN":"次要产物。它指向产出物本身，而 externality 指向由谁承担。"},{"word":"third-party effect","ipa":"/ˌθɜːd ˈpɑːti ɪˈfekt/","tag":"effect on outsiders","definition":"an effect on someone who is not one of the parties involved. It is the plain-language definition of an externality.","definitionCN":"对非当事人产生的影响。它就是 externality 的白话定义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"exter means 'outside': an externality is what sits outside the deal and still sends its bill in.","cn":"exter 意为“外面”：externality 就是坐在交易之外、却把账单寄进来的东西。"},{"en":"external, externally and externality form a clean family of adjective, adverb and noun.","cn":"external、externally、externality 构成形容词、副词、名词的整齐一族。"},{"en":"negative externality and positive externality differ only in sign, not in mechanism.","cn":"negative externality 与 positive externality 只在符号上不同，机制相同。"},{"en":"internalize an externality is the useful phrase: the outside cost is brought inside the accounts.","cn":"internalize an externality 是有用的搭配：把外部成本带进账本内部。"},{"en":"Do not confuse it with eternality: eternity is forever, externality is outside.","cn":"别与 eternality 混淆：eternity 是永远，externality 是外面。"}],"abstract":[{"en":"Think of smoke crossing a fence and settling on someone else's washing.","cn":"想象烟越过围墙，落在别人晾着的衣服上。"},{"en":"Think of a factory's bill being quietly forwarded to a house it has never visited.","cn":"想象工厂的账单被悄悄转寄到一栋它从未去过的房子。"},{"en":"Think of a boundary line drawn around a deal, with arrows leaking out of it in both directions.","cn":"想象在交易周围画一条边界线，箭头从线的两侧漏出去。"}]},"examples":[{"en":"Economists argue that a tax on carbon would price the externality into every decision.","cn":"经济学家认为，碳税会把外部性计入每一个决策。"},{"en":"The new rail link produced a positive externality for firms along the route.","cn":"新铁路为沿线的企业带来了正外部性。"},{"en":"Noise and traffic are the two externalities residents mention most often.","cn":"噪音与交通是居民最常提到的两项外部性。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“外部哪里提”——成本不在内部账上，要问“外部哪里提（ti）走”→ externality 外部性","word":"externality"},"root":"拉丁 exter“外面”（ex“出自”的比较级形式）→ externus“向外的” → 英语 external + -ity；经济义为 19 世纪末以来的专门化用法。","sensesIntro":{"en":"Eight senses share one boundary: something crosses the edge of a transaction or a system and lands on someone who did not ask for it.","cn":"八个义项共享一条边界：某物越过交易或系统的边缘，落到并未要求它的人身上。"},"semanticMap":{"core":{"en":"CORE IMAGE: smoke crossing a fence onto a neighbour's washing.","cn":"核心意象：烟越过围墙，落到邻居晾着的衣服上。"},"chain":["OUTSIDE THE DEAL","COST ON OTHERS","BENEFIT TO OTHERS","PUBLIC CONSEQUENCE","NETWORK EFFECT","BROUGHT INSIDE"],"branches":[{"senses":"01 · 02","en":"THE SIGN: negative and positive externalities are one crossing, differing only in whether the outsider gains or loses.","cn":"符号：负与正外部性是同一次越界，区别只在外人受损还是受益。"},{"senses":"03 · 07","en":"POLICY: naming an externality turns it into something that can be taxed, and internalizing brings it back inside the accounts.","cn":"政策：命名外部性使它变成可征税之物，内部化则把它带回账本。"},{"senses":"04","en":"NETWORK: users benefit one another unintentionally, the same outside-the-deal logic applied between users.","cn":"网络：用户无意中相互受益，同一套“交易之外”的逻辑用在用户之间。"},{"senses":"05 · 06","en":"OUTWARDNESS: the older senses name the state of being outside, before economics specialized the word.","cn":"外在性：较早的义项命名“处于外部”的状态，早于经济学的专门化。"},{"senses":"08","en":"NEIGHBOURS: the everyday local effect is the plainest picture of the whole concept.","cn":"邻里：日常的局部影响是整个概念最朴素的画面。"}]},"affixes":{"intro":{"en":"Externality is external plus -ity. The -ity suffix turns the adjective into a quality noun, while the base keeps the Latin comparative exter 'more outside'.","cn":"externality 是 external 加 -ity。-ity 把形容词变成性质名词，词基保留了拉丁比较级 exter“更外面”。"},"latinIntro":{"en":"The family runs from ex 'out of' to exter 'outside' to externus 'outward'. English builds external, externally and externality on the last form.","cn":"这个词族从 ex“出自”到 exter“外面”再到 externus“向外的”。英语在最后一形上构成 external、externally、externality。"},"items":[{"word":"external","structure":"externus + -al (relational adjective)","meaning":"belonging to the outside","meaningCN":"外部的；外来的（-al 关系形容词）","example":"The review brought in two external experts.","exampleCN":"评审引入了两位外部专家。"},{"word":"externally","structure":"external + -ly (manner adverb)","meaning":"from or on the outside","meaningCN":"从外部；外部地（-ly 方式副词）","example":"The tank is externally reinforced with steel bars.","exampleCN":"罐体外部用钢条加固。"},{"word":"externality","structure":"external + -ity (quality noun)","meaning":"the quality of being external; an outside effect","meaningCN":"外在性；外部性（-ity 性质名词）","example":"The externality is borne by the fishing village.","exampleCN":"这项外部性由渔村承担。"},{"word":"externalize","structure":"external + -ize (make verb)","meaning":"to make outward or attribute to outside causes","meaningCN":"使外化；归因于外部（-ize 使动动词）","example":"He externalized the blame onto the weather.","exampleCN":"他把责任外化到天气上。"},{"word":"externalization","structure":"externalize + -ation (process noun)","meaning":"the process of making something external","meaningCN":"外化过程（-ation 过程名词）","example":"Externalization of costs is the core of the problem.","exampleCN":"成本的外化正是问题的核心。"},{"word":"externalism","structure":"external + -ism (system noun)","meaning":"a view that stresses outside conditions","meaningCN":"外在主义（-ism 体系名词）","example":"Externalism holds that meaning depends on the world outside the mind.","exampleCN":"外在主义认为意义取决于心灵之外的世界。"},{"word":"extern","structure":"externus shortened","meaning":"an external student or worker, now rare","meaningCN":"走读生；外部人员（罕用）","example":"The hospital took on two externs from the university.","exampleCN":"医院接收了两名大学的走读实习生。"},{"word":"exterior","structure":"comparative of exter","meaning":"the outside surface of something","meaningCN":"外部；外表（exter 的比较级形式）","example":"The exterior of the building was painted last year.","exampleCN":"这栋楼的外表去年刷过漆。"}],"latinEntries":[{"word":"ex","structure":"ex (out of, from)","meaning":"out of, from","meaningCN":"出自；从"},{"word":"exter","structure":"comparative form of ex","meaning":"outward, on the outside","meaningCN":"向外的；在外的"},{"word":"externus","structure":"exter + -nus (adjective)","meaning":"outward, foreign","meaningCN":"向外的；外来的"},{"word":"externalis","structure":"externus + -alis (adjective)","meaning":"relating to the outside","meaningCN":"与外部有关的（晚期拉丁）"}]}},{"word":"extraction","ipa_uk":"/ɪkˈstrækʃn/","ipa_us":"/ɪkˈstrækʃn/","definition_zh":"提取；开采；拔除；摘录；出身","definition_en":"the act of drawing something out of a place, a substance, a body or a text","core_image":"一根吸管插进果肉，把里面的汁一点点抽出来","scene":"DNA extraction from the sample took less than an hour with the new kit.","sceneCN":"这里 extraction 是「提取」（第 1 个义项：把某物质从混合物或样本中分离出来）；句意：用新试剂盒从样本中提取 DNA 不到一小时。图中可辨识物件：离心管、移液枪、试剂盒、样本。","pos":[{"tag":"n.","zh":"提取；开采；拔除；摘录；出身"}],"collocations":[{"phrase":"extraction of","zh":"……的提取"},{"phrase":"DNA extraction","zh":"DNA 提取"},{"phrase":"coal extraction","zh":"煤炭开采"},{"phrase":"tooth extraction","zh":"拔牙"},{"phrase":"extraction rate","zh":"提取率"},{"phrase":"data extraction","zh":"数据提取"}],"forms":[{"label":"复数","form":"extractions"}],"derivatives":[{"word":"extract","pos":"v./n.","zh":"提取；拔出；摘录；提取物"},{"word":"extractor","pos":"n.","zh":"提取器；排气扇"},{"word":"extractive","pos":"adj.","zh":"提取的；采掘的"},{"word":"extractable","pos":"adj.","zh":"可提取的；可抽出的"},{"word":"extractionist","pos":"n.","zh":"主张提取说的人（罕用）"}],"senses":[{"no":"01","title":"Drawing a substance out","titleCN":"提取：把想要的东西从混合物里分离","definition":"the chemical or physical process of separating a substance from a mixture or sample","definitionCN":"从混合物或样本中分离出某物质的化学或物理过程","example":"The extraction of caffeine from coffee beans uses a solvent and heat.","exampleCN":"从咖啡豆中提取咖啡因要用溶剂和加热。","why":"extrahere means 'to draw out'. Extraction names the process after the direction: what is wanted is pulled out of what surrounds it.","whyCN":"extrahere 意为“抽出”。extraction 按方向命名过程：想要的东西被从包围它的东西里拉出来。"},{"no":"02","title":"Taking ore from the ground","titleCN":"开采：把矿从地下取出来","definition":"the mining of coal, oil, gas or minerals from the earth","definitionCN":"从地下开采煤、石油、天然气或矿物","example":"Coal extraction in the region fell by a third in ten years.","exampleCN":"该地区的煤炭开采量十年间下降了三分之一。","why":"Mining is the same pull, only the container is the earth. The word treats the ground as a substance from which something is drawn.","whyCN":"采矿是同一种“拉”，只是容器变成了大地。这个词把地面当作一种可以被抽出东西的物质。"},{"no":"03","title":"Pulling a tooth or a bullet","titleCN":"拔除：把嵌在身体里的东西取出来","definition":"the removal of a tooth, bullet or other object from the body","definitionCN":"从身体中取出牙齿、子弹或其他物体","example":"The extraction of the damaged tooth took only fifteen minutes.","exampleCN":"拔掉那颗坏牙只用了十五分钟。","why":"Dentistry uses extraction because the tooth is embedded in the gum. The object is not cut away; it is drawn out whole.","whyCN":"牙科用 extraction，因为牙齿嵌在牙龈里。不是把牙削掉，而是整颗抽出来。"},{"no":"04","title":"A passage taken from a text","titleCN":"摘录：从文章里抽一段出来","definition":"a short passage copied out of a longer text","definitionCN":"从较长文本中抄出的一段短文","example":"The anthology prints an extraction from her 1897 diary.","exampleCN":"这本选集刊出了她 1897 年日记的一段摘录。","why":"Here the container is a book. The image holds: a piece is pulled out and shown apart from the whole that held it.","whyCN":"这里的容器是一本书。意象不变：一块内容被抽出来，脱离原本包住它的整体单独展示。"},{"no":"05","title":"Origin or descent","titleCN":"出身：从哪个家族抽出来的","definition":"a person's family origin or social background, used in the phrase 'of ... extraction'","definitionCN":"某人的家族出身或社会背景，用于 of ... extraction 这一说法","example":"She is of Italian extraction but grew up in Buenos Aires.","exampleCN":"她是意大利裔，但在布宜诺斯艾利斯长大。","why":"The figurative sense treats ancestry as the substance a person was drawn from. You come out of a family the way a filament is pulled from a source.","whyCN":"这个比喻义把血统当作人被抽出的“原料”。人出自某个家族，就像细丝从源头被抽出。"},{"no":"06","title":"Pulling data out","titleCN":"数据提取：从系统里抽调信息","definition":"the process of retrieving selected information from records, websites or databases","definitionCN":"从记录、网页或数据库中取回选定信息的过程","example":"Automated extraction turned ten thousand invoices into a single table.","exampleCN":"自动提取把一万张发票变成了一张表。","why":"Databases are the modern ore. The verb stays exact: the wanted rows are drawn out of the mass that stores them.","whyCN":"数据库是现代矿石。动词仍精确：想要的行被从储存它们的大堆数据里抽出来。"},{"no":"07","title":"How much comes out","titleCN":"提取率：能抽出多少","definition":"the proportion of a useful substance recovered from the raw material","definitionCN":"从原料中回收的有用物质所占比例","example":"The new press raised the oil extraction rate from 18 to 24 percent.","exampleCN":"新压榨机把出油率从 18% 提高到 24%。","why":"Once the process is named, the result can be measured. Extraction rate simply asks how much of the target actually left its container.","whyCN":"过程一旦被命名，结果就能被计量。extraction rate 问的就是目标物实际离开了容器多少。"},{"no":"08","title":"Forcing out a confession","titleCN":"逼取：把口供从人嘴里抽出来","definition":"the act of obtaining money or information from someone by pressure or threat","definitionCN":"通过施压或威胁从某人处取得钱财或信息","example":"The report condemned the extraction of confessions under threat.","exampleCN":"报告谴责在威胁下逼取口供的做法。","why":"This darker sense uses the same verb on a person: information is treated as something held inside and pulled out by force.","whyCN":"这个更黑暗的义项把同一动词用在人身上：信息被当作藏在体内、靠强力抽出的东西。"}],"etymology":{"intro":{"en":"Extraction comes from extract, from Latin extrahere 'to draw out', built on ex- 'out' plus trahere 'to draw, drag'. The word has always been about direction: something is pulled from its container.","cn":"extraction 来自 extract，而 extract 出自拉丁 extrahere“抽出”，由 ex-“向外”加 trahere“拉、拖”构成。这个词始终关于方向：某物被从容器里拉出来。"},"items":[{"era":"LATIN TRAHERE","en":"trahere meant 'to draw, drag, pull'. Its past participle tractus gives English tract, tractor and contract; the same root underlies attract and distract with different prefixes.","cn":"trahere 意为“拉、拖、拽”。其过去分词 tractus 生出英语 tract、tractor、contract；同一词根也见于 attract、distract，但前缀不同。"},{"era":"LATIN EXTRAHERE","en":"ex- 'out' plus trahere gives extrahere 'to draw out'. The verb pictured a hand pulling something from a bag or a body.","cn":"ex-“向外”加 trahere 构成 extrahere“抽出”。这个动词原画面是一只手从袋子或身体里往外拉东西。"},{"era":"LATIN EXTRACTUS","en":"The past participle extractus 'drawn out' becomes the source of the English noun and adjective extract. The thing pulled out could be a passage, a metal or a essence.","cn":"过去分词 extractus“被抽出的”成为英语名词与形容词 extract 的来源。被抽出的东西可以是段落、金属或精华。"},{"era":"ENGLISH -ION","en":"English forms extraction on extract plus -ion, from Latin -io, naming the action. The word appears in the 15th century in alchemy and medicine.","cn":"英语以 extract 加 -ion（来自拉丁 -io，命名动作）构成 extraction。该词 15 世纪见于炼金术与医学。"},{"era":"MINING AND DENTISTRY","en":"From the 18th and 19th centuries extraction spreads to mining and dentistry, where the container is the earth or the jaw.","cn":"18 至 19 世纪，extraction 扩展到采矿与牙科，容器变成大地或下颌。"},{"era":"DATA AND ANCESTRY","en":"The data sense is a 20th-century extension; the ancestry sense, 'of Italian extraction', is older and treats family as the source material.","cn":"数据义是 20 世纪的扩展；血统义 of Italian extraction 更早，把家族当作原料来源。"}]},"similar":{"note":{"en":"The look-alike group shares the tract- stem or the ex- prefix; the near-meaning group all involve taking something out or away, but from different containers.","cn":"形近组共享 tract- 词干或 ex- 前缀；近义组都涉及“取出、拿走”，但容器不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"extract","ipa":"/ˈekstrækt/","tag":"same root, verb and noun","definition":"to draw out, or the substance drawn out. It is the base word; extraction names the action.","definitionCN":"抽出；提取物。它是基础词；extraction 命名动作。"},{"word":"extractive","ipa":"/ɪkˈstræktɪv/","tag":"same root, adjective","definition":"relating to extraction, especially mining and drilling. It describes an industry, not a process step.","definitionCN":"提取的；采掘的，尤指采矿与钻探。它描述产业，不描述某个操作步骤。"},{"word":"extradition","ipa":"/ˌekstrəˈdɪʃn/","tag":"different root: tradere","definition":"the official handing over of a person to another country. It looks close because of extra-, but comes from ex- plus tradere 'hand over', not trahere 'draw'.","definitionCN":"把某人正式移交给另一国。它因 extra- 而形近，但来自 ex- 加 tradere“交出”，并非 trahere“拉”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"removal","ipa":"/rɪˈmuːvl/","tag":"taking away","definition":"the act of taking something away from a place. It is broader than extraction and often implies clearing.","definitionCN":"把某物从某处拿走的行为。它比 extraction 宽泛，常含“清理”之意。"},{"word":"mining","ipa":"/ˈmaɪnɪŋ/","tag":"digging out minerals","definition":"the industry of taking coal, metal or gems from the earth. It is the industrial setting of one extraction sense.","definitionCN":"从地下开采煤、金属或宝石的产业。它是 extraction 某一义项的产业场景。"},{"word":"excerpt","ipa":"/ˈeksɜːpt/","tag":"a passage taken out","definition":"a short piece taken from a book or speech. It is the product, while extraction is the act of taking it.","definitionCN":"从书或讲话中摘取的短段。它是成品，而 extraction 是摘取的动作。"},{"word":"derivation","ipa":"/ˌderɪˈveɪʃn/","tag":"origin or source","definition":"the origin of something, or the process of obtaining it from a source. It overlaps the ancestry sense but sounds more technical.","definitionCN":"某物的来源，或从源头获得的过程。它与“出身”义重叠，但更技术化。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"ex- 'out' + trahere 'draw': extraction is the pull that moves something out of its container.","cn":"ex-“向外”+ trahere“拉”：extraction 就是把东西从容器里往外拉的那一下。"},{"en":"tract, tractor, contract and extraction share the tract- stem, so the family is one memory block.","cn":"tract、tractor、contract、extraction 共享 tract- 词干，可整块记忆。"},{"en":"tooth extraction is the clearest picture: the tooth is not cut, it is pulled out whole.","cn":"tooth extraction 是最清楚的画面：牙不是被削掉，而是整颗被拔出。"},{"en":"extraction rate turns the action into a number, which shows how much of the target actually left.","cn":"extraction rate 把这个动作变成一个数字，显示目标物实际出来了多少。"},{"en":"of Italian extraction uses the same verb for family: a person is drawn from a source.","cn":"of Italian extraction 把同一动词用在家族上：人是从某个源头抽出来的。"}],"abstract":[{"en":"Think of a syringe drawing liquid from a sealed vial, the level falling as the barrel fills.","cn":"想象注射器从密封小瓶里抽液，针筒满起来时瓶里的液面下降。"},{"en":"Think of a single page being lifted out of a thick book and laid on a table.","cn":"想象从一本厚书里抽出一页，单独放在桌上。"},{"en":"Think of a mine shaft as a straw pushed into the ground, with ore rising through it.","cn":"想象矿井是一根插进地里的吸管，矿石从里面升上来。"}]},"examples":[{"en":"The lab reports the extraction yield in milligrams per litre.","cn":"实验室以每升多少毫克报告提取产量。"},{"en":"After the extraction of the second molar, he ate only soft food for a week.","cn":"拔掉第二磨牙后，他一周只吃软食。"},{"en":"The chapter is an extraction from a longer memoir published in 1932.","cn":"这一章摘自 1932 年出版的一部更长回忆录。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“一克斯拽克神”——ex（向外）+ tract（拽）：把东西往外拽出来 → extraction 提取、开采","word":"extraction"},"root":"拉丁 extrahere“抽出”（ex-“向外”+ trahere“拉、拖”，过去分词 tractus）；extract + -ion 构成动作名词。","sensesIntro":{"en":"Eight senses share one direction: something is pulled out of whatever held it, whether earth, body, book or bloodline.","cn":"八个义项共享一个方向：某物被从包住它的东西里拉出来，不论是大地、身体、书本还是血统。"},"semanticMap":{"core":{"en":"CORE IMAGE: a straw drawing juice out of fruit.","cn":"核心意象：一根吸管把果汁从果肉里抽出来。"},"chain":["DRAW OUT","SEPARATE A SUBSTANCE","TAKE FROM THE EARTH","PULL FROM THE BODY","TAKE FROM A TEXT","COME FROM A SOURCE"],"branches":[{"senses":"01 · 07","en":"SUBSTANCE: chemical extraction and the extraction rate are the same separation seen as process and as measurement.","cn":"物质：化学提取与提取率是同一个分离过程，一个看过程，一个看量度。"},{"senses":"02","en":"EARTH: mining treats the ground as the container, with ore drawn upward through the shaft.","cn":"大地：采矿把地面当容器，矿石沿矿井被向上抽出。"},{"senses":"03","en":"BODY: a tooth or bullet is drawn out whole rather than cut away.","cn":"身体：牙齿或子弹是整块被拔出，而不是削掉。"},{"senses":"04 · 06","en":"INFORMATION: a passage and a database row are both selected pieces pulled from a larger store.","cn":"信息：一段文字与一行数据库记录，都是从更大储存中取出的选定片段。"},{"senses":"05 · 08","en":"SOURCE AND FORCE: ancestry is the source one is drawn from, while a forced confession is pulled out of a person against resistance.","cn":"来源与强力：血统是人被抽出的源头，而逼供是违背抵抗从人身上抽出信息。"}]},"affixes":{"intro":{"en":"Extraction is extract plus -ion. The ex- prefix means 'out', the -tract- stem means 'draw', and -ion names the action; -or and -ive build agent and quality nouns.","cn":"extraction 是 extract 加 -ion。ex- 前缀意为“向外”，-tract- 词干意为“拉”，-ion 命名动作；-or 与 -ive 构成施事与性质词。"},"latinIntro":{"en":"The Latin family grows from trahere 'draw' through extrahere 'draw out'. English relatives include extract, tractor, contract, attract and distract, each with its own prefix.","cn":"这个拉丁词族从 trahere“拉”经 extrahere“抽出”生长。英语同族词包括 extract、tractor、contract、attract、distract，各自前缀不同。"},"items":[{"word":"extract","structure":"ex- (out) + trahere (draw)","meaning":"to draw out; the thing drawn out","meaningCN":"抽出；提取物（ex-“向外”+ trahere“拉”）","example":"The machine extracts oil from the seeds.","exampleCN":"这台机器从种子里榨油。"},{"word":"extraction","structure":"extract + -ion (action noun)","meaning":"the act of drawing out","meaningCN":"提取；开采（-ion 动作名词）","example":"Extraction began before sunrise.","exampleCN":"开采在天亮前就开始了。"},{"word":"extractor","structure":"extract + -or (agent or device)","meaning":"a device or person that extracts","meaningCN":"提取器；排气扇（-or 施事或器械）","example":"The kitchen extractor pulls smoke out of the room.","exampleCN":"厨房排风扇把烟抽出房间。"},{"word":"extractive","structure":"extract + -ive (relational adjective)","meaning":"relating to extraction, especially mining","meaningCN":"提取的；采掘的（-ive 关系形容词）","example":"Extractive industries dominate the province.","exampleCN":"采掘业在该省占主导地位。"},{"word":"extractable","structure":"extract + -able (capable of being)","meaning":"able to be drawn out","meaningCN":"可提取的（-able“能够被……”）","example":"Only half of the sugar is extractable by this method.","exampleCN":"用这种方法只能提取出一半的糖。"},{"word":"tractor","structure":"tract- + -or (agent)","meaning":"a vehicle that draws or pulls implements","meaningCN":"拖拉机（tract-“拉”+ -or 施事，同一词根）","example":"The tractor pulled the plough across the field.","exampleCN":"拖拉机拉着犁穿过田地。"},{"word":"contract","structure":"con- (together) + trahere (draw)","meaning":"to draw together, hence a binding agreement","meaningCN":"收缩；合同（con-“共同”+ trahere“拉”，把双方拉到一起）","example":"The two firms signed a three-year contract.","exampleCN":"两家公司签了三年合同。"},{"word":"distract","structure":"dis- (apart) + trahere (draw)","meaning":"to draw attention apart; to divert","meaningCN":"分散注意力（dis-“分开”+ trahere“拉”）","example":"The noise distracted the whole class.","exampleCN":"噪音分散了全班的注意力。"}],"latinEntries":[{"word":"trahere","structure":"trahere (to draw)","meaning":"to draw, drag, pull","meaningCN":"拉；拖；拽"},{"word":"extrahere","structure":"ex- (out) + trahere (draw)","meaning":"to draw out","meaningCN":"抽出；拉出"},{"word":"extractus","structure":"past participle of extrahere","meaning":"having been drawn out","meaningCN":"已被抽出的（过去分词）"},{"word":"tractus","structure":"past participle of trahere","meaning":"a drawing, a stretch","meaningCN":"拉；延伸；地带"}]}},{"word":"facilitation","ipa_uk":"/fəˌsɪlɪˈteɪʃn/","ipa_us":"/fəˌsɪlɪˈteɪʃn/","definition_zh":"促进；便利化；引导；易化","definition_en":"the act of making a process easier or helping a group reach its own conclusions without directing them","core_image":"一个人把沉重的门扶住，让后面的人顺利通过","scene":"Trade facilitation cut the time trucks spend waiting at the border.","sceneCN":"这里 facilitation 是「便利化」（第 1 个义项：让流程更顺畅、成本更低）；句意：贸易便利化缩短了卡车在边境等待的时间。图中可辨识物件：边检亭、货车、通关单、时钟。","pos":[{"tag":"n.","zh":"促进；便利化；引导；（生理）易化"}],"collocations":[{"phrase":"trade facilitation","zh":"贸易便利化"},{"phrase":"facilitation skills","zh":"引导技巧"},{"phrase":"facilitation of trade","zh":"贸易的促进"},{"phrase":"group facilitation","zh":"小组引导"},{"phrase":"neural facilitation","zh":"神经易化"},{"phrase":"facilitation payment","zh":"便利费（贿赂的委婉说法）"}],"forms":[{"label":"复数","form":"facilitations"}],"derivatives":[{"word":"facilitate","pos":"v.","zh":"促进；使便利；引导"},{"word":"facilitator","pos":"n.","zh":"引导者；促进者"},{"word":"facilitative","pos":"adj.","zh":"促进的；助长的"},{"word":"facilitatory","pos":"adj.","zh":"起促进作用的中枢的"},{"word":"facility","pos":"n.","zh":"设施；便利；才能"}],"senses":[{"no":"01","title":"Making a process easier","titleCN":"便利化：让流程少卡几下","definition":"the act of removing obstacles so that a process runs more smoothly","definitionCN":"排除障碍、使过程更顺畅的行为","example":"The facilitation of visa procedures doubled the number of visiting students.","exampleCN":"签证手续的便利化让来访学生人数翻了一番。","why":"facilis means 'easy', from facere 'to do'. Facilitation does not do the work for you; it makes the work easier to do.","whyCN":"facilis 意为“容易”，来自 facere“做”。facilitation 不替你做事，而是让事情更容易做。"},{"no":"02","title":"Guiding a group","titleCN":"引导：不替他们决定，只帮他们谈成","definition":"the work of helping a group discuss and decide while keeping neutral about the outcome","definitionCN":"帮助群体讨论并作出决定、同时对结果保持中立的工作","example":"A trained outsider ran the facilitation of the neighbourhood meeting.","exampleCN":"一位受过训练的外部人员主持了社区会议的引导工作。","why":"The facilitator holds the door, not the destination. This modern sense keeps facilis 'easy' but adds the ethical rule of not steering the group.","whyCN":"引导者扶住门，但不决定门通向哪里。这个现代义保留 facilis“容易”，又加上“不操纵群体”的伦理规则。"},{"no":"03","title":"Helping someone learn","titleCN":"助学：把台阶铺到学生脚下","definition":"in education, the teacher's support that makes learning possible without doing it for the learner","definitionCN":"教育中教师提供的支持，使学习成为可能，但不代替学习者完成","example":"The course trains teachers in the facilitation of small-group discussion.","exampleCN":"该课程训练教师如何引导小组讨论。","why":"Learning is the learner's work. Facilitation supplies the easier path: better questions, clearer materials, a safer room.","whyCN":"学习是学习者自己的事。facilitation 提供更容易的路：更好的问题、更清楚的材料、更安全的房间。"},{"no":"04","title":"Physiology: a lowered threshold","titleCN":"易化：让反应更容易被触发","definition":"in physiology, the process by which a nerve or reflex response becomes easier to elicit","definitionCN":"生理学上指神经或反射反应变得更容易被引发的过程","example":"Repeated stimulation produced facilitation in the spinal pathway.","exampleCN":"反复刺激在脊髓通路中产生了易化。","why":"Here 'easy' becomes measurable: the threshold for a response drops. The same Latin word serves a laboratory fact.","whyCN":"这里“容易”变得可测量：反应阈值下降。同一个拉丁词服务于一项实验室事实。"},{"no":"05","title":"Brokering an agreement","titleCN":"促成：把两边的手拉到一起","definition":"the act of helping two parties reach an agreement without imposing terms","definitionCN":"帮助两方达成协议而不强加条款的行为","example":"His quiet facilitation brought the union and the managers back to the table.","exampleCN":"他低调的促成让工会与资方重回谈判桌。","why":"The broker removes friction rather than adding force. The word keeps the door-holding image: the parties still walk through it themselves.","whyCN":"中间人减少摩擦，而不是施加力量。这个词保留扶门的意象：门还是当事人自己走过去的。"},{"no":"06","title":"Simplifying paperwork","titleCN":"简化手续：把表格减到最少","definition":"the simplification of official procedures and forms","definitionCN":"对官方程序与表格的简化","example":"Customs facilitation reduced the number of forms from nine to two.","exampleCN":"海关手续简化把表格从九张减到两张。","why":"Administration speaks of facilitation when it removes steps. Each removed form is a door held open.","whyCN":"行政上说 facilitation，指的是去掉步骤。每去掉一张表格，就是扶住一扇门。"},{"no":"07","title":"Trade facilitation","titleCN":"贸易便利化：让货物过境更顺","definition":"the specific policy field concerned with lowering the cost of moving goods across borders","definitionCN":"专指降低货物跨境流动成本的政策领域","example":"The agreement's trade facilitation chapter covers customs and transit.","exampleCN":"该协定的贸易便利化章节涵盖海关与过境。","why":"This is the institutional name for the general sense. WTO documents fixed the phrase, giving 'easy' a permanent policy address.","whyCN":"这是总义项的制度化名称。WTO 文件固定了这个说法，让“容易”有了固定的政策地址。"},{"no":"08","title":"The euphemism for a bribe","titleCN":"便利费：给钱让事情快点办","definition":"a payment described as speeding up routine official action, widely treated as a bribe","definitionCN":"被说成加快例行公务的付款，普遍被视为贿赂","example":"The audit found facilitation payments recorded as 'express fees'.","exampleCN":"审计发现便利费被记作“加急费”。","why":"The darker use shows how neutral 'making easy' can be bent: money makes the door open faster, but the door is not yours to open.","whyCN":"这个更黑暗的用法显示中性的“使容易”如何被扭曲：钱让门开得更快，但那扇门不归你开。"}],"etymology":{"intro":{"en":"Facilitation comes from facilitate, from Latin facilitare, built on facilis 'easy'. Facilis itself comes from facere 'to do, make' plus -ilis 'able to be', so 'easy' originally meant 'doable'.","cn":"facilitation 来自 facilitate，而 facilitate 出自拉丁 facilitare，建立在 facilis“容易”之上。facilis 本身来自 facere“做、制作”加 -ilis“能被……”，所以“容易”原义是“做得到”。"},"items":[{"era":"LATIN FACERE","en":"facere meant 'to do, make'. It is one of the most productive Latin roots in English: fact, factor, facility, efficient and difficult all trace back to it.","cn":"facere 意为“做、制作”。它是英语中最能产的拉丁词根之一：fact、factor、facility、efficient、difficult 都能追溯到这里。"},{"era":"LATIN FACILIS","en":"facilis 'easy, doable' joins facere with -ilis 'able to be'. The word describes what can be done without great effort, not what requires no effort.","cn":"facilis“容易的、做得到的”由 facere 加 -ilis“能被……”构成。它描述不用太大功夫就能做到的事，而不是完全不用功夫的事。"},{"era":"LATIN FACILITAS","en":"facilitas meant 'ease, easiness' and also 'ability'. The abstract noun shows that 'easy' and 'capable' were once one idea.","cn":"facilitas 意为“容易、轻松”，也指“能力”。这个抽象名词显示“容易”与“有能力”曾是同一个观念。"},{"era":"LATIN FACILITARE","en":"facilitare 'to make easy' turns the adjective into a verb. The shift from being easy to making easy is the seed of the modern sense.","cn":"facilitare“使容易”把形容词变成动词。从“容易”到“使容易”，正是现代义的种子。"},{"era":"ENGLISH FACILITATE","en":"English facilitate appears in the 16th century meaning 'to make easy'. The group-process sense, 'to guide without directing', is a 20th-century development.","cn":"英语 facilitate 于 16 世纪出现，意为“使容易”。而“引导但不操纵”的群体过程义是 20 世纪的发展。"},{"era":"POLICY AND PHYSIOLOGY","en":"Trade facilitation becomes a fixed policy term in the late 20th century, while neural facilitation is an older laboratory usage in physiology.","cn":"贸易便利化在 20 世纪末成为固定政策术语，而神经易化是生理学中更早的实验室用法。"}]},"similar":{"note":{"en":"The look-alike group shares the fac- root or the -ilit- shape but splits by suffix; the near-meaning group all involve helping, with different degrees of control.","cn":"形近组共享 fac- 词根或 -ilit- 外形，但按后缀分流；近义组都涉及“帮助”，控制程度不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"facilitate","ipa":"/fəˈsɪlɪteɪt/","tag":"same root, verb","definition":"to make easier or to guide. It is the action; facilitation is the act or process as a noun.","definitionCN":"使容易；引导。它是动作；facilitation 是作为名词的动作或过程。"},{"word":"facility","ipa":"/fəˈsɪləti/","tag":"same root, different noun","definition":"a place or equipment that makes an activity possible; also ease or aptitude. It names the means, not the helping act.","definitionCN":"使活动成为可能的场所或设备；也指轻松、才能。它命名手段，不是帮助行为。"},{"word":"felicitation","ipa":"/fəˌlɪsɪˈteɪʃn/","tag":"different root: felix","definition":"an expression of congratulations. It looks and sounds close but comes from felix 'happy', not from facilis 'easy'.","definitionCN":"祝贺的话。它形音都接近，但来自 felix“幸福的”，并非 facilis“容易的”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"assistance","ipa":"/əˈsɪstəns/","tag":"help given","definition":"help with a task. It can involve doing part of the work, while facilitation usually leaves the work with the participants.","definitionCN":"对任务的帮助。它可能包含替做一部分，而 facilitation 通常把工作留给参与者。"},{"word":"enablement","ipa":"/ɪˈneɪblmənt/","tag":"making possible","definition":"the act of giving someone the means or power to do something. It is broader and often technical.","definitionCN":"给予某人做某事的手段或能力。它更宽泛，常带技术色彩。"},{"word":"mediation","ipa":"/ˌmiːdiˈeɪʃn/","tag":"settling between parties","definition":"helping two sides reach agreement by talking between them. It is a specific form of facilitation with a settlement goal.","definitionCN":"在双方之间斡旋以达成协议。它是有“达成和解”目标的特定引导形式。"},{"word":"promotion","ipa":"/prəˈməʊʃn/","tag":"pushing something forward","definition":"the act of encouraging or advancing something. It may actively push, while facilitation removes obstacles.","definitionCN":"鼓励或推进某事的行为。它可能主动推动，而 facilitation 是排除障碍。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"facilis 'easy' comes from facere 'do': facilitation makes a thing doable rather than doing it for you.","cn":"facilis“容易”来自 facere“做”：facilitation 让事情做得到，而不是替你做。"},{"en":"facilitate, facilitator, facility and facilitation share the fac- stem, so one root covers the family.","cn":"facilitate、facilitator、facility、facilitation 共享 fac- 词干，一个词根覆盖全家。"},{"en":"trade facilitation is the policy name, and group facilitation is the meeting-room name; same door held open.","cn":"trade facilitation 是政策名称，group facilitation 是会议室里的名称；都是同一扇被扶住的门。"},{"en":"A facilitator is neutral about the outcome, which is what separates facilitation from mediation.","cn":"facilitator 对结果保持中立，这正是 facilitation 与 mediation 的分界。"},{"en":"Do not confuse felicitation with facilitation: one wishes you happiness, the other makes the work easier.","cn":"别把 felicitation 与 facilitation 混淆：一个祝你好运，一个让工作更容易。"}],"abstract":[{"en":"Think of a hand holding a heavy door while someone else walks through.","cn":"想象一只手扶住一扇重门，另一个人从门里走过去。"},{"en":"Think of stones removed from a path one by one, until the cart can roll on its own.","cn":"想象把路上的石头一块块搬走，直到车能自己滚过去。"},{"en":"Think of a guide-rail along a cliff: it does not walk for you, it keeps you from falling.","cn":"想象悬崖边的护栏：它不替你走路，只让你不掉下去。"}]},"examples":[{"en":"The facilitation of cross-border payments saved small exporters both time and fees.","cn":"跨境支付的便利化为小出口商节省了时间和费用。"},{"en":"Good facilitation leaves the group feeling that the decision was its own.","cn":"好的引导会让小组觉得决定是自己作出的。"},{"en":"The study measured neural facilitation after repeated stimulation.","cn":"该研究测量了反复刺激后的神经易化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“扶（facil）你上楼梯”——扶着你、让你更容易走上去 → facilitation 促进、便利化","word":"facilitation"},"root":"拉丁 facilis“容易的”（facere“做”+ -ilis“能被……”）→ facilitare“使容易” → facilitate + -ion；核心仍是“让事情做得到”。","sensesIntro":{"en":"Eight senses share one gesture: a hand holds a door or removes a stone, but the traveller still walks through alone.","cn":"八个义项共享一个动作：一只手扶住门或搬走石头，但走路的人仍要自己走过去。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand holding a heavy door open.","cn":"核心意象：一只手扶住沉重的门。"},"chain":["MAKE EASY","REMOVE OBSTACLES","HOLD THE SPACE","LOWER THE THRESHOLD","BROKER AGREEMENT","SPEED THE PAPERWORK"],"branches":[{"senses":"01 · 06 · 07","en":"PROCESS: easing a procedure, simplifying forms and trade facilitation are one removal of steps at three scales.","cn":"流程：便利化程序、简化表格与贸易便利化，是三个尺度上同一种“去掉步骤”。"},{"senses":"02 · 05","en":"GROUP WORK: guiding a meeting and brokering a deal both hold the space without choosing the outcome.","cn":"群体工作：引导会议与促成协议，都扶住空间却不选择结果。"},{"senses":"03","en":"LEARNING: the teacher builds the easier path but does not walk it for the student.","cn":"学习：教师铺出更容易的路，但不替学生走。"},{"senses":"04","en":"PHYSIOLOGY: 'easy' becomes a lowered threshold for a nerve response.","cn":"生理：这里的“容易”变成神经反应阈值的下降。"},{"senses":"08","en":"EUPHEMISM: a payment that makes the door open faster shows the same image bent to a bribe.","cn":"委婉语：让门开得更快的付款，把同一意象扭成了贿赂。"}]},"affixes":{"intro":{"en":"Facilitation is facilitate plus -ion. The fac- stem means 'do, make', -ilis means 'able to be', -ate makes a verb and -ion names the action.","cn":"facilitation 是 facilitate 加 -ion。fac- 词干意为“做、制作”，-ilis 意为“能被……”，-ate 构成动词，-ion 命名动作。"},"latinIntro":{"en":"The family runs from facere 'do' to facilis 'easy' to facilitas 'ease' to facilitare 'make easy'. English relatives include facility, facilitate, fact and factor.","cn":"这个词族从 facere“做”到 facilis“容易”到 facilitas“轻松”再到 facilitare“使容易”。英语同族词包括 facility、facilitate、fact、factor。"},"items":[{"word":"facilitate","structure":"facilis + -ate (verb)","meaning":"to make easier; to help forward","meaningCN":"促进；使便利（-ate 动词后缀）","example":"The new software facilitates group editing.","exampleCN":"新软件方便了多人协同编辑。"},{"word":"facilitation","structure":"facilitate + -ion (action noun)","meaning":"the act of making easier","meaningCN":"促进；便利化（-ion 动作名词）","example":"Facilitation of the talks took two weeks.","exampleCN":"会谈的促成工作花了两周。"},{"word":"facilitator","structure":"facilitate + -or (person noun)","meaning":"a person who guides a group neutrally","meaningCN":"引导者（-or 施事名词）","example":"The facilitator wrote every idea on the board.","exampleCN":"引导者把每个想法都写在白板上。"},{"word":"facility","structure":"facilis + -ity (quality noun)","meaning":"ease; aptitude; a place or service","meaningCN":"容易；才能；设施（-ity 性质名词，来自 facilitas）","example":"She plays the violin with great facility.","exampleCN":"她拉小提琴非常娴熟。"},{"word":"facilitative","structure":"facilitate + -ive (tendency)","meaning":"tending to make things easier","meaningCN":"促进的；助长的（-ive 性质形容词）","example":"The teacher used a facilitative style of questioning.","exampleCN":"教师采用了促进式的提问风格。"},{"word":"facilitatory","structure":"facilitate + -ory (serving for)","meaning":"serving to facilitate, often in physiology","meaningCN":"起促进作用的（-ory“用于……”；生理学常用）","example":"The facilitatory pathway lowers the response threshold.","exampleCN":"易化通路降低了反应阈值。"},{"word":"fact","structure":"facere + -tum (thing done)","meaning":"something done or known to be true","meaningCN":"事实（facere 的中性过去分词 factum“已做成之事”）","example":"The fact was checked twice.","exampleCN":"这个事实被核对了两遍。"},{"word":"difficult","structure":"dis- (not) + facilis (easy)","meaning":"not easy to do","meaningCN":"困难的（dis-“不”+ facilis“容易”，与 facilitation 同一词根）","example":"The final question was the most difficult.","exampleCN":"最后一道题是最难的。"}],"latinEntries":[{"word":"facere","structure":"facere (to do, make)","meaning":"to do, make","meaningCN":"做；制作"},{"word":"facilis","structure":"facere + -ilis (able to be)","meaning":"easy, doable","meaningCN":"容易的；做得到的"},{"word":"facilitas","structure":"facilis + -itas (quality)","meaning":"ease, ability","meaningCN":"容易；能力"},{"word":"facilitare","structure":"facilitas + -are (verb)","meaning":"to make easy","meaningCN":"使容易；促进"}]}},{"word":"factorization","ipa_uk":"/ˌfæktəraɪˈzeɪʃn/","ipa_us":"/ˌfæktərəˈzeɪʃn/","definition_zh":"因式分解；因子分解","definition_en":"the process of breaking a number or expression into factors that multiply back to the original","core_image":"一堆积木被拆成几组相同的零件，每组都能重新拼回原样","scene":"Prime factorization writes 84 as 2 × 2 × 3 × 7, and no other primes will do.","sceneCN":"这里 factorization 是「质因数分解」（第 2 个义项：把整数拆成质数乘积）；句意：84 的质因数分解是 2×2×3×7，换成别的质数都拼不回来。图中可辨识物件：数字方块、乘号、分解树。","pos":[{"tag":"n.","zh":"因式分解；因子分解"}],"collocations":[{"phrase":"prime factorization","zh":"质因数分解"},{"phrase":"integer factorization","zh":"整数分解"},{"phrase":"polynomial factorization","zh":"多项式因式分解"},{"phrase":"matrix factorization","zh":"矩阵分解"},{"phrase":"unique factorization","zh":"唯一分解"},{"phrase":"factorization algorithm","zh":"分解算法"}],"forms":[{"label":"复数","form":"factorizations"}],"derivatives":[{"word":"factor","pos":"n./v.","zh":"因数；因素；把……分解成因式"},{"word":"factorize","pos":"v.","zh":"因式分解；把……分解"},{"word":"factorable","pos":"adj.","zh":"可分解的"},{"word":"factorial","pos":"n./adj.","zh":"阶乘；因子的"},{"word":"factoring","pos":"n.","zh":"因式分解；保理业务"}],"senses":[{"no":"01","title":"Breaking an expression apart","titleCN":"因式分解：把式子拆成能乘回去的块","definition":"the process of writing an algebraic expression as a product of simpler expressions","definitionCN":"把一个代数式写成若干个更简单式子之积的过程","example":"Factorization of x squared minus 9 gives (x minus 3)(x plus 3).","exampleCN":"x 平方减 9 的因式分解是 (x 减 3)(x 加 3)。","why":"factor means 'maker'. Factorization asks which makers, multiplied together, produced this expression, so the answer rebuilds the original.","whyCN":"factor 意为“制作者”。因式分解问的是哪几个“制作者”相乘得到了这个式子，因此答案能重建原式。"},{"no":"02","title":"Prime factorization","titleCN":"质因数分解：拆到不能再拆","definition":"the expression of a whole number as a product of prime numbers","definitionCN":"把一个整数表示成质数乘积","example":"The prime factorization of 84 is 2 × 2 × 3 × 7.","exampleCN":"84 的质因数分解是 2×2×3×7。","why":"Primes are the atoms of arithmetic. Factorization stops when every factor is prime, because a prime cannot be broken further.","whyCN":"质数是算术的原子。当每个因子都是质数时分解就停止，因为质数不能再拆。"},{"no":"03","title":"Unique factorization","titleCN":"唯一分解：答案只有一种","definition":"the theorem that every integer above one has exactly one prime factorization apart from order","definitionCN":"每个大于 1 的整数除顺序外只有一种质因数分解的定理","example":"Unique factorization is why 84 cannot be built from a different set of primes.","exampleCN":"唯一分解正是 84 无法由另一组质数拼成的原因。","why":"The theorem turns a procedure into a law. Order does not matter because multiplication is commutative, but the set of primes is fixed.","whyCN":"这一定理把操作变成定律。顺序无关紧要，因为乘法可交换，但质数集合是固定的。"},{"no":"04","title":"Polynomial factorization","titleCN":"多项式分解：把长式子拆成括号","definition":"the factorization of polynomials into products of lower-degree polynomials","definitionCN":"把多项式分解为次数更低的多项式之积","example":"Polynomial factorization is the first step in solving many equations.","exampleCN":"多项式因式分解是解许多方程的第一步。","why":"The same question is asked of expressions rather than numbers: what simpler pieces multiply to this? Degree is the measure of complexity.","whyCN":"同样的问题被用在式子上而非数字上：哪些更简单的块相乘得到它？次数就是复杂度的量度。"},{"no":"05","title":"Matrix factorization","titleCN":"矩阵分解：把大表拆成两张小表","definition":"the decomposition of a matrix into a product of two or more matrices","definitionCN":"把一个矩阵分解为两个或多个矩阵之积","example":"Matrix factorization compresses a large rating table into two smaller ones.","exampleCN":"矩阵分解把一张大的评分表压缩成两张较小的表。","why":"Matrices are arrays of numbers, and factorization finds hidden structure inside them. The product rule stays the same; the objects grow larger.","whyCN":"矩阵是数字阵列，分解在其中找出隐藏结构。乘积规则不变，只是对象变大了。"},{"no":"06","title":"A hard computational problem","titleCN":"整数分解问题：拆大数非常费力","definition":"the computational task of finding the prime factors of a large integer","definitionCN":"寻找大整数质因数这一计算任务","example":"The security of RSA rests on the difficulty of integer factorization.","exampleCN":"RSA 的安全性建立在整数分解的难度上。","why":"Here factorization names a problem rather than a result. Multiplying is fast, but reversing the multiplication is slow, and that asymmetry protects codes.","whyCN":"这里 factorization 命名的是一个难题而非结果。相乘很快，反向拆开很慢，这种不对称保护着密码。"},{"no":"07","title":"Breaking a problem into parts","titleCN":"拆解：把复杂问题分成几块","definition":"the general act of separating something complex into components that can be handled separately","definitionCN":"把复杂事物分成可分别处理的组成部分的一般行为","example":"The team's factorization of the budget revealed three independent cost drivers.","exampleCN":"团队对预算的拆解揭示了三个独立的成本驱动因素。","why":"Outside mathematics the word keeps the rebuild test: the parts must multiply back to the whole, or the breakdown was wrong.","whyCN":"在数学之外，这个词仍保留“能拼回去”的检验：各部分必须能乘回整体，否则拆法就是错的。"},{"no":"08","title":"Why codes depend on it","titleCN":"密码依赖：拆不开才安全","definition":"the use of the difficulty of factorization to protect encrypted messages","definitionCN":"利用分解之困难来保护加密信息","example":"A quantum computer could make some factorization tasks easy and break current ciphers.","exampleCN":"量子计算机可能让某些分解任务变容易，从而破解现有密码。","why":"The word's technical weight comes from this use: a lock is strong when the reverse operation is practically impossible.","whyCN":"这个词的技术分量来自这一用途：当逆向操作实际上不可能时，锁才是牢的。"}],"etymology":{"intro":{"en":"Factorization is factorize plus -ation. Factor comes from Latin factor 'doer, maker', built on facere 'to do, make'. In arithmetic a factor is what 'makes' a product by multiplying.","cn":"factorization 是 factorize 加 -ation。factor 来自拉丁 factor“做者、制作者”，建立在 facere“做、制作”之上。在算术里，因数就是通过相乘“造出”乘积的东西。"},"items":[{"era":"LATIN FACERE","en":"facere 'to do, make' is the root of factor. The same root gives fact, facility and difficult, but each takes a different suffix or prefix.","cn":"facere“做、制作”是 factor 的词根。同一词根生出 fact、facility、difficult，但各自带不同后缀或前缀。"},{"era":"LATIN FACTOR","en":"factor meant 'one who does or makes'. In commerce it became a person who acts for another, which is why English factor also means a business agent.","cn":"factor 意为“做事或制作的人”。在商业中它变成替他人行事的人，因此英语 factor 也指代理商。"},{"era":"ARITHMETIC FACTOR","en":"The mathematical sense, 'a number that multiplies with another to give a product', develops later. It treats each number as a maker of the product.","cn":"数学义“与另一数相乘得到乘积的数”后来发展出来。它把每个数当作乘积的“制作者”。"},{"era":"ENGLISH FACTORIZE","en":"English factorize appears in the 19th century as the verb for resolving into factors. The suffix -ize marks the action of making or converting.","cn":"英语 factorize 于 19 世纪出现，指把式子分解为因数的动词。-ize 标记“使成为、转换”的动作。"},{"era":"ENGLISH -ATION","en":"Factorization adds -ation, from Latin -atio, naming the process. The word is thus an English construction on a Latin base, not a direct Latin noun.","cn":"factorization 再加 -ation（来自拉丁 -atio，命名过程）。因此这个词是在拉丁词基上的英语构造，不是直接的拉丁名词。"},{"era":"COMPUTING ERA","en":"In the 20th century integer factorization becomes a central computational problem, and the word gains weight in cryptography.","cn":"20 世纪整数分解成为核心计算问题，这个词在密码学中获得分量。"}]},"similar":{"note":{"en":"The look-alike group shares the fact- stem but only the first two share the arithmetic sense; the near-meaning group all involve breaking a whole into parts.","cn":"形近组共享 fact- 词干，但只有前两个共享算术义；近义组都涉及把整体拆成部分。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"factor","ipa":"/ˈfæktə(r)/","tag":"same root, unit noun","definition":"a number or element that multiplies with others; also an agent or cause. It is the unit; factorization is the process.","definitionCN":"与其它数相乘的数或要素；也指代理人、原因。它是单位，factorization 是过程。"},{"word":"factorize","ipa":"/ˈfæktəraɪz/","tag":"same root, verb","definition":"to break into factors. It is the action that the noun names.","definitionCN":"把……分解成因式。它是名词所命名的动作。"},{"word":"factory","ipa":"/ˈfæktri/","tag":"same root, place noun","definition":"a building where goods are made. It comes from factor plus -y 'place', so it shares the 'making' root but has nothing to do with arithmetic.","definitionCN":"制造货物的场所。它由 factor 加 -y“场所”构成，共享“制作”词根，却与算术无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"decomposition","ipa":"/ˌdiːkɒmpəˈzɪʃn/","tag":"breaking into parts","definition":"the process of separating into constituent parts. It is close, but often implies decay or chemical breakdown.","definitionCN":"分离成组成部分的过程。它接近，但常含腐烂或化学分解之意。"},{"word":"resolution","ipa":"/ˌrezəˈluːʃn/","tag":"resolving into parts","definition":"the act of resolving something into components, especially in mathematics. It is more formal than factorization.","definitionCN":"把某物解析成组成部分，尤用于数学。它比 factorization 更正式。"},{"word":"analysis","ipa":"/əˈnæləsɪs/","tag":"examining the parts","definition":"the detailed examination of the elements of something. It studies the parts rather than proving they multiply back.","definitionCN":"对某物各要素的细致检查。它研究部分，而不证明部分能乘回整体。"},{"word":"breakdown","ipa":"/ˈbreɪkdaʊn/","tag":"separation into groups","definition":"a division of something into categories or steps. It is informal and need not be reversible.","definitionCN":"把某物分成类别或步骤。它口语化，且不必可逆。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"factor means 'maker': factorization lists the makers whose product rebuilds the original.","cn":"factor 意为“制作者”：因式分解列出那些相乘后能重建原式的“制作者”。"},{"en":"prime factorization stops at primes because primes are the atoms of arithmetic.","cn":"质因数分解止于质数，因为质数是算术的原子。"},{"en":"factor, factorize, factorization and factory share the fac- 'make' root, though only the first three are mathematical.","cn":"factor、factorize、factorization、factory 共享 fac-“制作”词根，但只有前三个属数学。"},{"en":"RSA security is integer factorization in reverse: easy to multiply, hard to split.","cn":"RSA 安全就是整数分解的反面：乘起来容易，拆开来难。"},{"en":"Unique factorization is the guarantee that the answer has only one prime set, so you cannot 'almost' be right.","cn":"唯一分解保证答案只有一组质数，因此不存在“差一点对”。"}],"abstract":[{"en":"Think of a tower of blocks taken apart into identical smaller blocks that rebuild the same tower.","cn":"想象一堆积木被拆成相同的更小块，而这些小块能重新拼出同一座塔。"},{"en":"Think of a family tree read upward: every person is a product of two parents, and the tree is the factorization.","cn":"想象把家谱向上读：每个人都是两位父母的“乘积”，家谱就是那套分解。"},{"en":"Think of a locked box whose key is the list of prime factors; without the list the box stays shut.","cn":"想象一只锁着的盒子，钥匙就是那串质因数；没有这串数，盒子打不开。"}]},"examples":[{"en":"The worksheet asks for the factorization of six quadratic expressions.","cn":"这份练习要求对六个二次式作因式分解。"},{"en":"Integer factorization is easy for small numbers and hard for large ones.","cn":"整数分解对小数字容易，对大数字很难。"},{"en":"Matrix factorization is widely used in recommender systems.","cn":"矩阵分解广泛用于推荐系统。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“fact 做 + 分解”——factor 是“做乘积的零件”，把乘积拆回零件 → factorization 因式分解","word":"factorization"},"root":"拉丁 facere“做、制作” → factor“制作者、因数” → 英语 factorize + -ation；核心是“找出相乘能重建原式的那些因数”。","sensesIntro":{"en":"Eight senses share one test: the parts must multiply back to the whole, or the breakdown is wrong.","cn":"八个义项共享一个检验：各部分必须能乘回整体，否则拆法就是错的。"},"semanticMap":{"core":{"en":"CORE IMAGE: blocks taken apart and rebuilt into the same tower.","cn":"核心意象：积木被拆开，又能拼回同一座塔。"},"chain":["BREAK INTO FACTORS","STOP AT PRIMES","PROVE THE SET IS UNIQUE","FACTOR EXPRESSIONS","FACTOR MATRICES","HARD COMPUTATION"],"branches":[{"senses":"01 · 04","en":"EXPRESSIONS: algebra and polynomials ask the same rebuilding question at different levels of complexity.","cn":"式子：代数式与多项式在复杂度不同的层级上问同一个“能拼回去”的问题。"},{"senses":"02 · 03","en":"PRIMES: breaking until primes and proving the set unique are the procedure and its guarantee.","cn":"质数：拆到质数为止，以及证明集合唯一，是操作与其保证。"},{"senses":"05","en":"MATRICES: factorization finds hidden structure inside an array, with the same product rule.","cn":"矩阵：分解在阵列内部找出隐藏结构，乘积规则不变。"},{"senses":"06 · 08","en":"CRYPTOGRAPHY: the difficulty of integer factorization and its use in ciphers turn the process into a lock.","cn":"密码学：整数分解的困难及其在密码中的用途，把这一过程变成一把锁。"},{"senses":"07","en":"GENERAL BREAKDOWN: outside mathematics the rebuild test still decides whether the split was valid.","cn":"一般拆解：在数学之外，“能否拼回”仍决定拆法是否成立。"}]},"affixes":{"intro":{"en":"Factorization is factorize plus -ation. The fac- stem means 'make', -or marks the maker, -ize makes a verb and -ation names the process.","cn":"factorization 是 factorize 加 -ation。fac- 词干意为“制作”，-or 标记制作者，-ize 构成动词，-ation 命名过程。"},"latinIntro":{"en":"The family grows from facere 'do, make' through factor 'maker'. English builds factor, factorize and factorization on that stem; factory is a place noun from the same base.","cn":"这个词族从 facere“做、制作”经 factor“制作者”生长。英语在该词干上构成 factor、factorize、factorization；factory 是同词基的场所名词。"},"items":[{"word":"factor","structure":"facere + -or (agent noun)","meaning":"a maker; a number that multiplies; a cause","meaningCN":"制作者；因数；因素（-or 施事名词）","example":"Three factors explain the change.","exampleCN":"三个因素解释了这一变化。"},{"word":"factorize","structure":"factor + -ize (make verb)","meaning":"to resolve into factors","meaningCN":"因式分解（-ize 使动动词）","example":"Factorize the expression before solving it.","exampleCN":"解之前先把式子因式分解。"},{"word":"factorization","structure":"factorize + -ation (process noun)","meaning":"the process of resolving into factors","meaningCN":"因式分解（-ation 过程名词）","example":"Factorization simplified the equation.","exampleCN":"因式分解简化了方程。"},{"word":"factorable","structure":"factor + -able (capable of being)","meaning":"able to be factorized","meaningCN":"可分解的（-able“能够被……”）","example":"Not every polynomial is factorable over the integers.","exampleCN":"并非每个多项式都能在整数上分解。"},{"word":"factorial","structure":"factor + -ial (relational adjective)","meaning":"the product of all integers up to a given number","meaningCN":"阶乘；因子的（-ial 关系形容词，与 factor 同一词基）","example":"Five factorial equals one hundred twenty.","exampleCN":"5 的阶乘等于 120。"},{"word":"factory","structure":"factor + -y (place noun)","meaning":"a place where goods are made","meaningCN":"工厂（factor“制作者”+ -y“场所”）","example":"The factory runs three shifts.","exampleCN":"这家工厂三班倒。"},{"word":"factoring","structure":"factor + -ing (action noun)","meaning":"factorization; also selling invoices for cash","meaningCN":"因式分解；保理（-ing 动作名词，商业义另立）","example":"Factoring the invoice freed up cash quickly.","exampleCN":"发票保理迅速释放了现金。"},{"word":"fact","structure":"facere + -tum (thing done)","meaning":"something done or established","meaningCN":"事实（facere 的过去分词 factum“已做成之事”）","example":"The fact is recorded in the minutes.","exampleCN":"这一事实记录在会议纪要里。"}],"latinEntries":[{"word":"facere","structure":"facere (to do, make)","meaning":"to do, make","meaningCN":"做；制作"},{"word":"factor","structure":"facere + -or (agent)","meaning":"a doer, a maker","meaningCN":"做者；制作者"},{"word":"factum","structure":"past participle of facere","meaning":"a thing done","meaningCN":"已做成之事；事实"},{"word":"factio","structure":"fact- + -io (action noun)","meaning":"a making, a faction","meaningCN":"制作；派系（语义另分）"}]}},{"word":"feasibility","ipa_uk":"/ˌfiːzəˈbɪləti/","ipa_us":"/ˌfiːzəˈbɪləti/","definition_zh":"可行性；可实现性","definition_en":"the quality of being possible to do in practice, given time, money and technical limits","core_image":"一张图纸旁边放着预算表、日历和材料清单，三样都被打上对勾","scene":"Before building the bridge, the council ordered a feasibility study on cost and soil.","sceneCN":"这里 feasibility 是「可行性」（第 1 个义项：在现实中能否做成）；句意：建桥之前，市政会委托做了成本与土质的可行性研究。图中可辨识物件：桥梁草图、预算表、土壤样本、日历。","pos":[{"tag":"n.","zh":"可行性；可实现性"}],"collocations":[{"phrase":"feasibility study","zh":"可行性研究"},{"phrase":"technical feasibility","zh":"技术可行性"},{"phrase":"financial feasibility","zh":"财务可行性"},{"phrase":"assess feasibility","zh":"评估可行性"},{"phrase":"feasibility analysis","zh":"可行性分析"},{"phrase":"economic feasibility","zh":"经济可行性"}],"forms":[{"label":"复数","form":"feasibilities（罕用）"}],"derivatives":[{"word":"feasible","pos":"adj.","zh":"可行的；行得通的"},{"word":"feasibly","pos":"adv.","zh":"可行地；可能地"},{"word":"infeasible","pos":"adj.","zh":"不可行的"},{"word":"infeasibility","pos":"n.","zh":"不可行性"},{"word":"feasibleness","pos":"n.","zh":"可行性（罕用，同 feasibility）"}],"senses":[{"no":"01","title":"Practical possibility","titleCN":"可行性：现实中做不做得到","definition":"whether something can actually be done with the resources and conditions available","definitionCN":"在现有资源与条件下某事是否真的能做到","example":"The feasibility of the plan depends on whether the land can be drained.","exampleCN":"该计划的可行性取决于那块地能否排水。","why":"feasible means 'doable'. Feasibility is simply doability measured against real limits, not against desire.","whyCN":"feasible 意为“做得到的”。feasibility 就是对照真实限制来衡量的“做得到程度”，而不是对照愿望。"},{"no":"02","title":"The study that answers it","titleCN":"可行性研究：先算账再动手","definition":"a formal investigation that estimates whether a proposed project can succeed","definitionCN":"正式调查，用以估计拟议项目能否成功","example":"The feasibility study found that the tunnel would cost twice the original estimate.","exampleCN":"可行性研究发现这条隧道的成本会是原估算的两倍。","why":"The study is named after the question it answers. Feasibility here is the object of research, not a vague hope.","whyCN":"这项研究以它回答的问题命名。这里的 feasibility 是研究对象，不是模糊的希望。"},{"no":"03","title":"Technical feasibility","titleCN":"技术可行性：现有技术够不够","definition":"whether current tools and knowledge can achieve the result","definitionCN":"现有工具与知识能否实现该结果","example":"Technical feasibility was proven in the lab, but scaling up failed.","exampleCN":"技术可行性在实验室得到证明，但放大生产失败了。","why":"This sense isolates one kind of limit. Something can be desirable and legal while still being impossible to build with today's methods.","whyCN":"这一义项单独考察一类限制。一件事可以既令人向往又合法，却仍无法用今天的方法造出来。"},{"no":"04","title":"Financial feasibility","titleCN":"财务可行性：钱够不够撑到回本","definition":"whether the money needed can be raised and repaid within the expected return","definitionCN":"所需资金能否筹集，并在预期回报内偿还","example":"The project passed technical review but failed financial feasibility.","exampleCN":"项目通过了技术评审，却没通过财务可行性。","why":"Here the limit is cash flow. A doable thing is still not feasible if it cannot pay for itself in time.","whyCN":"这里的限制是现金流。一件做得到的事，若不能及时回本，仍然不可行。"},{"no":"05","title":"Legal feasibility","titleCN":"法规可行性：允不允许做","definition":"whether the proposal is permitted by law and regulation","definitionCN":"该方案是否为法律与法规所允许","example":"Legal feasibility ruled out building inside the protected wetland.","exampleCN":"法规可行性排除了在受保护湿地内建楼的可能。","why":"The word expands from physical ability to permission. A wall you cannot legally cross is as real as a wall you cannot physically cross.","whyCN":"这个词从“身体上能否”扩展到“是否被允许”。法律上不能越过的墙，与物理上不能越过的墙一样真实。"},{"no":"06","title":"How workable a design is","titleCN":"可实施程度：方案落地的难易","definition":"the degree to which a design or method can be put into practice without major change","definitionCN":"某个设计或方法无需大改即可付诸实践的程度","example":"The committee questioned the feasibility of the schedule rather than the idea.","exampleCN":"委员会质疑的是时间表的可实施性，而不是想法本身。","why":"Feasibility here is a scale, not a yes or no. Some plans are barely feasible, needing every condition to hold.","whyCN":"这里的 feasibility 是一个尺度，而非是非题。有些计划只是勉强可行，需要所有条件同时成立。"},{"no":"07","title":"Computational feasibility","titleCN":"计算可行性：机器算不算得完","definition":"whether an algorithm can finish within realistic time and memory limits","definitionCN":"算法能否在现实的时间与内存限制内完成","example":"The method is correct but lacks computational feasibility for large graphs.","exampleCN":"该方法正确，但对大图缺乏计算可行性。","why":"Computer science borrows the word for resources that are not money: time and memory. A proof can exist while the computation cannot finish.","whyCN":"计算机科学借这个词指非金钱资源：时间与内存。证明可以存在，而计算却跑不完。"},{"no":"08","title":"Engineering feasibility","titleCN":"工程可行性：能不能造出来","definition":"whether a structure or machine can be built and operated safely with available materials","definitionCN":"用现有材料能否安全建造并运行某结构或机器","example":"Engineering feasibility improved once the new alloy became available.","exampleCN":"新合金问世后，工程可行性提高了。","why":"Engineering brings the physical sense back to the foreground: loads, materials, tolerances. The question is whether the thing stands up.","whyCN":"工程学把物理义拉回前台：荷载、材料、公差。问题在于这东西立不立得住。"}],"etymology":{"intro":{"en":"Feasibility is feasible plus -ity. Feasible comes through French faisable from faire 'to do', which descends from Latin facere 'to do, make'. The -able suffix means 'capable of being'.","cn":"feasibility 是 feasible 加 -ity。feasible 经法语 faisable 来自 faire“做”，而 faire 又源自拉丁 facere“做、制作”。-able 后缀意为“能够被……”。"},"items":[{"era":"LATIN FACERE","en":"facere 'to do, make' is the remote source. It also gives factor, facility, effect and difficult, so the family is large and split by suffix.","cn":"facere“做、制作”是远源。它也生出 factor、facility、effect、difficult，因此这个词族很大，并按后缀分流。"},{"era":"FRENCH FAIRE","en":"French faire 'to do' continues Latin facere. English feasible comes through the French adjective faisable rather than directly from Latin.","cn":"法语 faire“做”延续了拉丁 facere。英语 feasible 是经法语形容词 faisable 进入的，而非直接来自拉丁。"},{"era":"FRENCH FAISABLE","en":"faisable meant 'that can be done'. The suffix -able, from Latin -abilis, marks capability, so the word is about ability, not certainty.","cn":"faisable 意为“能做成的”。后缀 -able（来自拉丁 -abilis）标记能力，因此这个词讲的是“能不能”，不是“一定成”。"},{"era":"ENGLISH FEASIBLE","en":"English adopts feasible in the 16th century. Early spellings included faisable and feasible, and the meaning stayed 'practicable'.","cn":"英语于 16 世纪引入 feasible。早期拼写包括 faisable 与 feasible，词义一直是“可实行的”。"},{"era":"ENGLISH -ITY","en":"Feasibility adds -ity from Latin -itas, forming the abstract quality. The noun appears later than the adjective and is common in engineering and commerce.","cn":"feasibility 加 -ity（来自拉丁 -itas）构成抽象性质名词。名词晚于形容词出现，常见于工程与商业语境。"},{"era":"PROJECT LANGUAGE","en":"In the 20th century feasibility becomes a fixed stage in project planning, giving rise to the standard phrase feasibility study.","cn":"20 世纪 feasibility 成为项目规划的固定阶段，形成标准说法 feasibility study。"}]},"similar":{"note":{"en":"The look-alike group shares the fais-/fac- root; the near-meaning group all answer 'can it be done?', from different angles.","cn":"形近组共享 fais-/fac- 词根；近义组都回答“能不能做成”，角度不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"feasible","ipa":"/ˈfiːzəbl/","tag":"same root, adjective","definition":"able to be done. It is the adjective; feasibility is the noun for that ability.","definitionCN":"可行的。它是形容词；feasibility 是这种能力的名词。"},{"word":"feasibly","ipa":"/ˈfiːzəbli/","tag":"same root, adverb","definition":"in a way that can be done. It modifies how something is done, not whether it is possible.","definitionCN":"可行地。它修饰做事方式，而不是是否可能。"},{"word":"infeasible","ipa":"/ɪnˈfiːzəbl/","tag":"negated form","definition":"not capable of being done. The in- prefix negates the adjective, and infeasibility is its noun.","definitionCN":"不可行的。in- 前缀否定该形容词，其名词为 infeasibility。"}]},{"heading":"NEAR MEANING","entries":[{"word":"viability","ipa":"/vaɪəˈbɪləti/","tag":"ability to survive","definition":"the ability to work successfully and continue. It adds a survival or business dimension that feasibility does not.","definitionCN":"成功运作并持续下去的能力。它多了一层生存或商业维度，而 feasibility 没有。"},{"word":"practicality","ipa":"/ˌpræktɪˈkæləti/","tag":"fitness for practice","definition":"the quality of being sensible and usable in real conditions. It stresses everyday good sense more than calculation.","definitionCN":"在真实条件下合理可用的性质。它比 feasibility 更强调日常常识，而非测算。"},{"word":"workability","ipa":"/ˌwɜːkəˈbɪləti/","tag":"able to function","definition":"the degree to which a method or material can be worked with. It often refers to materials or procedures.","definitionCN":"某方法或材料可被操作的程度。它常指材料或工序。"},{"word":"possibility","ipa":"/ˌpɒsəˈbɪləti/","tag":"may happen","definition":"whether something can exist or occur at all. It is broader and weaker than feasibility, which assumes someone intends to do it.","definitionCN":"某事能否存在或发生。它比 feasibility 更宽也更弱，后者假定有人打算去做。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"facere 'do' + -able 'can be': feasible is 'can be done', and feasibility is that 'can' turned into a noun.","cn":"facere“做”+ -able“能被”：feasible 是“能做成的”，feasibility 就是把这个“能”变成名词。"},{"en":"feasibility study is the standard collocation, and it names the document that answers the question.","cn":"feasibility study 是标准搭配，命名的是回答这个问题的文件。"},{"en":"Technical, financial, legal and engineering feasibility are four separate walls; a project must pass all four.","cn":"技术、财务、法规、工程可行性是四堵独立的墙，项目必须四堵都过。"},{"en":"Do not confuse feasibility with possibility: possibility asks if it can exist, feasibility asks if it can be done by someone.","cn":"别把 feasibility 与 possibility 混淆：possibility 问能否存在，feasibility 问某人能否做成。"},{"en":"The in- form is infeasible, not unfeasible in formal writing, and infeasibility is its matching noun.","cn":"否定形式在正式写作中作 infeasible，而非 unfeasible；对应名词是 infeasibility。"}],"abstract":[{"en":"Think of three gates in a row, marked time, money and law; failing any one stops the walk.","cn":"想象三扇排成一列的门，分别写时间、金钱、法律；任何一扇过不去，路就断了。"},{"en":"Think of a blueprint laid beside a calculator and a calendar, all three agreeing.","cn":"想象一张蓝图旁边放着计算器和日历，三者互相对得上。"},{"en":"Think of a bridge drawn on paper, then a real truck driven across it in the mind.","cn":"想象纸上画的一座桥，然后在脑中让一辆真卡车开过去。"}]},"examples":[{"en":"The feasibility of the solar farm depends on the price of land.","cn":"太阳能农场的可行性取决于土地价格。"},{"en":"A feasibility study is cheaper than a failed construction project.","cn":"一份可行性研究比一个失败的建设项目便宜。"},{"en":"The algorithm's feasibility was limited by memory, not by logic.","cn":"该算法的可行性受限于内存，而不是逻辑。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“费（fea）事不（si）ble”——费不费事，先算一算能不能做 → feasibility 可行性","word":"feasibility"},"root":"拉丁 facere“做” → 法语 faire / faisable“能做成的” → 英语 feasible + -ity；核心是“在真实限制下能不能做成”。","sensesIntro":{"en":"Eight senses share one question: can this actually be done, given the walls of time, money, law, technique and materials?","cn":"八个义项共享一个问题：在时间、金钱、法律、技术、材料这些墙面前，这件事真的做得成吗？"},"semanticMap":{"core":{"en":"CORE IMAGE: a blueprint beside a budget, a calendar and a soil sample, all checked.","cn":"核心意象：蓝图旁放着预算、日历与土样，三样都打了勾。"},"chain":["CAN IT BE DONE","STUDY THE QUESTION","CHECK THE METHOD","COUNT THE MONEY","CHECK THE LAW","CHECK THE MACHINE"],"branches":[{"senses":"01 · 06","en":"THE QUESTION AND ITS DEGREE: feasibility is both a yes-or-no test and a scale of how easily a design can be carried out.","cn":"问题与程度：feasibility 既是是非题，也是“方案落地有多容易”的尺度。"},{"senses":"02","en":"THE STUDY: the formal investigation takes the question as its object and produces a document.","cn":"研究：正式调查把这个问题当作对象，并产出一份文件。"},{"senses":"03 · 07 · 08","en":"TECHNICAL WALLS: laboratory method, computation and engineering all ask whether the means exist and can finish.","cn":"技术之墙：实验室方法、计算与工程都在问手段是否存在、能否完成。"},{"senses":"04","en":"MONEY: financial feasibility adds the condition that the money can be raised and repaid.","cn":"金钱：财务可行性加上“钱能筹到也能还上”的条件。"},{"senses":"05","en":"LAW: legal feasibility adds permission, a wall as hard as any physical one.","cn":"法律：法规可行性加上许可，这堵墙与任何物理墙一样硬。"}]},"affixes":{"intro":{"en":"Feasibility is feasible plus -ity. The -able suffix marks capability, and -ity turns that capability into an abstract noun; the base is the French form of Latin facere.","cn":"feasibility 是 feasible 加 -ity。-able 标记能力，-ity 把这种能力变成抽象名词；词基是拉丁 facere 的法语形式。"},"latinIntro":{"en":"The family runs from facere 'do' through French faire and faisable to English feasible. Relatives include facility, factor, effect and difficult, each with its own suffix history.","cn":"这个词族从 facere“做”经法语 faire、faisable 到英语 feasible。同族词包括 facility、factor、effect、difficult，各有自己的后缀历史。"},"items":[{"word":"feasible","structure":"French faisable + -able (capable of being)","meaning":"capable of being done","meaningCN":"可行的（-able“能够被……”）","example":"The route is feasible in summer only.","exampleCN":"这条路线只在夏季可行。"},{"word":"feasibility","structure":"feasible + -ity (quality noun)","meaning":"the quality of being doable","meaningCN":"可行性（-ity 性质名词）","example":"Feasibility was assessed in six weeks.","exampleCN":"可行性在六周内完成评估。"},{"word":"feasibly","structure":"feasible + -ly (manner adverb)","meaning":"in a doable manner","meaningCN":"可行地（-ly 方式副词）","example":"The task can feasibly be finished by Friday.","exampleCN":"这项任务在周五前完成是可行的。"},{"word":"infeasible","structure":"in- (not) + feasible","meaning":"not capable of being done","meaningCN":"不可行的（in-“不”+ feasible）","example":"The schedule was infeasible from the start.","exampleCN":"这个时间表从一开始就不可行。"},{"word":"infeasibility","structure":"infeasible + -ity (quality noun)","meaning":"the quality of being impossible to do","meaningCN":"不可行性（-ity 性质名词）","example":"The report documents the infeasibility of the design.","exampleCN":"报告记录了这一设计的不可行性。"},{"word":"facility","structure":"facilis + -ity (quality noun)","meaning":"ease; a place or service that helps","meaningCN":"便利；设施（facilis“容易”+ -ity）","example":"The lab has excellent facilities.","exampleCN":"这个实验室设施一流。"},{"word":"factor","structure":"facere + -or (agent)","meaning":"a maker; a cause; a number that multiplies","meaningCN":"因素；因数（-or 施事名词）","example":"Cost was the deciding factor.","exampleCN":"成本是决定性因素。"},{"word":"effect","structure":"ex- (out) + facere (do)","meaning":"a result brought about","meaningCN":"效果；结果（ex-“向外”+ facere“做”，同词根）","example":"The tax had an immediate effect on demand.","exampleCN":"这项税对需求产生了立竿见影的效果。"}],"latinEntries":[{"word":"facere","structure":"facere (to do, make)","meaning":"to do, make","meaningCN":"做；制作"},{"word":"facilis","structure":"facere + -ilis (able to be)","meaning":"easy, doable","meaningCN":"容易的；做得到的"},{"word":"facultas","structure":"facilis + -tas (ability)","meaning":"ability, opportunity","meaningCN":"能力；机会"},{"word":"faisable","structure":"French faire + -able","meaning":"that can be done","meaningCN":"能做成的（法语中介形式）"}]}},{"word":"feasible","ipa_uk":"/ˈfiːzəbl/","ipa_us":"/ˈfiːzəbl/","definition_zh":"可行的；行得通的；可能的","definition_en":"capable of being done or carried out with the means available","core_image":"一把钥匙正好插进锁孔，门后是一条能走通的路","scene":"A solar-powered pump is feasible here because the sun shines nine hours a day.","sceneCN":"这里 feasible 是「可行的」（第 1 个义项：在现有条件下能做得到）；句意：这里用太阳能水泵是可行的，因为每天日照九小时。图中可辨识物件：太阳能板、水泵、水槽、日照计。","pos":[{"tag":"adj.","zh":"可行的；行得通的；可能的"}],"collocations":[{"phrase":"feasible solution","zh":"可行解；可行的方案"},{"phrase":"technically feasible","zh":"技术上可行的"},{"phrase":"economically feasible","zh":"经济上可行的"},{"phrase":"feasible plan","zh":"可行的计划"},{"phrase":"not feasible","zh":"不可行"},{"phrase":"feasible alternative","zh":"可行的替代方案"}],"forms":[{"label":"比较级","form":"more feasible"},{"label":"最高级","form":"most feasible"}],"derivatives":[{"word":"feasibility","pos":"n.","zh":"可行性"},{"word":"feasibly","pos":"adv.","zh":"可行地"},{"word":"infeasible","pos":"adj.","zh":"不可行的"},{"word":"infeasibility","pos":"n.","zh":"不可行性"},{"word":"feasibleness","pos":"n.","zh":"可行性（罕用）"}],"senses":[{"no":"01","title":"Able to be done","titleCN":"可行的：条件凑齐就能做","definition":"possible to do or achieve with the resources and conditions that exist","definitionCN":"在现有资源与条件下可以做或实现的","example":"It is feasible to finish the report by Friday if we drop the survey.","exampleCN":"如果砍掉调查部分，周五前完成报告是可行的。","why":"feasible comes from French faisable, 'that can be done'. The word never promises success; it only says the doing is within reach.","whyCN":"feasible 来自法语 faisable“能做成的”。这个词从不承诺成功，只说明“做”在可及范围内。"},{"no":"02","title":"A plan that can be carried out","titleCN":"可实施的：计划落得下去","definition":"describing a plan that can be put into action without falling apart at the first obstacle","definitionCN":"指计划能够付诸行动、不会一遇障碍就崩掉","example":"The committee approved the cheaper, more feasible version of the design.","exampleCN":"委员会批准了成本更低、更可实施的那版设计。","why":"A plan is feasible when its steps fit the world. The adjective tests the plan against reality rather than against ambition.","whyCN":"计划可行，是指它的步骤与世界对得上。这个形容词用现实检验计划，而不是用野心检验。"},{"no":"03","title":"Economically feasible","titleCN":"经济上可行：算得过账","definition":"able to be financed and to return more than it costs","definitionCN":"能够获得资金、且回报高于成本的","example":"Wind power became economically feasible only after the subsidy.","exampleCN":"风电只有在补贴之后才在经济上可行。","why":"The same project can be physically easy and financially impossible. This sense puts the word on the ledger.","whyCN":"同一个项目可以物理上容易、财务上不可能。这个义项把词放到账本上。"},{"no":"04","title":"Technically feasible","titleCN":"技术上可行：现有手段够用","definition":"achievable with current technology, even if expensive or slow","definitionCN":"用现有技术可以实现的，即使昂贵或缓慢","example":"Capturing the exhaust gas is technically feasible but needs a large plant.","exampleCN":"捕集废气在技术上可行，但需要大型装置。","why":"Here the test is the toolbox, not the budget. Feasibility is split by dimension so that each can be argued separately.","whyCN":"这里的检验是工具箱，而不是预算。可行性按维度拆分，以便分别论证。"},{"no":"05","title":"Plausible, believable","titleCN":"似乎有理的：听起来站得住","definition":"seeming reasonable or likely, especially of an explanation or excuse","definitionCN":"显得合理或可能的，尤指解释或借口","example":"His story was feasible, but the timestamps did not match it.","exampleCN":"他的说法听起来合理，但时间戳对不上。","why":"The old rhetorical sense moves the word from doing to believing. A feasible story is one the mind can carry out without contradiction.","whyCN":"这个较旧的修辞义把词从“做”移到“信”。一个 feasible 的说法，是头脑能无矛盾地走通的版本。"},{"no":"06","title":"Optimization: a feasible solution","titleCN":"可行解：满足所有约束的那组值","definition":"in optimization, describing a point or solution that satisfies every constraint, though not necessarily the best","definitionCN":"最优化中满足所有约束、但不一定最优的点或解","example":"The solver found a feasible solution in two seconds and the optimum in an hour.","exampleCN":"求解器两秒找到可行解，一小时找到最优解。","why":"In mathematics the constraints are the walls. Feasible means the point is inside the walls; optimal means it is also the best spot inside.","whyCN":"数学里约束就是墙。feasible 指点在墙内；optimal 指它还是墙内最好的位置。"},{"no":"07","title":"Archaic: suitable or convenient","titleCN":"适宜的（古义）：方便合用","definition":"in older usage, describing something suitable, convenient or fair to use","definitionCN":"旧用法中指合适、方便或宜于使用的","example":"The old lease speaks of a feasible hour for the rent to be paid.","exampleCN":"旧租约提到一个适宜的缴租时辰。","why":"The oldest English sense was close to 'handy'. The modern 'possible' sense grew out of that, since what is convenient is usually also doable.","whyCN":"最早的英语义接近“顺手”。现代“可能”义由此生长，因为方便的事通常也做得到。"},{"no":"08","title":"Satisfying every constraint","titleCN":"可满足的：约束一条都没破","definition":"describing a set of conditions that can all hold at the same time","definitionCN":"指一组条件能够同时成立的","example":"The schedule is feasible only if no two labs need the same machine.","exampleCN":"只有当两个实验室不需要同一台机器时，这个时间表才可满足。","why":"This is the logical core of the mathematical sense: feasibility is the possibility of satisfying all conditions at once, not one by one.","whyCN":"这是数学义里的逻辑内核：可行就是所有条件能同时满足，而不是逐条满足。"}],"etymology":{"intro":{"en":"Feasible enters English through French faisable, 'that can be done', from faire 'to do' plus -able. Faire descends from Latin facere 'to do, make', so the root is the same as in facility and factor.","cn":"feasible 经法语 faisable“能做成的”进入英语，由 faire“做”加 -able 构成。faire 源自拉丁 facere“做、制作”，因此词根与 facility、factor 相同。"},"items":[{"era":"LATIN FACERE","en":"facere meant 'to do, make'. The root is extremely productive: fact, factor, facility, effect, defect and difficult all derive from it by different routes.","cn":"facere 意为“做、制作”。这个词根极为能产：fact、factor、facility、effect、defect、difficult 都由不同路径派生。"},{"era":"FRENCH FAIRE","en":"In French, facere became faire. The change from f to f and the loss of the Latin ending are regular sound developments, not a new word.","cn":"在法语中 facere 变成 faire。词尾消失等变化是规律性音变，不是新造词。"},{"era":"FRENCH FAISABLE","en":"faisable 'doable' adds -able to the stem. Old French used it for things that could be carried out, including legal conditions.","cn":"faisable“做得到的”在词干后加 -able。古法语用它指可以执行的事，包括法律条件。"},{"era":"ENGLISH ADOPTION","en":"English borrows the word in the 16th century with the spelling faisable, later reshaped to feasible. The meaning stayed 'practicable'.","cn":"英语于 16 世纪借入，拼作 faisable，后改形为 feasible。词义一直是“可实行的”。"},{"era":"MATHEMATICAL USE","en":"In the 20th century optimization theory fixes the phrase feasible solution, where feasibility means satisfying constraints.","cn":"20 世纪最优化理论固定了 feasible solution 这一说法，可行即满足约束。"}]},"similar":{"note":{"en":"The look-alike group shares the fais- form; the near-meaning group all describe something that can happen or be done, with different strengths.","cn":"形近组共享 fais- 外形；近义组都描述“能发生或能做”，强度不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"feasibility","ipa":"/ˌfiːzəˈbɪləti/","tag":"same root, noun","definition":"the quality of being doable. It is the abstract noun; feasible is the adjective.","definitionCN":"可行性。它是抽象名词；feasible 是形容词。"},{"word":"feasibly","ipa":"/ˈfiːzəbli/","tag":"same root, adverb","definition":"in a doable way. It modifies the manner of an action, not the possibility of it.","definitionCN":"可行地。它修饰动作方式，而非动作的可能性。"},{"word":"infeasible","ipa":"/ɪnˈfiːzəbl/","tag":"negated form","definition":"not capable of being done. The in- prefix reverses the adjective, and the word is common in optimization.","definitionCN":"不可行的。in- 前缀反转词义，这个词在最优化中很常见。"}]},{"heading":"NEAR MEANING","entries":[{"word":"possible","ipa":"/ˈpɒsəbl/","tag":"can exist or happen","definition":"able to exist or occur. It is wider than feasible, which assumes a plan and an agent.","definitionCN":"能够存在或发生的。它比 feasible 更宽，后者假定有计划与执行者。"},{"word":"practicable","ipa":"/prækˈtɪkəbl/","tag":"can be put into practice","definition":"able to be done in practice. It is close to feasible but sounds more formal and British.","definitionCN":"可实行的。它接近 feasible，但更正式、更偏英式。"},{"word":"viable","ipa":"/ˈvaɪəbl/","tag":"can survive and work","definition":"able to work successfully and last. It adds the idea of continuing to exist, which feasible lacks.","definitionCN":"能成功运作并持续的。它多了“继续存在”的意思，而 feasible 没有。"},{"word":"workable","ipa":"/ˈwɜːkəbl/","tag":"can be operated","definition":"able to be used or made to function. It often describes methods, materials or arrangements rather than projects.","definitionCN":"可操作的。它常描述方法、材料或安排，而非项目。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"French faisable 'can be done' is the direct source; the -able suffix is the 'can' in the word.","cn":"法语 faisable“能做成的”是直接来源；-able 后缀就是词里的那个“能”。"},{"en":"feasible solution is the standard phrase in optimization and means a point inside every constraint.","cn":"feasible solution 是最优化标准说法，指落在所有约束之内的一点。"},{"en":"The four common hedges are technically, economically, legally and physically feasible.","cn":"四个常见限定是技术上、经济上、法规上、物理上可行。"},{"en":"feasible never means certain: it means the door can open, not that it will.","cn":"feasible 从不表示“一定”：它说门能开，不说门会开。"},{"en":"The family hedge is infeasible, not unfeasible, in careful writing.","cn":"在严谨写作中，否定形式是 infeasible，而不是 unfeasible。"}],"abstract":[{"en":"Think of a key that turns in the lock: it fits, but someone still has to push the door.","cn":"想象一把钥匙在锁里转动：它配得上，但还得有人推门。"},{"en":"Think of a path drawn on a map that avoids every marked cliff.","cn":"想象地图上画出一条避开所有标记悬崖的路。"},{"en":"Think of a bridge made of paper that holds a small weight, not a truck.","cn":"想象一座纸桥能承住小重量，却承不住卡车。"}]},"examples":[{"en":"A single-payer system is feasible only if the tax base is broad enough.","cn":"只有税基足够广，单一支付体系才可行。"},{"en":"The design was feasible on paper and impossible on the factory floor.","cn":"这个设计在纸上可行，在车间里却不可能。"},{"en":"Every feasible solution satisfies the constraints, but only one is optimal.","cn":"每个可行解都满足约束，但只有一个是最优的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“费事不？”——先问一句费不费事，不费事就是能做 → feasible 可行的","word":"feasible"},"root":"拉丁 facere“做” → 法语 faire / faisable“能做成的” + -able；核心是“在现有条件下做得到”。","sensesIntro":{"en":"Eight senses share one test: the act fits inside the walls of resources, money, law or logic.","cn":"八个义项共享一个检验：这个动作能否落在资源、金钱、法律或逻辑的墙内。"},"semanticMap":{"core":{"en":"CORE IMAGE: a key that fits the lock.","cn":"核心意象：一把配得上锁孔的钥匙。"},"chain":["CAN BE DONE","CAN BE CARRIED OUT","CAN BE PAID FOR","CAN BE BUILT","SEEMS BELIEVABLE","FITS THE CONSTRAINTS"],"branches":[{"senses":"02","en":"THE CARRYABLE PLAN: a plan is feasible when every step can actually be taken.","cn":"可执行的计划：计划可行，在于每一步都真能走出去。"},{"senses":"01","en":"THE MINIMUM: one doable act is the atom from which every larger feasibility claim is built.","cn":"最小单位：一个可做的动作，是构成所有更大可行性判断的原子。"},{"senses":"03 · 04","en":"RESOURCES: money and technique are two separate walls, and a project may pass one and fail the other.","cn":"资源：金钱与技术是两堵独立的墙，项目可能过一堵、倒一堵。"},{"senses":"05 · 07","en":"BELIEF AND CONVENIENCE: the older senses move from 'handy' to 'believable', both about what the mind can accept.","cn":"信念与便利：较早义从“顺手”移到“可信”，都关于头脑能否接受。"},{"senses":"06 · 08","en":"CONSTRAINTS: the optimization solution and the satisfiable schedule are the logical core, all conditions holding at once.","cn":"约束：最优化解与可满足的时间表是逻辑内核——所有条件同时成立。"}]},"affixes":{"intro":{"en":"Feasible is a French adjective in -able built on faire 'do'. The -able suffix means 'capable of being', and the stem descends from Latin facere.","cn":"feasible 是带 -able 的法语形容词，建立在 faire“做”之上。-able 意为“能够被……”，词干源自拉丁 facere。"},"latinIntro":{"en":"The Latin base facere 'do' reaches English by two routes: directly in factor and facility, and through French in feasible and feasible's noun feasibility.","cn":"拉丁词基 facere“做”经两条路径到英语：直接进入 factor、facility，经法语进入 feasible 及其名词 feasibility。"},"items":[{"word":"feasible","structure":"French faisable + -able (capable)","meaning":"capable of being done","meaningCN":"可行的（-able“能够被……”）","example":"The plan is feasible within one year.","exampleCN":"该计划在一年内可行。"},{"word":"feasibility","structure":"feasible + -ity (quality noun)","meaning":"doability","meaningCN":"可行性（-ity 性质名词）","example":"They questioned its feasibility, not its value.","exampleCN":"他们质疑的是可行性，不是价值。"},{"word":"feasibly","structure":"feasible + -ly (manner adverb)","meaning":"in a doable way","meaningCN":"可行地（-ly 方式副词）","example":"The repair can feasibly wait until Monday.","exampleCN":"这次维修等到周一再说是可行的。"},{"word":"infeasible","structure":"in- (not) + feasible","meaning":"not doable","meaningCN":"不可行的（in-“不”）","example":"The deadline is infeasible with two staff.","exampleCN":"只有两名员工，这个截止期不可行。"},{"word":"infeasibility","structure":"infeasible + -ity","meaning":"impossibility of doing","meaningCN":"不可行性（-ity 名词）","example":"The proof of infeasibility saved months of work.","exampleCN":"不可行性的证明节省了数月工作。"},{"word":"facility","structure":"facilis + -ity (quality noun)","meaning":"ease; a helpful place or service","meaningCN":"便利；设施（facilis + -ity）","example":"The new facility can test fifty samples a day.","exampleCN":"新设施每天能检测五十个样本。"},{"word":"factor","structure":"facere + -or (agent)","meaning":"a cause or a multiplying number","meaningCN":"因素；因数（-or 施事名词）","example":"Weather was a major factor in the delay.","exampleCN":"天气是延误的主要因素。"},{"word":"difficult","structure":"dis- (not) + facilis (easy)","meaning":"not easy to do","meaningCN":"困难的（dis-“不”+ facilis“容易”，同根反义）","example":"The last stage is the most difficult.","exampleCN":"最后阶段最难。"}],"latinEntries":[{"word":"facere","structure":"facere (to do, make)","meaning":"to do, make","meaningCN":"做；制作"},{"word":"facilis","structure":"facere + -ilis (able to be)","meaning":"easy, doable","meaningCN":"容易的；做得到的"},{"word":"facultas","structure":"facilis + -tas (ability)","meaning":"ability, means","meaningCN":"能力；手段"},{"word":"faisable","structure":"French faire + -able","meaning":"that can be done","meaningCN":"能做成的（法语形式）"}]}},{"word":"fluctuation","ipa_uk":"/ˌflʌktʃuˈeɪʃn/","ipa_us":"/ˌflʌktʃuˈeɪʃn/","definition_zh":"波动；涨落；起伏","definition_en":"irregular rising and falling in level, amount or condition","core_image":"一条上下起伏的曲线，像水面被风推起的波纹","scene":"Currency fluctuation made the importer's costs change from month to month.","sceneCN":"这里 fluctuation 是「波动」（第 1 个义项：数值上下不规则变化）；句意：汇率波动让进口商的成本逐月变化。图中可辨识物件：汇率曲线、天平、货柜、日历。","pos":[{"tag":"n.","zh":"波动；涨落；起伏"}],"collocations":[{"phrase":"price fluctuation","zh":"价格波动"},{"phrase":"market fluctuation","zh":"市场波动"},{"phrase":"fluctuations in","zh":"……的波动"},{"phrase":"seasonal fluctuation","zh":"季节性波动"},{"phrase":"exchange-rate fluctuation","zh":"汇率波动"},{"phrase":"temperature fluctuation","zh":"温度起伏"}],"forms":[{"label":"复数","form":"fluctuations"}],"derivatives":[{"word":"fluctuate","pos":"v.","zh":"波动；起伏；变动"},{"word":"fluctuating","pos":"adj.","zh":"波动的；起伏不定的"},{"word":"fluctuant","pos":"adj.","zh":"波动的（罕用）"},{"word":"fluctuational","pos":"adj.","zh":"涨落的（物理学）"},{"word":"fluctuation","pos":"n.","zh":"波动；涨落"}],"senses":[{"no":"01","title":"Prices moving up and down","titleCN":"价格波动：今天高明天低","definition":"irregular changes in the price or value of something over time","definitionCN":"某物价格或价值随时间的不规则变化","example":"Price fluctuation in the grain market makes planning difficult for farmers.","exampleCN":"粮食市场的价格波动让农民难以规划。","why":"fluctus means 'wave'. Prices are pictured as a surface that rises and falls, not as a line that simply goes up.","whyCN":"fluctus 意为“波浪”。价格被想象成上下起伏的水面，而不是一条只往上的线。"},{"no":"02","title":"Physical rise and fall","titleCN":"涨落：水位与波动的物理过程","definition":"the rising and falling of a physical quantity such as water level or pressure","definitionCN":"水位、压力等物理量的上升与下降","example":"The fluctuation of the tide controls when the harbor can be entered.","exampleCN":"潮位的涨落决定何时能进港。","why":"This is the literal wave sense. The noun was first used for water and air before it was used for money.","whyCN":"这是字面的波浪义。这个名词先用于水与空气，之后才用于金钱。"},{"no":"03","title":"Statistical variation","titleCN":"统计涨落：平均值附近的抖动","definition":"random variation around an average value in measurements or counts","definitionCN":"测量或计数中围绕平均值的随机变化","example":"The detector's fluctuation is small enough to be averaged out.","exampleCN":"探测器的涨落小到可以被平均掉。","why":"Statistics formalizes the wave: variation is expected, and the word names the up-and-down motion around a mean.","whyCN":"统计学把波浪形式化：变化是预期之中的，这个词命名围绕均值的上下运动。"},{"no":"04","title":"Moods going up and down","titleCN":"情绪起伏：心情像水面一样晃","definition":"changes in mood or emotion that go up and down without a fixed pattern","definitionCN":"情绪或心情无固定规律地上下变化","example":"Her mood fluctuation worried the people who worked with her.","exampleCN":"她的情绪起伏让共事的人担忧。","why":"The metaphor moves inward: feelings are treated as a liquid level that rises and falls, out of the person's control.","whyCN":"这个比喻转向内部：情绪被当作会涨落的水位，不受本人控制。"},{"no":"05","title":"Numbers in a population","titleCN":"数量起伏：人多人少来回变","definition":"changes in the size of a population, group or quantity over time","definitionCN":"人口、群体或数量随时间的变化","example":"The fluctuation of the bird population follows the rainfall cycle.","exampleCN":"鸟类数量的起伏跟随降雨周期。","why":"Ecology counts individuals instead of dollars. The shape of the change is the same: not a trend but a repeated rise and fall.","whyCN":"生态学数的是个体而非美元。变化形状相同：不是趋势，而是反复的升降。"},{"no":"06","title":"Quantum fluctuation","titleCN":"量子涨落：真空里短暂的起伏","definition":"in physics, a temporary random change in the energy of a quantum system or field","definitionCN":"物理学中指量子系统或场能量的短暂随机变化","example":"Quantum fluctuation explains why empty space is never perfectly empty.","exampleCN":"量子涨落解释了为何真空从不是完美的空。","why":"The word reaches its most technical point here: a value that briefly departs from its expected level and returns, like a ripple in nothing.","whyCN":"这个词在这里达到最技术化的程度：数值短暂离开期望水平又回来，像“无”中的一圈涟漪。"},{"no":"07","title":"Business cycles","titleCN":"经济波动：繁荣与萧条交替","definition":"the recurring expansion and contraction of economic activity","definitionCN":"经济活动的周期性扩张与收缩","example":"The study links employment fluctuation to the investment cycle.","exampleCN":"该研究把就业波动与投资周期联系起来。","why":"Large-scale economics uses the plural almost always: fluctuations are many waves, not one. The word pictures an economy breathing in and out.","whyCN":"宏观经济学几乎总用复数：波动是许多道浪，不是一道。这个词把经济画成在吸气与呼气。"},{"no":"08","title":"Any irregular change","titleCN":"起伏不定：没有稳定的时候","definition":"any change that repeatedly moves away from and back toward a previous level","definitionCN":"任何反复离开先前水平又返回的变化","example":"The fluctuation in his attendance made the coach drop him from the team.","exampleCN":"他出勤的起伏让教练把他踢出了队。","why":"The general sense keeps the essential shape: movement that is not a steady climb or fall but an oscillation around a level.","whyCN":"总义保留基本形状：不是稳定的升或降，而是围绕某个水平的摆动。"}],"etymology":{"intro":{"en":"Fluctuation comes from Latin fluctuatio, built on fluctuare 'to move in waves', from fluctus 'a wave', from fluere 'to flow'. The word has described water, then prices, then quantum fields.","cn":"fluctuation 来自拉丁 fluctuatio，建立在 fluctuare“波浪式运动”之上，而 fluctus“波浪”又源自 fluere“流动”。这个词先后描述水、价格与量子场。"},"items":[{"era":"LATIN FLUERE","en":"fluere meant 'to flow'. Its present participle fluens gives English fluent, and the adjective fluidus gives fluid; the same root underlies influence and affluent with different prefixes.","cn":"fluere 意为“流动”。其现在分词 fluens 生出英语 fluent，形容词 fluidus 生出 fluid；同一词根也见于 influence、affluent，但前缀不同。"},{"era":"LATIN FLUCTUS","en":"fluctus meant 'a wave, a billow'. It is a fourth-declension noun from the same verb, naming the result of flowing.","cn":"fluctus 意为“波浪、涌浪”。它是同一动词派生的第四变格名词，命名“流动”的结果。"},{"era":"LATIN FLUCTUARE","en":"fluctuare 'to wave, to move like a wave' turns the noun into a verb. The motion is not directional; it rises and falls around a level.","cn":"fluctuare“波动、像波浪一样运动”把名词变成动词。这种运动没有固定方向，而是围绕某个水平上下。"},{"era":"LATIN FLUCTUATIO","en":"fluctuatio names the action or state of waving. English borrows this form as fluctuation in the 17th century, first for physical motion.","cn":"fluctuatio 命名“波动”的动作或状态。英语于 17 世纪以 fluctuation 借入这一形式，最初用于物理运动。"},{"era":"ECONOMIC EXTENSION","en":"From the 18th and 19th centuries the word spreads to prices, markets and populations, where the up-and-down shape is statistical rather than physical.","cn":"18 至 19 世纪，这个词扩展到价格、市场与人口，其上下形状变为统计性的而非物理性的。"},{"era":"QUANTUM SENSE","en":"In the 20th century quantum physics adopts the word for short-lived random variations of a field, the smallest possible waves.","cn":"20 世纪量子物理采用该词，指场中短暂随机的变化，即最小的波浪。"}]},"similar":{"note":{"en":"The look-alike group shares the flu- root but splits into flow, wave and adjective forms; the near-meaning group all describe change, with different shapes.","cn":"形近组共享 flu- 词根，但分为流动、波浪与形容词形式；近义组都描述变化，但形状不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"fluctuate","ipa":"/ˈflʌktʃueɪt/","tag":"same root, verb","definition":"to rise and fall irregularly. It is the action; fluctuation is the resulting movement as a noun.","definitionCN":"不规则地上下波动。它是动作；fluctuation 是作为名词的波动。"},{"word":"fluent","ipa":"/ˈfluːənt/","tag":"same root, different participle","definition":"speaking or flowing smoothly. It comes from the present participle of fluere 'flow', so it describes smooth flow, not wave motion.","definitionCN":"流利的；流畅的。它来自 fluere“流动”的现在分词，因此描述顺畅流动，而非波浪。"},{"word":"fluid","ipa":"/ˈfluːɪd/","tag":"same root, adjective and noun","definition":"a substance that flows; also smooth or changeable. It names flow, while fluctuation names oscillation.","definitionCN":"流体；流动的；易变的。它命名“流”，而 fluctuation 命名“摆”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"variation","ipa":"/ˌværiˈeɪʃn/","tag":"change in form or amount","definition":"a change or difference in condition or level. It is broader and need not go up and down.","definitionCN":"状态或水平的变化或差异。它更宽泛，不必上下反复。"},{"word":"oscillation","ipa":"/ˌɒsɪˈleɪʃn/","tag":"swinging back and forth","definition":"regular movement back and forth. It is more regular than fluctuation, which is often irregular.","definitionCN":"有规律的往返运动。它比 fluctuation 更规则，后者常不规则。"},{"word":"instability","ipa":"/ˌɪnstəˈbɪləti/","tag":"lack of steadiness","definition":"the quality of being likely to change or fail. It judges the change as a problem, while fluctuation merely describes it.","definitionCN":"易变或易失稳的性质。它把变化判定为问题，而 fluctuation 只作描述。"},{"word":"swing","ipa":"/swɪŋ/","tag":"a large movement","definition":"a noticeable change from one level or opinion to another. It is informal and usually suggests a bigger range.","definitionCN":"从一个水平或立场到另一个的明显变化。它口语化，通常暗示幅度更大。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"fluere 'flow' gives fluctus 'wave': fluctuation is a level flowing up and down.","cn":"fluere“流动”生出 fluctus“波浪”：fluctuation 就是水平面上下流动。"},{"en":"fluent, fluid and fluctuation share the flu- stem but split into smooth flow, substance and oscillation.","cn":"fluent、fluid、fluctuation 共享 flu- 词干，但分别指向顺畅流动、流体与摆动。"},{"en":"price fluctuation, market fluctuation and exchange-rate fluctuation are the three everyday collocations.","cn":"price fluctuation、market fluctuation、exchange-rate fluctuation 是三个日常搭配。"},{"en":"Quantum fluctuation is the smallest wave: a value briefly leaves its level and returns.","cn":"量子涨落是最小的波浪：数值短暂离开原位又回来。"},{"en":"Fluctuation is neutral, instability is negative; one describes the motion, the other judges it.","cn":"fluctuation 中性，instability 负面；一个描述运动，一个评判运动。"}],"abstract":[{"en":"Think of a cork bobbing on water, rising and sinking without travelling anywhere.","cn":"想象一个软木塞在水上上下浮动，却没有去往任何地方。"},{"en":"Think of a graph line that keeps crossing its own average, again and again.","cn":"想象一条曲线反复穿过自己的平均值。"},{"en":"Think of a heartbeat monitor: the line is never flat, and that is what life looks like.","cn":"想象心跳监护仪：线从不平直，而生命就是这个样子。"}]},"examples":[{"en":"Small fluctuations in temperature can change the result of the experiment.","cn":"温度的微小波动就能改变实验结果。"},{"en":"The central bank tries to limit fluctuation in the currency.","cn":"央行试图限制货币的波动。"},{"en":"Seasonal fluctuation in demand is normal in the tourism industry.","cn":"旅游业的季节性需求波动是正常的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“浮（flu）起来又沉下去”——水面上下浮沉，像价格线来回走 → fluctuation 波动","word":"fluctuation"},"root":"拉丁 fluere“流动” → fluctus“波浪” → fluctuare“波动” → fluctuatio；核心是“围绕某一水平的上下起伏”。","sensesIntro":{"en":"Eight senses share one shape: a level rises and falls around a mean, never settling and never simply climbing.","cn":"八个义项共享一种形状：某个水平围绕均值上下，既不安定，也不是单纯上升。"},"semanticMap":{"core":{"en":"CORE IMAGE: a water surface pushed into ripples by wind.","cn":"核心意象：被风推起波纹的水面。"},"chain":["MOVE LIKE A WAVE","RISE AND FALL","PRICES SWING","MOODS SWING","COUNTS SWING","TINY RANDOM WAVES"],"branches":[{"senses":"01 · 07","en":"MARKETS: price and business-cycle fluctuation are the same wave seen in a day and in a decade.","cn":"市场：价格波动与经济周期波动，是同一种波浪在一天与十年两个尺度上的样子。"},{"senses":"02","en":"PHYSICAL: tide and pressure fluctuation are the literal water-and-air version of the word.","cn":"物理：潮位与压力涨落，是这个词字面上的水与空气版本。"},{"senses":"03 · 06","en":"RANDOMNESS: statistical variation and quantum fluctuation are small departures from an expected level.","cn":"随机性：统计涨落与量子涨落，都是对期望水平的微小偏离。"},{"senses":"04 · 05","en":"LIVING THINGS: mood and population fluctuation move the wave from matter to feeling and to counts of organisms.","cn":"生命：情绪与数量波动，把这道浪从物质移到情感与生物计数。"},{"senses":"08","en":"GENERAL SHAPE: any repeated departure and return is the same oscillation, whatever the unit.","cn":"一般形状：任何反复离开又返回的运动都是同一种摆动，不论单位是什么。"}]},"affixes":{"intro":{"en":"Fluctuation is fluctuate plus -ion. The flu- stem means 'flow', -ct- marks the wave noun, -ate makes a verb and -ion names the motion.","cn":"fluctuation 是 fluctuate 加 -ion。flu- 词干意为“流动”，-ct- 标记波浪名词，-ate 构成动词，-ion 命名运动。"},"latinIntro":{"en":"The family runs from fluere 'flow' to fluctus 'wave' to fluctuare 'wave' to fluctuatio. English relatives include fluent, fluid, influence and affluent.","cn":"这个词族从 fluere“流动”到 fluctus“波浪”到 fluctuare“波动”再到 fluctuatio。英语同族词包括 fluent、fluid、influence、affluent。"},"items":[{"word":"fluctuate","structure":"fluctuare + -ate (verb)","meaning":"to rise and fall irregularly","meaningCN":"波动；起伏（-ate 动词后缀）","example":"Prices fluctuated all summer.","exampleCN":"整个夏天价格都在波动。"},{"word":"fluctuation","structure":"fluctuat- + -ion (action noun)","meaning":"the motion of rising and falling","meaningCN":"波动；涨落（-ion 动作名词）","example":"The fluctuation was within five percent.","exampleCN":"波动幅度在百分之五以内。"},{"word":"fluctuating","structure":"fluctuate + -ing (participial adjective)","meaning":"changing up and down","meaningCN":"波动的（-ing 分词形容词）","example":"The fluctuating demand strained the supply chain.","exampleCN":"波动的需求让供应链吃紧。"},{"word":"fluctuant","structure":"fluctus + -ant (adjective)","meaning":"wavy, moving up and down, now rare","meaningCN":"波动的（-ant 形容词，罕用）","example":"The fluctuant surface made landing difficult.","exampleCN":"起伏的水面让降落很困难。"},{"word":"fluctuational","structure":"fluctuation + -al (relational adjective)","meaning":"relating to fluctuation, used in physics","meaningCN":"涨落的（-al 关系形容词，物理学用）","example":"Fluctuational noise sets the limit of the sensor.","exampleCN":"涨落噪声决定了传感器的极限。"},{"word":"fluent","structure":"fluere + -ent (present participle)","meaning":"flowing smoothly","meaningCN":"流利的（fluere 现在分词，同一词根）","example":"She is fluent in three languages.","exampleCN":"她能流利使用三种语言。"},{"word":"fluid","structure":"fluere + -idus (adjective)","meaning":"a flowing substance; changeable","meaningCN":"流体；易变的（-idus 形容词）","example":"The fluid in the pipe was replaced.","exampleCN":"管道里的流体被更换了。"},{"word":"influence","structure":"in- (into) + fluere (flow)","meaning":"a flowing-in of power or effect","meaningCN":"影响（in-“进入”+ fluere“流动”，同根不同义）","example":"The climate has a strong influence on crops.","exampleCN":"气候对作物有很大影响。"}],"latinEntries":[{"word":"fluere","structure":"fluere (to flow)","meaning":"to flow","meaningCN":"流动"},{"word":"fluctus","structure":"fluere + -ctus (result noun)","meaning":"a wave, a billow","meaningCN":"波浪；涌浪"},{"word":"fluctuare","structure":"fluctus + -are (verb)","meaning":"to move in waves","meaningCN":"波动；起伏"},{"word":"fluctuatio","structure":"fluctuat- + -io (action noun)","meaning":"a waving, a fluctuation","meaningCN":"波动；涨落"}]}},{"word":"formulation","ipa_uk":"/ˌfɔːmjuˈleɪʃn/","ipa_us":"/ˌfɔːrmjəˈleɪʃn/","definition_zh":"表述；制定；配方；公式表达","definition_en":"the act of expressing an idea precisely, or the particular mixture and wording that results","core_image":"一张纸上先写出一句精确的话，旁边再排出配比表","scene":"The formulation of the policy took months of drafting and redrafting.","sceneCN":"这里 formulation 是「制定、表述」（第 1 个义项：把想法整理成明确文字）；句意：这项政策的制定花了几个月反复起草。图中可辨识物件：草稿纸、修改批注、会议桌、印章。","pos":[{"tag":"n.","zh":"表述；制定；配方；公式化"}],"collocations":[{"phrase":"policy formulation","zh":"政策制定"},{"phrase":"formulation of","zh":"……的表述／制定"},{"phrase":"drug formulation","zh":"药物配方；剂型"},{"phrase":"mathematical formulation","zh":"数学表述"},{"phrase":"strategy formulation","zh":"战略制定"},{"phrase":"product formulation","zh":"产品配方"}],"forms":[{"label":"复数","form":"formulations"}],"derivatives":[{"word":"formulate","pos":"v.","zh":"制定；确切表达；配制"},{"word":"formula","pos":"n.","zh":"公式；配方；方案"},{"word":"formulary","pos":"n./adj.","zh":"处方集；公式化的"},{"word":"formulistic","pos":"adj.","zh":"公式化的；拘泥形式的"},{"word":"reformulate","pos":"v.","zh":"重新表述；重新制定"}],"senses":[{"no":"01","title":"Putting an idea into exact words","titleCN":"表述：把想法压成一句准话","definition":"the act of expressing a thought or plan in clear, precise language","definitionCN":"用清楚、精确的语言表达思想或计划的行为","example":"The formulation of the question decided what could count as an answer.","exampleCN":"问题的表述方式决定了什么才算答案。","why":"formula is a small form. Formulation gives an idea a definite shape in words, the way a mold gives metal a shape.","whyCN":"formula 是“小形式”。formulation 用文字给想法一个确定形状，就像模具给金属一个形状。"},{"no":"02","title":"Drafting a policy","titleCN":"制定：把政策一条条写出来","definition":"the process of designing and writing a policy, strategy or plan","definitionCN":"设计并写出政策、战略或计划的过程","example":"The formulation of the new tax rules involved three ministries.","exampleCN":"新税则的制定涉及三个部委。","why":"Policy does not exist until it is written down. Formulation is the moment an intention acquires clauses, numbers and a signature line.","whyCN":"政策在写下来之前并不存在。formulation 就是意图获得条款、数字与签字栏的那一刻。"},{"no":"03","title":"A chemical recipe","titleCN":"配方：每种成分放多少","definition":"a specific mixture of ingredients and their proportions, especially in medicine or industry","definitionCN":"成分及其比例的特定混合，尤用于医药或工业","example":"The new formulation dissolves faster and tastes less bitter.","exampleCN":"新配方溶解更快，苦味也更少。","why":"This is the most concrete sense: the formula is a list of quantities. The word names both the list and the resulting product.","whyCN":"这是最具体的义项：formula 是一张数量清单。这个词既命名清单，也命名产物。"},{"no":"04","title":"Stating it as a formula","titleCN":"公式表达：把关系写成符号","definition":"the expression of a relationship in mathematical symbols","definitionCN":"用数学符号表达某种关系","example":"The formulation of the model uses two variables and one constant.","exampleCN":"该模型的公式表达使用两个变量和一个常数。","why":"Mathematics strips the idea to symbols. The same 'give it a form' act now produces an equation rather than a sentence.","whyCN":"数学把想法剥到符号层。同一个“给它一个形式”的动作，现在产出的是方程而不是句子。"},{"no":"05","title":"Building a theory","titleCN":"理论建构：把假设搭成体系","definition":"the construction of a theory or hypothesis in a defined and testable form","definitionCN":"以明确且可检验的形式构建理论或假设","example":"Her formulation of the problem avoided the usual assumption of perfect information.","exampleCN":"她对问题的理论建构避开了常见的完全信息假设。","why":"A theory is formulation all the way down: assumptions, definitions and predictions are all given form before anything can be tested.","whyCN":"理论从头到尾都是 formulation：假设、定义与预测都必须先获得形式，才谈得上检验。"},{"no":"06","title":"The finished product form","titleCN":"剂型：做成药片还是液体","definition":"the physical form in which a medicine or product is supplied","definitionCN":"药品或产品供应的物理形态","example":"The same drug is sold in tablet and liquid formulations.","exampleCN":"同一种药有片剂和液剂两种剂型。","why":"Here formulation means the shape the product finally takes. The active ingredient is the same; the form is the difference.","whyCN":"这里 formulation 指产品最终采取的形状。有效成分相同，差别在形式。"},{"no":"07","title":"Setting out a problem","titleCN":"问题形式化：先把题目写清楚","definition":"the formal statement of a problem so that it can be solved or computed","definitionCN":"为使问题可解或可计算而作的正式陈述","example":"A good formulation often makes the solution obvious.","exampleCN":"一个好的问题表述常让解法变得显然。","why":"This sense treats formulation as half the solution. Once the problem is stated in the right variables, the hard part is already done.","whyCN":"这个义项把 formulation 当作解法的一半。一旦用正确的变量表述问题，难的部分已经完成。"},{"no":"08","title":"A statement repeated as a formula","titleCN":"套话：固定成句的说法","definition":"a fixed phrase used repeatedly, often losing its original force","definitionCN":"被反复使用、常失去原有力量的固定说法","example":"The minister's formulation about 'shared responsibility' satisfied nobody.","exampleCN":"部长那句关于“共同责任”的套话谁也没说服。","why":"A formulation can harden into a formula. What was once a precise shaping becomes a ready-made block dropped into any speech.","whyCN":"formulation 会硬化成 formula。曾经精确的塑形，变成可以塞进任何演讲的现成积木。"}],"etymology":{"intro":{"en":"Formulation comes from formulate, from Latin formulare 'to form', built on formula, a diminutive of forma 'form, shape'. The word is about giving something a definite shape.","cn":"formulation 来自 formulate，而 formulate 出自拉丁 formulare“成形”，建立在 formula 之上，而 formula 是 forma“形式、形状”的指小形式。这个词讲的是给某物一个确定形状。"},"items":[{"era":"LATIN FORMA","en":"forma meant 'form, shape, mold'. It also meant 'beauty', because a well-shaped thing was thought beautiful; English form and formal descend from it.","cn":"forma 意为“形式、形状、模具”。它也表示“美”，因为形状好的东西被认为美；英语 form、formal 由此而来。"},{"era":"LATIN FORMULA","en":"formula was a small forma, 'a little shape'. In law it meant a fixed form of words, which is how the modern 'formula' sense began.","cn":"formula 是“小形式”，即一个小 shape。在法律中它指固定的措辞格式，现代“公式”义正由此开始。"},{"era":"LATIN FORMULARE","en":"formulare 'to shape, to express in a fixed form' turns the noun into a verb. The verb covers both drafting a text and mixing a preparation.","cn":"formulare“塑形、以固定形式表达”把名词变成动词。这个动词既涵盖起草文本，也涵盖配制混合物。"},{"era":"ENGLISH FORMULATE","en":"English formulate appears in the 19th century. It inherits both the verbal sense, to state precisely, and the chemical sense, to prepare by recipe.","cn":"英语 formulate 于 19 世纪出现。它继承了两种含义：精确陈述的言语义，以及按配方配制的化学义。"},{"era":"ENGLISH -ATION","en":"Formulation adds -ation, from Latin -atio, naming the process or its result. The noun is common in policy, pharmacy and mathematics.","cn":"formulation 加 -ation（来自拉丁 -atio），命名过程或结果。这个名词常见于政策、药学与数学。"},{"era":"MODERN POLICY USE","en":"In the 20th century formulation becomes standard in policy and strategy writing, where it names the drafting stage before adoption.","cn":"20 世纪 formulation 成为政策与战略写作的标准词，命名通过之前的起草阶段。"}]},"similar":{"note":{"en":"The look-alike group shares the form- root but each adds a different suffix; the near-meaning group all involve putting something into a definite shape, verbal or material.","cn":"形近组共享 form- 词根，但各加不同后缀；近义组都涉及把某物放进确定形状，或言语或物质。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"formula","ipa":"/ˈfɔːmjələ/","tag":"same root, base noun","definition":"a fixed expression, recipe or equation. It is the shaped thing; formulation is the shaping act.","definitionCN":"固定的说法、配方或公式。它是被塑成之物；formulation 是塑形行为。"},{"word":"formulate","ipa":"/ˈfɔːmjuleɪt/","tag":"same root, verb","definition":"to express precisely or to prepare by recipe. It is the action behind the noun.","definitionCN":"确切表达；按配方配制。它是名词背后的动作。"},{"word":"formation","ipa":"/fɔːˈmeɪʃn/","tag":"same root, different suffix","definition":"the process of coming into being, as of a structure or group. It uses formare 'to form' directly, without the -ula diminutive.","definitionCN":"形成、构成的过程，如结构或群体的形成。它直接用 formare“形成”，没有 -ula 指小成分。"}]},{"heading":"NEAR MEANING","entries":[{"word":"expression","ipa":"/ɪkˈspreʃn/","tag":"putting into words","definition":"the act of putting a thought into words. It is broader than formulation and less technical.","definitionCN":"把想法放进文字的行为。它比 formulation 更宽泛，也更不技术化。"},{"word":"wording","ipa":"/ˈwɜːdɪŋ/","tag":"choice of words","definition":"the particular words used to say something. It focuses on the verbal surface, not the underlying design.","definitionCN":"用来表达某事的特定措辞。它聚焦言语表面，而非底层设计。"},{"word":"composition","ipa":"/ˌkɒmpəˈzɪʃn/","tag":"putting together","definition":"the act of combining parts into a whole, as in music or writing. It is broader and often artistic.","definitionCN":"把部分合成整体，如音乐或写作。它更宽泛，常带艺术性。"},{"word":"preparation","ipa":"/ˌprepəˈreɪʃn/","tag":"making a substance ready","definition":"the act of making something ready, especially a mixture. It covers the pharmacy sense but not the policy sense.","definitionCN":"使某物准备好的行为，尤指配制混合物。它覆盖药学义，但不含政策义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"forma 'shape' + -ula 'little': a formula is a little shape, and formulation is giving an idea that shape.","cn":"forma“形状”+ -ula“小”：formula 是一个小形状，formulation 就是给想法这个形状。"},{"en":"policy formulation and strategy formulation are the two standard policy collocations.","cn":"policy formulation 与 strategy formulation 是两个标准政策搭配。"},{"en":"drug formulation is the pharmacy sense: same active ingredient, different physical form.","cn":"drug formulation 是药学义：同一有效成分，不同物理形态。"},{"en":"A good mathematical formulation often solves half the problem before calculation starts.","cn":"好的数学表述常在计算开始前就解决了一半问题。"},{"en":"Note the pair formula and formulation: one is the fixed shape, the other the act of shaping.","cn":"注意 formula 与 formulation 这一对：一个是固定形状，一个是塑形动作。"}],"abstract":[{"en":"Think of clay pressed into a mold and lifted out with a clean edge.","cn":"想象黏土压进模具，取出时边缘干净。"},{"en":"Think of a long argument reduced to one sentence on an index card.","cn":"想象一段长论证被压缩成卡片上的一句话。"},{"en":"Think of a cook writing exact grams beside each ingredient, then handing the card to a factory.","cn":"想象厨师在每种配料旁写下精确克数，然后把卡片交给工厂。"}]},"examples":[{"en":"The formulation of the hypothesis took longer than the experiment itself.","cn":"假设的表述比实验本身花的时间还长。"},{"en":"The company changed the formulation to remove the artificial colour.","cn":"公司修改配方，去掉了人工色素。"},{"en":"Clear formulation is a courtesy to the reader.","cn":"清晰的表述是对读者的礼貌。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“form（形式）+ ulate”——给想法一个形式，再写出来 → formulation 表述、配方","word":"formulation"},"root":"拉丁 forma“形式、形状” → formula（forma 的指小形式，固定措辞/配方）→ formulare“塑形、表述” → formulate + -ation。","sensesIntro":{"en":"Eight senses share one act: an idea or a substance is given a definite form, so that it can be repeated, tested or manufactured.","cn":"八个义项共享一个动作：想法或物质被赋予确定形式，从而可以被重复、检验或制造。"},"semanticMap":{"core":{"en":"CORE IMAGE: clay pressed into a mold.","cn":"核心意象：黏土被压进模具。"},"chain":["GIVE IT A FORM","PUT IT INTO WORDS","WRITE IT AS POLICY","MIX IT BY RECIPE","WRITE IT AS SYMBOLS","FIX IT INTO A PHRASE"],"branches":[{"senses":"01 · 08","en":"WORDS: a precise statement and a hardened stock phrase are the same shaping, one still alive and one gone rigid.","cn":"文字：精确表述与僵硬套话是同一种塑形，一个还活着，一个已硬化。"},{"senses":"02","en":"POLICY: the drafting stage gives an intention clauses and numbers before adoption.","cn":"政策：起草阶段在通过之前给意图配上条款与数字。"},{"senses":"03 · 06","en":"MATTER: a recipe and a finished dosage form are the list and the resulting shape of the same mixture.","cn":"物质：配方与最终剂型，是同一混合物的清单与成品形状。"},{"senses":"04 · 07","en":"SYMBOLS: mathematical statement and formal problem setting reduce the idea to variables and constraints.","cn":"符号：数学表述与问题形式化，把想法压缩成变量与约束。"},{"senses":"05","en":"THEORY: assumptions, definitions and predictions are all given form before testing begins.","cn":"理论：假设、定义与预测在检验开始前都必须获得形式。"}]},"affixes":{"intro":{"en":"Formulation is formulate plus -ation. The form- stem means 'shape', -ula is a diminutive, -ate makes a verb and -ation names the process.","cn":"formulation 是 formulate 加 -ation。form- 词干意为“形状”，-ula 是指小成分，-ate 构成动词，-ation 命名过程。"},"latinIntro":{"en":"The family runs from forma 'shape' to formula 'little shape, fixed wording' to formulare 'shape, express'. English relatives include form, formal, format and formulate.","cn":"这个词族从 forma“形状”到 formula“小形状、固定措辞”再到 formulare“塑形、表达”。英语同族词包括 form、formal、format、formulate。"},"items":[{"word":"formulate","structure":"formula + -ate (verb)","meaning":"to state precisely; to prepare by recipe","meaningCN":"确切表述；按配方配制（-ate 动词后缀）","example":"The team formulated a clear hypothesis.","exampleCN":"团队提出了一个清晰的假设。"},{"word":"formulation","structure":"formulate + -ation (process noun)","meaning":"the act or result of shaping","meaningCN":"表述；制定；配方（-ation 过程名词）","example":"The formulation was revised twice.","exampleCN":"这份表述被修改了两次。"},{"word":"formula","structure":"forma + -ula (diminutive)","meaning":"a fixed phrase, recipe or equation","meaningCN":"公式；配方（forma 的指小形式）","example":"The formula has three variables.","exampleCN":"这个公式有三个变量。"},{"word":"form","structure":"forma (shape)","meaning":"the shape or structure of something","meaningCN":"形式；形状（同一词根的基础名词）","example":"Water takes the form of the container.","exampleCN":"水呈现出容器的形状。"},{"word":"formal","structure":"forma + -alis (relational adjective)","meaning":"following an established shape or rule","meaningCN":"正式的；形式上的（-alis 关系形容词）","example":"The letter was too formal for a friend.","exampleCN":"这封信对朋友来说太正式了。"},{"word":"format","structure":"forma + -atus (thing noun)","meaning":"the arrangement or layout of something","meaningCN":"格式；版式（-atus 事物名词）","example":"The file format is not supported.","exampleCN":"不支持这种文件格式。"},{"word":"formulary","structure":"formula + -ary (collection noun)","meaning":"a book of approved formulas or medicines","meaningCN":"处方集；公式集（-ary 集合名词）","example":"The hospital formulary lists two hundred drugs.","exampleCN":"医院处方集列出两百种药。"},{"word":"reformulate","structure":"re- (again) + formulate","meaning":"to state or prepare again in a new form","meaningCN":"重新表述；重新配制（re-“再次”）","example":"They reformulated the question to avoid ambiguity.","exampleCN":"他们重新表述问题以避免歧义。"}],"latinEntries":[{"word":"forma","structure":"forma (form, shape)","meaning":"form, shape, mold","meaningCN":"形式；形状；模具"},{"word":"formula","structure":"forma + -ula (diminutive)","meaning":"a little shape; a fixed form of words","meaningCN":"小形状；固定措辞"},{"word":"formulare","structure":"formula + -are (verb)","meaning":"to shape, to express in a form","meaningCN":"塑形；以形式表达"},{"word":"formatio","structure":"formare + -tio (action noun)","meaning":"a forming, a shaping","meaningCN":"形成；塑形"}]}},{"word":"foundational","ipa_uk":"/faʊnˈdeɪʃənl/","ipa_us":"/faʊnˈdeɪʃənl/","definition_zh":"基础的；奠基性的；根本的","definition_en":"serving as the base on which something else is built or understood","core_image":"石匠把第一块方石放进坑里，后面的墙都从它起线","scene":"The course covers foundational concepts before moving to applied work.","sceneCN":"这里 foundational 是「基础的」（第 1 个义项：作为后续学习的前提）；句意：这门课先讲基础概念，再转向应用。图中可辨识物件：基石、水平仪、图纸、砖块。","pos":[{"tag":"adj.","zh":"基础的；奠基性的；根本的"}],"collocations":[{"phrase":"foundational concept","zh":"基础概念"},{"phrase":"foundational research","zh":"基础研究"},{"phrase":"foundational text","zh":"奠基性文本"},{"phrase":"foundational assumption","zh":"基本假设"},{"phrase":"foundational course","zh":"基础课程"},{"phrase":"foundational skill","zh":"基础技能"}],"forms":[{"label":"比较级","form":"more foundational"},{"label":"最高级","form":"most foundational"}],"derivatives":[{"word":"foundation","pos":"n.","zh":"基础；地基；基金会"},{"word":"found","pos":"v.","zh":"创立；建造；以……为基础"},{"word":"founder","pos":"n.","zh":"创始人；（船）沉没者"},{"word":"fundamental","pos":"adj./n.","zh":"根本的；基本原理"},{"word":"fundamentally","pos":"adv.","zh":"根本上"}],"senses":[{"no":"01","title":"The base for later learning","titleCN":"基础的：后面内容都从这儿起","definition":"forming the basic knowledge or skills that later work depends on","definitionCN":"构成后续工作所依赖的基础知识或技能的","example":"Foundational reading skills predict success in every other subject.","exampleCN":"基础阅读能力可以预测其他所有学科的成功。","why":"fundus means 'bottom'. Foundational marks what sits at the bottom of a structure, holding everything above it.","whyCN":"fundus 意为“底部”。foundational 标记位于结构底部、托住上方一切的东西。"},{"no":"02","title":"Serving as a foundation","titleCN":"奠基性的：第一块石头","definition":"acting as the first established part on which a system or institution is erected","definitionCN":"作为建立某个体系或制度的第一部分的","example":"The 1789 report is a foundational document of the public school system.","exampleCN":"1789 年的那份报告是公立学校体系的奠基性文件。","why":"The first stone determines the line of every later stone. A foundational document does the same for an institution.","whyCN":"第一块石头决定了后面每块石头的走向。一份奠基性文件对一个制度也是如此。"},{"no":"03","title":"Fundamental to a theory","titleCN":"根本的：理论离不开的假设","definition":"being one of the assumptions or principles without which a theory cannot stand","definitionCN":"作为理论不可或缺的假设或原则之一的","example":"The foundational assumption of the model is that preferences do not change.","exampleCN":"该模型的基本假设是偏好不变。","why":"A theory rests on a few unproved commitments. Foundational names them without calling them true, only load-bearing.","whyCN":"理论建立在少数未经证明的承诺上。foundational 命名它们，但不说它们为真，只说它们承重。"},{"no":"04","title":"Introductory in teaching","titleCN":"入门的：先学这一层","definition":"describing a course or lesson that teaches the first layer of a subject","definitionCN":"指教授某学科第一层内容的课程或课","example":"The foundational course has no prerequisites.","exampleCN":"这门入门课程没有先修要求。","why":"In a curriculum the foundation is what comes first in time as well as in depth. The word marks order and dependence at once.","whyCN":"在课程体系中，基础既在深度上、也在时间上排在最前。这个词同时标记顺序与依赖关系。"},{"no":"05","title":"Basic science","titleCN":"基础研究的：不急着应用","definition":"relating to research aimed at understanding basics rather than solving an immediate problem","definitionCN":"指以理解基本原理为目标、而非解决眼前问题的研究","example":"Foundational research on cell membranes later produced a whole class of drugs.","exampleCN":"关于细胞膜的基础研究后来催生了一整类药物。","why":"The foundation is laid below the visible building. Basic research is valued for what it will support, not for what it sells now.","whyCN":"地基铺在可见建筑之下。基础研究的价值在于它将支撑什么，而不在于它现在卖什么。"},{"no":"06","title":"The bottom layer of a system","titleCN":"底层的：整个系统压在上面","definition":"describing the lowest layer of a technical system that all other layers rely on","definitionCN":"指技术系统中最底层、其他各层都依赖的那一层","example":"The foundational layer of the software handles memory and timing.","exampleCN":"这个软件的底层负责内存与计时。","why":"Computing borrows the building image: the base layer must be stable before anything can be stacked on it.","whyCN":"计算机借用了建筑意象：底层必须稳定，上面才堆得起来。"},{"no":"07","title":"Founding or establishing","titleCN":"创立的：把机构立起来","definition":"relating to the act of founding an institution or movement","definitionCN":"与创立某个机构或运动的行为有关的","example":"The foundational meeting elected a chair and wrote three rules.","exampleCN":"创立会议选出了主席，并写下三条规则。","why":"This sense is close to the verb found: what is foundational is what was laid down at the beginning and still shapes the thing.","whyCN":"这个义项接近动词 found：foundational 的东西就是开头立下、至今仍在塑造该事物的东西。"},{"no":"08","title":"Structurally load-bearing","titleCN":"结构性的：抽掉就塌","definition":"so basic that removing it would bring the whole structure down","definitionCN":"基础到抽掉它整个结构就会倒塌的","example":"Trust is foundational to the team; without it the rules do not work.","exampleCN":"信任是团队的基础；没有它，规则就不起作用。","why":"The test of a foundation is removal. If taking it away collapses the rest, the word applies.","whyCN":"检验地基的办法是抽掉它。若拿走它其余部分就塌，这个词就用得上。"}],"etymology":{"intro":{"en":"Foundational is foundation plus -al. Foundation comes from Latin fundatio, from fundare 'to lay a base', from fundus 'bottom'. The root pictures the bottom of a structure.","cn":"foundational 是 foundation 加 -al。foundation 来自拉丁 fundatio，出自 fundare“打地基”，而 fundare 又源自 fundus“底部”。词根描绘的是结构的底。"},"items":[{"era":"LATIN FUNDUS","en":"fundus meant 'bottom, base', and also 'a piece of land', because land is the bottom on which things stand. English fund, in the money sense, comes from the same word.","cn":"fundus 意为“底部、基底”，也指“一块土地”，因为土地是万物立足之底。英语中表示资金的 fund 也来自同一个词。"},{"era":"LATIN FUNDARE","en":"fundare 'to lay a bottom, to found' turns the noun into a verb. It was used for founding cities and for laying the base of a building.","cn":"fundare“铺底、奠基”把名词变成动词。它既用于建城，也用于给建筑打地基。"},{"era":"LATIN FUNDATIO","en":"fundatio names the act of founding. English takes it as foundation, which means both the act of founding and the base that results.","cn":"fundatio 命名奠基行为。英语借作 foundation，既指创立行为，也指由此形成的基础。"},{"era":"LATIN FUNDAMENTUM","en":"fundamentum is a parallel noun from the same verb, giving English fundamental. So foundation and fundamental are siblings, both from fundus, not one derived from the other.","cn":"fundamentum 是同一动词的并行名词，生出英语 fundamental。因此 foundation 与 fundamental 是同胞，都来自 fundus，并非一个派生自另一个。"},{"era":"ENGLISH -AL","en":"Foundational adds -al, from Latin -alis, to foundation. The adjective is relatively modern and became common in education and research policy in the 20th century.","cn":"foundational 在 foundation 后加 -al（来自拉丁 -alis）。这个形容词相对晚出，20 世纪在教育与研究政策中变得常见。"}]},"similar":{"note":{"en":"The look-alike group shares the fund- root but splits between bottom and performance; the near-meaning group all describe something prior and load-bearing.","cn":"形近组共享 fund- 词根，但在“底部”与“运作”之间分流；近义组都描述在先且承重之物。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"fundamental","ipa":"/ˌfʌndəˈmentl/","tag":"same root, sibling noun","definition":"forming the base or essence. It comes from fundamentum, a parallel noun to foundation, so the two are siblings rather than parent and child.","definitionCN":"根本的；基本的。它来自 fundamentum，与 foundation 是并行名词，因此二者是同胞而非父子。"},{"word":"foundation","ipa":"/faʊnˈdeɪʃn/","tag":"same root, base noun","definition":"the base of a building or the act of founding. It is the thing; foundational is the adjective.","definitionCN":"地基；创立行为。它是名词；foundational 是形容词。"},{"word":"founder","ipa":"/ˈfaʊndə(r)/","tag":"same root, two senses","definition":"one who founds, or a ship that sinks. Both senses trace to fundus: one who lays the bottom, and one who goes to the bottom.","definitionCN":"创始人；沉没的船。两个义项都可追溯到 fundus：一个铺底的人，一个沉到底的东西。"}]},{"heading":"NEAR MEANING","entries":[{"word":"basic","ipa":"/ˈbeɪsɪk/","tag":"lowest level","definition":"forming the simplest or lowest level. It is plainer and less structural than foundational.","definitionCN":"构成最简单或最低层的。它比 foundational 更朴素，结构意味更弱。"},{"word":"elementary","ipa":"/ˌelɪˈmentri/","tag":"first elements","definition":"concerned with first principles or simple parts. It often refers to early schooling.","definitionCN":"关于基本原理或简单部分的。它常指早期教育。"},{"word":"underlying","ipa":"/ˌʌndəˈlaɪɪŋ/","tag":"lying beneath","definition":"situated below and often hidden, but causing what is seen. It stresses hidden depth rather than load-bearing.","definitionCN":"位于下方、常不可见，却造成可见现象。它强调隐藏深度，而非承重。"},{"word":"rudimentary","ipa":"/ˌruːdɪˈmentri/","tag":"early and undeveloped","definition":"limited to basic principles, often in an incomplete way. It can sound critical, unlike foundational.","definitionCN":"仅限于基本原理，常带不完整之意。它可能带批评色彩，而 foundational 不带。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"fundus 'bottom' gives foundation: foundational marks what sits at the bottom and holds the rest up.","cn":"fundus“底部”生出 foundation：foundational 标记位于底部、托住其余部分的东西。"},{"en":"foundation and fundamental are siblings from fundus and fundamentum, not one from the other.","cn":"foundation 与 fundamental 是来自 fundus 与 fundamentum 的同胞，并非一个派生自另一个。"},{"en":"foundational concept, foundational research and foundational course are the three standard collocations.","cn":"foundational concept、foundational research、foundational course 是三个标准搭配。"},{"en":"The removal test is the quickest check: take it away and see whether the rest collapses.","cn":"抽掉检验是最快的判断法：拿走它，看其余部分是否倒塌。"},{"en":"Do not confuse foundation with function: fundus is bottom, fungi is perform, and the two roots are unrelated.","cn":"别把 foundation 与 function 混淆：fundus 是底部，fungi 是执行，两个词根无关。"}],"abstract":[{"en":"Think of the first stone laid in a trench, with every later course lined up from it.","cn":"想象沟槽里放下的第一块石头，后面每一层都从它起线。"},{"en":"Think of a tree's roots underground, invisible but holding the trunk upright.","cn":"想象树根在地下，看不见，却让树干立着。"},{"en":"Think of a table with one leg removed: the whole thing falls, and that leg was foundational.","cn":"想象一张桌子被抽掉一条腿：整张桌子倒下，那条腿就是基础的。"}]},"examples":[{"en":"The first chapter lays the foundational vocabulary for the rest of the book.","cn":"第一章为全书铺设基础词汇。"},{"en":"Foundational research rarely produces a product within five years.","cn":"基础研究很少在五年内产出产品。"},{"en":"The foundational assumption was never tested, only inherited.","cn":"那个基本假设从未被检验，只是被继承下来。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“放（found）第一块石头”——打地基时先放第一块，后面全压在它上面 → foundational 基础的","word":"foundational"},"root":"拉丁 fundus“底部、基底” → fundare“打地基” → fundatio“奠基” → 英语 foundation + -al；与 fundamental 同出 fundus 但为并行名词。","sensesIntro":{"en":"Eight senses share one test: remove it, and the structure above loses its line.","cn":"八个义项共享一个检验：抽掉它，上面的结构就失去基准线。"},"semanticMap":{"core":{"en":"CORE IMAGE: the first stone laid in a trench.","cn":"核心意象：沟槽里放下的第一块石头。"},"chain":["SIT AT THE BOTTOM","HOLD THE REST UP","COME FIRST IN LEARNING","SUPPORT THE THEORY","SERVE BASIC RESEARCH","BE LOAD-BEARING"],"branches":[{"senses":"01 · 04","en":"LEARNING: basic skills and introductory courses are foundations in depth and in time.","cn":"学习：基础技能与入门课程，是深度与时间两个意义上的地基。"},{"senses":"02 · 07","en":"FOUNDING: a foundational document and a founding meeting both lay down what later institutions repeat.","cn":"创立：奠基性文件与创立会议，都立下后来机构反复遵循的东西。"},{"senses":"03 · 08","en":"LOAD: an assumption and a load-bearing element are both tested by removal rather than by argument.","cn":"承重：假设与承重构件，都靠“抽掉”来检验，而不是靠辩论。"},{"senses":"05","en":"RESEARCH: basic science is valued for what it will support, not for what it sells now.","cn":"研究：基础研究的价值在于它将支撑什么，而不在于它现在卖什么。"},{"senses":"06","en":"SYSTEMS: the lowest software layer must be stable before anything can be stacked on it.","cn":"系统：软件最底层必须稳定，上面才堆得起来。"}]},"affixes":{"intro":{"en":"Foundational is foundation plus -al. The fund- stem means 'bottom', -atio makes an action noun and -al makes the relational adjective.","cn":"foundational 是 foundation 加 -al。fund- 词干意为“底部”，-atio 构成动作名词，-al 构成关系形容词。"},"latinIntro":{"en":"The family grows from fundus 'bottom' through fundare 'lay a base' and fundatio 'founding'. English relatives include found, founder, foundation and fundamental.","cn":"这个词族从 fundus“底部”经 fundare“打地基”与 fundatio“奠基”生长。英语同族词包括 found、founder、foundation、fundamental。"},"items":[{"word":"foundation","structure":"fundare + -tio (action noun)","meaning":"the act of founding; the base","meaningCN":"创立；地基（-tio 动作名词）","example":"The foundation was poured in June.","exampleCN":"地基在六月浇筑。"},{"word":"foundational","structure":"foundation + -al (relational adjective)","meaning":"serving as a base","meaningCN":"基础的；奠基性的（-al 关系形容词）","example":"These are foundational questions.","exampleCN":"这些是基础性问题。"},{"word":"found","structure":"fundare + -are (verb)","meaning":"to establish; to lay a base","meaningCN":"创立；奠基（动词）","example":"The school was founded in 1902.","exampleCN":"这所学校建于 1902 年。"},{"word":"founder","structure":"found + -er (person noun)","meaning":"a person who founds","meaningCN":"创始人（-er 施事名词）","example":"The founder left the city a library.","exampleCN":"创始人给这座城市留下了一座图书馆。"},{"word":"fundamental","structure":"fundamentum + -al (relational adjective)","meaning":"forming the base or essence","meaningCN":"根本的（fundamentum + -al，与 foundation 同胞）","example":"The right to speak is fundamental.","exampleCN":"发言权是根本性的。"},{"word":"fundamentally","structure":"fundamental + -ly (manner adverb)","meaning":"in essence; at the base","meaningCN":"根本上（-ly 方式副词）","example":"The two plans differ fundamentally.","exampleCN":"这两个方案根本不同。"},{"word":"fund","structure":"fundus (bottom, land)","meaning":"money set aside as a base; to provide money","meaningCN":"基金；资助（fundus“底、土地”，金融义另立）","example":"The fund pays for rural clinics.","exampleCN":"该基金支付乡村诊所的费用。"},{"word":"profound","structure":"pro- (forward, down) + fundus (bottom)","meaning":"deep; reaching the bottom","meaningCN":"深刻的（pro- + fundus“底”，同一词根）","example":"The book had a profound effect on her.","exampleCN":"这本书对她影响很深。"}],"latinEntries":[{"word":"fundus","structure":"fundus (bottom, base, farm)","meaning":"bottom, base; a piece of land","meaningCN":"底部；基底；一块土地"},{"word":"fundare","structure":"fundus + -are (verb)","meaning":"to lay a base, to found","meaningCN":"打地基；创立"},{"word":"fundatio","structure":"fundat- + -io (action noun)","meaning":"a founding, a foundation","meaningCN":"奠基；创立"},{"word":"fundamentum","structure":"fundare + -mentum (means noun)","meaning":"a foundation, a base","meaningCN":"基础；地基（fundamental 的直接来源）"}]}},{"word":"functionality","ipa_uk":"/ˌfʌŋkʃəˈnæləti/","ipa_us":"/ˌfʌŋkʃəˈnæləti/","definition_zh":"功能；功能性；功能特性","definition_en":"the set of things a system or device can actually do, or the quality of working as intended","core_image":"一台机器的控制面板上，每个按钮按下后都有对应的灯亮起","scene":"Reviewers praised the app's functionality but asked for a simpler menu.","sceneCN":"这里 functionality 是「功能、功能特性」（第 1 个义项：系统实际能做哪些事）；句意：评审称赞这款应用的功能，但要求菜单更简洁。图中可辨识物件：手机界面、功能按钮、设置菜单、勾选清单。","pos":[{"tag":"n.","zh":"功能；功能性；功能特性"}],"collocations":[{"phrase":"core functionality","zh":"核心功能"},{"phrase":"add functionality","zh":"添加功能"},{"phrase":"loss of functionality","zh":"功能丧失"},{"phrase":"functionality test","zh":"功能测试"},{"phrase":"functionality and usability","zh":"功能性与易用性"},{"phrase":"full functionality","zh":"完整功能"}],"forms":[{"label":"复数","form":"functionalities"}],"derivatives":[{"word":"function","pos":"n./v.","zh":"功能；函数；运作"},{"word":"functional","pos":"adj.","zh":"功能的；实用的"},{"word":"functionally","pos":"adv.","zh":"功能上；从功能角度"},{"word":"malfunction","pos":"n./v.","zh":"故障；发生故障"},{"word":"dysfunction","pos":"n.","zh":"功能障碍"}],"senses":[{"no":"01","title":"The set of things it can do","titleCN":"功能集合：它到底能做哪些事","definition":"the total set of operations that a product or system is able to perform","definitionCN":"产品或系统能够执行的全部操作","example":"The update added functionality for offline editing.","exampleCN":"这次更新增加了离线编辑功能。","why":"functio means 'performance'. Functionality lists the performances a thing can give, taken together as one property.","whyCN":"functio 意为“执行、履行”。functionality 把一件东西能给出的各种“执行”合在一起，当作一个属性。"},{"no":"02","title":"Working order","titleCN":"功能性：还能不能正常用","definition":"the state of working correctly and being usable for its intended purpose","definitionCN":"正常运作、能按其用途使用的状态","example":"The repair restored full functionality to the pump.","exampleCN":"这次维修让水泵恢复了完整功能。","why":"Here the word is a condition, not a list. Something has functionality when its parts still perform their functions.","whyCN":"这里的词是一种状态，而不是清单。当零件仍能履行各自功能时，该物就具有 functionality。"},{"no":"03","title":"Software features","titleCN":"软件功能：版本里带了什么","definition":"the features offered by a piece of software, considered as a selling point","definitionCN":"某软件提供的功能特性，被视为卖点","example":"Users compare the functionality of the two apps before choosing one.","exampleCN":"用户会先比较两款应用的功能，再作选择。","why":"Software made the word common. A program is judged by what its buttons actually do, which is a list of performances.","whyCN":"软件让这个词流行。程序按按钮实际能做什么来评判，而那是一张“执行清单”。"},{"no":"04","title":"Bodily function","titleCN":"生物机能：器官还在工作","definition":"in biology or medicine, the normal operation of an organ or system","definitionCN":"生物学或医学中器官或系统的正常运作","example":"The treatment preserved kidney functionality in most patients.","exampleCN":"该治疗在多数患者身上保住了肾功能。","why":"Biological functionality keeps the original sense of functio: an organ has a job, and functionality is whether it still does it.","whyCN":"生物机能保留 functio 的本义：器官有一项职责，functionality 就是它是否仍在履行。"},{"no":"05","title":"Extra features","titleCN":"附加功能：有当然好，没有也能用","definition":"additional capabilities beyond the essential ones, often optional","definitionCN":"超出基本必需之外的附加能力，常为可选","example":"The basic model lacks the connectivity functionality of the larger one.","exampleCN":"基础型号缺少大型号的联网功能。","why":"This sense is comparative: functionality can be counted and added. More features mean more functions, though not always more usefulness.","whyCN":"这个义项是比较性的：功能可以被计数、被添加。功能多意味着“执行”多，但未必更有用。"},{"no":"06","title":"Testing that it works","titleCN":"功能测试：逐项按一遍","definition":"the aspect of quality assurance concerned with whether each feature works as specified","definitionCN":"质量保证中关注每项功能是否按规格运作的方面","example":"Functionality testing found two buttons that did nothing.","exampleCN":"功能测试发现两个按钮按了没反应。","why":"Testing splits a product into functions and checks each. The word shifts from the property to the activity of verifying it.","whyCN":"测试把产品拆成功能逐项检查。这个词从属性转到验证属性的活动。"},{"no":"07","title":"How useful it really is","titleCN":"实用程度：功能多不等于好用","definition":"the practical usefulness of a product, as distinct from the number of features listed","definitionCN":"产品的实际有用程度，区别于所列功能的数量","example":"The camera's functionality is limited by its slow autofocus.","exampleCN":"这款相机的实用性受限于它缓慢的自动对焦。","why":"A long feature list can hide weak performance. Functionality in this sense asks whether the functions actually serve the user.","whyCN":"长长的功能清单可能掩盖薄弱性能。这个义项的 functionality 问的是这些功能是否真的服务于用户。"},{"no":"08","title":"Completeness of function","titleCN":"功能完整性：该有的都有","definition":"the degree to which all expected functions are present and working","definitionCN":"所有预期功能都存在并正常运作的程度","example":"The prototype has the functionality of the final product but not its finish.","exampleCN":"样机具备最终产品的功能，但没有它的外观工艺。","why":"This sense measures completeness against a specification. The question is not how many features but whether any required one is missing.","whyCN":"这个义项对照规格衡量完整性。问题不是功能多少，而是有没有漏掉必需的那一项。"}],"etymology":{"intro":{"en":"Functionality is functional plus -ity. Functional comes from function, from Latin functio 'performance', from fungi 'to perform'. The root is fung-, not fund-, and has nothing to do with 'bottom'.","cn":"functionality 是 functional 加 -ity。functional 来自 function，而 function 出自拉丁 functio“执行”，源头是 fungi“履行”。词根是 fung-，不是 fund-，与“底部”无关。"},"items":[{"era":"LATIN FUNGI","en":"fungi meant 'to perform, discharge, carry out'. The past participle functus gives the whole family; the root is unrelated to fundus 'bottom'.","cn":"fungi 意为“履行、执行、完成”。过去分词 functus 生出整个词族；这个词根与 fundus“底部”无关。"},{"era":"LATIN FUNCTIO","en":"functio named a performance or discharge, including a duty or an official role. The word already carried the idea of a job being done.","cn":"functio 命名一次执行或履行，包括职责与公职。这个词已带有“完成一项任务”的观念。"},{"era":"ENGLISH FUNCTION","en":"English function arrives in the 16th century with both the 'duty, role' sense and the mathematical sense. The mathematical use grows in the 17th and 18th centuries.","cn":"英语 function 于 16 世纪进入，兼有“职责、角色”义与数学义。数学用法在 17 至 18 世纪发展。"},{"era":"ENGLISH FUNCTIONAL","en":"Functional adds -al to function, meaning 'relating to function'. In the 19th and 20th centuries it also means 'practical rather than decorative', especially in design.","cn":"functional 在 function 后加 -al，意为“与功能有关的”。19 至 20 世纪它也指“实用而非装饰的”，尤见于设计。"},{"era":"ENGLISH -ITY","en":"Functionality adds -ity to functional, forming the abstract noun. The word becomes common with 20th-century engineering and computing.","cn":"functionality 在 functional 后加 -ity，构成抽象名词。这个词随 20 世纪工程与计算机而流行。"},{"era":"SOFTWARE ERA","en":"In the late 20th century software marketing fixes functionality as a countable feature set, giving the plural functionalities wide use.","cn":"20 世纪后期软件营销把 functionality 固定为可计数的功能集，使复数 functionalities 广泛使用。"}]},"similar":{"note":{"en":"The look-alike group shares the funct- stem; the near-meaning group all concern what a thing can do or how well it does it.","cn":"形近组共享 funct- 词干；近义组都关于某物能做什么或做得多好。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"function","ipa":"/ˈfʌŋkʃn/","tag":"same root, base noun","definition":"a purpose, role or mathematical relation. It is one function; functionality is the whole set or the working state.","definitionCN":"用途、职责或数学关系。它是单个功能；functionality 是整套功能或运作状态。"},{"word":"functional","ipa":"/ˈfʌŋkʃənl/","tag":"same root, adjective","definition":"relating to function, or practical. It describes a thing; functionality names the property.","definitionCN":"功能的；实用的。它描述事物；functionality 命名属性。"},{"word":"malfunction","ipa":"/ˌmælˈfʌŋkʃn/","tag":"different prefix, same root","definition":"a failure to work properly. mal- means 'badly', so it is the negative of function, while functionality can still be partial.","definitionCN":"故障；运作失常。mal- 意为“坏地”，是 function 的反面，而 functionality 仍可能是部分的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"capability","ipa":"/ˌkeɪpəˈbɪləti/","tag":"what it is able to do","definition":"the power or ability to do something. It is broader and can include potential not yet used.","definitionCN":"做某事的能力。它更宽泛，可包含尚未使用的潜力。"},{"word":"feature","ipa":"/ˈfiːtʃə(r)/","tag":"one offered item","definition":"a distinctive part or function of a product. It is one item; functionality is the collection.","definitionCN":"产品的特色部分或功能。它是一项；functionality 是集合。"},{"word":"utility","ipa":"/juːˈtɪləti/","tag":"usefulness","definition":"the quality of being useful, or a public service. It stresses benefit rather than operation.","definitionCN":"有用性，或公用事业。它强调益处，而非运作。"},{"word":"performance","ipa":"/pəˈfɔːməns/","tag":"how well it works","definition":"how well a machine or system carries out its tasks. It adds speed and reliability to the bare idea of function.","definitionCN":"机器或系统执行任务的优劣。它在“功能”之上加了速度与可靠性。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"fungi 'perform' gives function: functionality is the sum of what a thing can perform.","cn":"fungi“履行”生出 function：functionality 就是一件东西能履行的全部事情。"},{"en":"function, functional, functionality form the noun-adjective-noun chain of one root.","cn":"function、functional、functionality 构成同一词根的名词—形容词—名词链条。"},{"en":"core functionality and full functionality are the two common extremes: the minimum and the complete set.","cn":"core functionality 与 full functionality 是两个常见极端：最低必需与完整集合。"},{"en":"Keep fund- and fung- apart: foundation is 'bottom', function is 'perform'.","cn":"把 fund- 与 fung- 分开：foundation 是“底部”，function 是“执行”。"},{"en":"A feature is one thing it does; functionality is the whole list or the fact that it still works.","cn":"feature 是它做的一件事；functionality 是整张清单，或它仍能工作的状态。"}],"abstract":[{"en":"Think of a control panel where every button lights up a different lamp.","cn":"想象一块控制面板，每个按钮都点亮一盏不同的灯。"},{"en":"Think of a toolbox: the tools are features, and the box's usefulness is its functionality.","cn":"想象一个工具箱：每件工具是功能点，整个箱子的用处就是它的 functionality。"},{"en":"Think of a body whose organs each do their job, so the whole person still works.","cn":"想象身体各器官各司其职，整个人因此仍能运作。"}]},"examples":[{"en":"The new version adds functionality without changing the interface.","cn":"新版本增加了功能，却没有改动界面。"},{"en":"Restoring functionality after the flood took four months.","cn":"洪水后恢复功能花了四个月。"},{"en":"Functionality testing is separate from usability testing.","cn":"功能测试与易用性测试是分开的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“方（fun）壳（ction）里能做的事”——一个方壳子机器，按下按钮能干什么 → functionality 功能","word":"functionality"},"root":"拉丁 fungi“履行、执行” → functio“执行” → 英语 function → functional → functionality；注意词根是 fung-，与 fund-（底部）无关。","sensesIntro":{"en":"Eight senses share one question, asked of a machine, a program or an organ: what can it actually perform, and does it still perform it?","cn":"八个义项共享一个问题，用来问机器、程序或器官：它实际能执行什么，现在还能不能执行？"},"semanticMap":{"core":{"en":"CORE IMAGE: a control panel where each button lights its own lamp.","cn":"核心意象：一块控制面板，每个按钮点亮自己的灯。"},"chain":["PERFORM A TASK","LIST THE TASKS","KEEP THEM WORKING","SELL THEM AS FEATURES","TEST EACH ONE","JUDGE THE WHOLE"],"branches":[{"senses":"01 · 05","en":"THE SET: the full list and the optional extras are the same collection seen with and without its edges.","cn":"集合：完整清单与附加功能，是同一集合带着边界和不带边界的样子。"},{"senses":"02 · 08","en":"WORKING ORDER: full functionality and functional completeness both ask whether anything required has stopped.","cn":"运作状态：完整功能与功能完整性，都在问是否有必需功能停了。"},{"senses":"03","en":"SOFTWARE: features become selling points, turning performances into a comparison table.","cn":"软件：功能变成卖点，把“执行”变成一张对比表。"},{"senses":"04","en":"BODY: an organ keeps its job, and functionality is whether it still discharges it.","cn":"身体：器官有其职责，functionality 就是它是否仍在履行。"},{"senses":"06 · 07","en":"JUDGMENT: testing each feature and judging real usefulness both ask whether the list means anything in practice.","cn":"判断：逐项测试与评判实际用处，都在问这张清单在现实中是否有意义。"}]},"affixes":{"intro":{"en":"Functionality is functional plus -ity. The funct- stem means 'perform', -ion makes an action noun, -al makes a relational adjective and -ity makes the quality noun.","cn":"functionality 是 functional 加 -ity。funct- 词干意为“履行”，-ion 构成动作名词，-al 构成关系形容词，-ity 构成性质名词。"},"latinIntro":{"en":"The family runs from fungi 'perform' through functio 'performance' to English function. Relatives include functional, malfunction, defunct and functionary.","cn":"这个词族从 fungi“履行”经 functio“执行”到英语 function。同族词包括 functional、malfunction、defunct、functionary。"},"items":[{"word":"function","structure":"functio + -ion (action noun)","meaning":"a role, purpose or mathematical relation","meaningCN":"功能；职责；函数（-ion 动作名词）","example":"The heart's function is to pump blood.","exampleCN":"心脏的功能是泵血。"},{"word":"functional","structure":"function + -al (relational adjective)","meaning":"relating to function; practical","meaningCN":"功能的；实用的（-al 关系形容词）","example":"The chair is functional rather than beautiful.","exampleCN":"这把椅子重在实用，不在美观。"},{"word":"functionality","structure":"functional + -ity (quality noun)","meaning":"the set or quality of functions","meaningCN":"功能；功能性（-ity 性质名词）","example":"The device's functionality is limited.","exampleCN":"该设备的功能有限。"},{"word":"functionally","structure":"functional + -ly (manner adverb)","meaning":"in terms of function","meaningCN":"功能上（-ly 方式副词）","example":"The two parts are functionally identical.","exampleCN":"这两个部件在功能上完全相同。"},{"word":"malfunction","structure":"mal- (badly) + function","meaning":"a failure to work","meaningCN":"故障（mal-“坏地”+ function）","example":"A sensor malfunction stopped the line.","exampleCN":"一个传感器故障让生产线停了。"},{"word":"dysfunction","structure":"dys- (badly) + function","meaning":"abnormal or impaired function","meaningCN":"功能障碍（dys-“不良”+ function）","example":"The drug treats liver dysfunction.","exampleCN":"这种药治疗肝功能障碍。"},{"word":"defunct","structure":"de- (away) + functus (performed)","meaning":"no longer working or existing","meaningCN":"已废止的；不再运作的（de-“离开”+ functus“已履行”）","example":"The defunct factory was sold.","exampleCN":"那家停产的工厂被卖掉了。"},{"word":"functionary","structure":"function + -ary (person noun)","meaning":"an official with a defined role","meaningCN":"官员；职员（-ary 人称名词）","example":"A junior functionary signed the form.","exampleCN":"一名低级职员签了那张表。"}],"latinEntries":[{"word":"fungi","structure":"fungi (to perform)","meaning":"to perform, discharge","meaningCN":"履行；执行"},{"word":"functio","structure":"funct- + -io (action noun)","meaning":"a performance, a discharge","meaningCN":"执行；履行"},{"word":"functus","structure":"past participle of fungi","meaning":"having performed","meaningCN":"已履行的（过去分词）"},{"word":"functor","structure":"funct- + -or (agent)","meaning":"one who performs","meaningCN":"执行者（-or 施事名词）"}]}},{"word":"functional","ipa_uk":"/ˈfʌŋkʃənl/","ipa_us":"/ˈfʌŋkʃənl/","definition_zh":"功能的；实用的；起作用的；函数式的","definition_en":"relating to how something works or operates; designed to be practical rather than decorative","core_image":"一把没有花纹、但每处弯折都贴合手掌的椅子","scene":"The prototype looks rough, but it is functional and survives daily use.","sceneCN":"这里 functional 是「实用的、能正常工作的」（第 2 个义项：重在能用而不是好看）；句意：样机看着粗糙，但很实用，经得住日常使用。图中可辨识物件：木椅原型、工具、磨损痕迹、测试台。","pos":[{"tag":"adj.","zh":"功能的；实用的；函数式的；（医学）功能性的"}],"collocations":[{"phrase":"functional design","zh":"功能主义设计"},{"phrase":"functional requirement","zh":"功能需求"},{"phrase":"functional programming","zh":"函数式编程"},{"phrase":"functional disorder","zh":"功能性疾病"},{"phrase":"fully functional","zh":"功能完全的；完全可用的"},{"phrase":"functional unit","zh":"功能单位"}],"forms":[{"label":"比较级","form":"more functional"},{"label":"最高级","form":"most functional"}],"derivatives":[{"word":"function","pos":"n./v.","zh":"功能；函数；运作"},{"word":"functionality","pos":"n.","zh":"功能；功能性"},{"word":"functionally","pos":"adv.","zh":"功能上"},{"word":"functionalism","pos":"n.","zh":"功能主义"},{"word":"dysfunctional","pos":"adj.","zh":"功能失调的；运作不良的"}],"senses":[{"no":"01","title":"Relating to function","titleCN":"功能的：讲它怎么运作","definition":"concerned with how something works rather than with how it looks","definitionCN":"关注某物如何运作、而非外观的","example":"The report gives a functional description of the engine, not a drawing.","exampleCN":"这份报告给出的是发动机的功能描述，而不是图纸。","why":"functio means 'performance'. Functional marks the question 'what does it do?', leaving appearance and origin aside.","whyCN":"functio 意为“执行”。functional 标记的是“它做什么”这个问题，把外观与来源放在一边。"},{"no":"02","title":"Practical and working","titleCN":"实用的：能用就行","definition":"designed to be useful and to work well, without decoration","definitionCN":"设计上追求好用、能运作，不加装饰的","example":"The kitchen is small but highly functional.","exampleCN":"这间厨房很小，但非常实用。","why":"Modern design made functional a virtue. A functional object is judged by whether it performs its job, not by ornament.","whyCN":"现代设计把 functional 变成一种美德。评判一件 functional 的物品，看它是否履行职责，而不是看装饰。"},{"no":"03","title":"Functional design","titleCN":"功能主义的：形式跟着用途走","definition":"in architecture and design, following the principle that form should serve use","definitionCN":"建筑与设计中遵循“形式服从用途”原则的","example":"The building's functional style leaves the concrete and glass bare.","exampleCN":"这栋建筑的功能主义风格让混凝土与玻璃保持素面。","why":"This sense names a movement, not just a quality. Functionalism turned 'what it does' into a rule for 'how it should look'.","whyCN":"这个义项命名的是一场运动，而不只是性质。功能主义把“它做什么”变成“它该长什么样”的规则。"},{"no":"04","title":"Organized by role","titleCN":"按职能划分的：谁管什么","definition":"describing an organization divided by the work each part performs rather than by product or region","definitionCN":"指按各部分承担的工作而非产品或地区划分的组织结构","example":"The company moved from a regional to a functional structure.","exampleCN":"公司从地区型结构转为职能型结构。","why":"In management the function is a department's job. A functional structure groups people by what they do, not by where they sit.","whyCN":"管理中的 function 是部门的职责。职能型结构按“做什么”分组，而不是按“在哪里”分组。"},{"no":"05","title":"Mathematics and programming","titleCN":"函数式的：把计算当函数","definition":"in mathematics and computing, relating to functions or to a style of programming based on them","definitionCN":"数学与计算中与函数有关，或指以函数为基础的编程风格","example":"Functional programming treats computation as the evaluation of functions.","exampleCN":"函数式编程把计算视为对函数的求值。","why":"The mathematical function is a fixed mapping from input to output. Functional programming builds everything from such mappings.","whyCN":"数学函数是从输入到输出的固定映射。函数式编程用这类映射构建一切。"},{"no":"06","title":"Medical: no visible damage","titleCN":"功能性的：查不出器质病变","definition":"in medicine, describing a disorder in which the organ works badly without structural damage","definitionCN":"医学上指器官运作不良但没有结构损害的疾病","example":"She was diagnosed with a functional bowel disorder.","exampleCN":"她被诊断为功能性肠病。","why":"Here functional marks the absence of structural cause. The complaint is real, but the tests show a working organ behaving badly.","whyCN":"这里的 functional 标记“没有结构病因”。症状真实，但检查显示器官结构正常、运作失常。"},{"no":"07","title":"Operational and usable","titleCN":"可运作的：装好就能转","definition":"in a state of working order, ready to be used","definitionCN":"处于可运作状态、随时可使用的","example":"The website is functional again after the server move.","exampleCN":"服务器迁移之后，网站又能正常使用了。","why":"This is the condition sense: not how it is designed, but whether it currently runs. A functional machine is one that answers when switched on.","whyCN":"这是状态义：不是问如何设计，而是问现在是否运转。functional 的机器就是打开开关会响应的机器。"},{"no":"08","title":"Grammar that follows use","titleCN":"功能语法的：按用途解释形式","definition":"in linguistics, describing an approach that explains forms by the jobs they perform in communication","definitionCN":"语言学中指按形式在交流中承担的作用来解释形式的取向","example":"Functional grammar asks why a passive is chosen, not just how it is formed.","exampleCN":"功能语法问的是为什么选被动式，而不只是它如何构成。","why":"Linguistics uses the word for explanations based on use. A form exists because it does a job, which is the functional argument in one line.","whyCN":"语言学用这个词指基于用途的解释。形式存在是因为它承担一项任务，这就是功能论证的一句话版本。"}],"etymology":{"intro":{"en":"Functional is function plus -al. Function comes from Latin functio 'performance', from fungi 'to perform'. The root is fung-, unrelated to fundus 'bottom'; the word concerns doing, not founding.","cn":"functional 是 function 加 -al。function 来自拉丁 functio“执行”，源头是 fungi“履行”。词根是 fung-，与 fundus“底部”无关；这个词讲“做”，不讲“奠基”。"},"items":[{"era":"LATIN FUNGI","en":"fungi 'to perform, discharge' is the source. Its past participle functus produces function, defunct and functionary; the root has no connection with fundus.","cn":"fungi“履行、执行”是源头。其过去分词 functus 生出 function、defunct、functionary；这个词根与 fundus 没有联系。"},{"era":"LATIN FUNCTIO","en":"functio named the discharge of a duty or role. English function keeps both the everyday 'purpose' sense and the mathematical 'mapping' sense.","cn":"functio 命名职责或角色的履行。英语 function 同时保留日常“用途”义与数学“映射”义。"},{"era":"ENGLISH FUNCTION","en":"Function enters English in the 16th century. The mathematical sense develops later, once algebra needs a word for a relation between quantities.","cn":"function 于 16 世纪进入英语。数学义较晚发展，是代数需要一个词来表示量之间关系的结果。"},{"era":"ENGLISH -AL","en":"Functional adds -al, from Latin -alis, to function. The adjective first means 'relating to a function', then 'practical' in design language.","cn":"functional 在 function 后加 -al（来自拉丁 -alis）。这个形容词先指“与功能有关”，后来在设计语言中转为“实用的”。"},{"era":"DESIGN MOVEMENT","en":"In the 20th century functional becomes a slogan of architecture and design, where form is supposed to follow use.","cn":"20 世纪 functional 成为建筑与设计的口号，主张形式服从用途。"},{"era":"COMPUTING AND MEDICINE","en":"Functional programming names a computing style, while functional disorder names illness without structural damage. Both keep the same root idea of performance.","cn":"函数式编程命名一种计算风格，而功能性疾病命名无结构损害的疾病。两者都保留“执行”的词根观念。"}]},"similar":{"note":{"en":"The look-alike group shares the funct- stem but splits by suffix and prefix; the near-meaning group all describe something judged by use rather than appearance.","cn":"形近组共享 funct- 词干，但按后缀与前缀分流；近义组都描述“按用途而非外观评判”的东西。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"function","ipa":"/ˈfʌŋkʃn/","tag":"same root, base noun","definition":"a purpose, role or mathematical relation. It is the thing; functional describes it.","definitionCN":"用途、职责或数学关系。它是名词；functional 描述它。"},{"word":"functionality","ipa":"/ˌfʌŋkʃəˈnæləti/","tag":"same root, abstract noun","definition":"the set of functions or the working state. It is a noun; functional is the adjective.","definitionCN":"功能集合或运作状态。它是名词；functional 是形容词。"},{"word":"defunct","ipa":"/dɪˈfʌŋkt/","tag":"different prefix, same root","definition":"no longer existing or working. de- 'away' plus functus 'performed' gives 'having finished performing'.","definitionCN":"已废止的；不再运作的。de-“离开”加 functus“已履行”，意为“已停止履行”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"practical","ipa":"/ˈpræktɪkl/","tag":"useful in real use","definition":"useful and sensible in real conditions. It is wider than functional and often about judgment.","definitionCN":"在真实条件下有用且合理。它比 functional 宽泛，常涉及判断。"},{"word":"operational","ipa":"/ˌɒpəˈreɪʃənl/","tag":"ready to run","definition":"in working order and ready for use. It stresses readiness, while functional can also describe design.","definitionCN":"处于运作状态、可供使用。它强调就绪，而 functional 也可描述设计。"},{"word":"utilitarian","ipa":"/ˌjuːtɪlɪˈteəriən/","tag":"useful over beautiful","definition":"designed for usefulness, often at the cost of beauty. It is more judgmental than functional.","definitionCN":"为实用而设计，常牺牲美观。它比 functional 更具评价色彩。"},{"word":"serviceable","ipa":"/ˈsɜːvɪsəbl/","tag":"fit for service","definition":"good enough to use, though not elegant. It is close to functional but implies adequacy rather than design intent.","definitionCN":"够用、可服役的，虽不精美。它接近 functional，但暗示“够用”而非设计意图。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"fungi 'perform' gives function and functional: the word always asks what a thing performs.","cn":"fungi“履行”生出 function 与 functional：这个词始终在问一件东西履行什么。"},{"en":"functional design, functional requirement and functional programming are the three strongest collocations.","cn":"functional design、functional requirement、functional programming 是三个最强的搭配。"},{"en":"functional disorder means the organ looks fine but works badly, which shows the word is about performance.","cn":"functional disorder 指器官外观正常却运作不良，说明这个词讲的是“执行”。"},{"en":"Do not confuse functional with foundational: fung- is perform, fund- is bottom.","cn":"别把 functional 与 foundational 混淆：fung- 是执行，fund- 是底部。"},{"en":"A functional object is not necessarily beautiful, and a beautiful object is not necessarily functional.","cn":"functional 的物品不一定美，美的物品不一定 functional。"}],"abstract":[{"en":"Think of a chair with no ornament whose every angle fits the body.","cn":"想象一把没有装饰、每个角度都贴合身体的椅子。"},{"en":"Think of a machine that starts on the first try, with no light and no sound wasted.","cn":"想象一台一次就启动的机器，不浪费一点灯光与声音。"},{"en":"Think of a toolbox where each tool sits in the slot shaped for it.","cn":"想象工具箱里每件工具都放在为它开好的槽里。"}]},"examples":[{"en":"The prototype is functional but too heavy to carry.","cn":"样机可以正常使用，但太重，带不动。"},{"en":"Functional requirements describe what the system must do.","cn":"功能需求描述系统必须做什么。"},{"en":"The patient had functional symptoms but normal scans.","cn":"患者有功能性症状，但扫描正常。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“放（fun）进去就能用”——功能（function）先放进去，能用就是 functional 实用的","word":"functional"},"root":"拉丁 fungi“履行、执行” → functio“执行” → 英语 function + -al；词根为 fung-，与 fund-（底部）无关。","sensesIntro":{"en":"Eight senses share one standard: judge it by what it performs, not by what it looks like or where it came from.","cn":"八个义项共享一个标准：按它履行什么来评判，而不是按外观或来源。"},"semanticMap":{"core":{"en":"CORE IMAGE: an unornamented chair shaped to the body.","cn":"核心意象：一把没有装饰、贴合身体的椅子。"},"chain":["WHAT IT DOES","HOW IT WORKS","USEFUL OVER PRETTY","FORM FOLLOWS USE","GROUPED BY ROLE","READY TO RUN"],"branches":[{"senses":"01 · 02 · 07","en":"PERFORMANCE: describing a function, being practical and being in working order are three views of the same 'it works'.","cn":"执行：描述功能、实用、处于可运作状态，是同一个“它能工作”的三种视角。"},{"senses":"03","en":"DESIGN: functionalism turns performance into a rule for appearance.","cn":"设计：功能主义把“性能”变成外观规则。"},{"senses":"04","en":"ORGANIZATION: a functional structure groups people by the job they perform.","cn":"组织：职能型结构按人们履行的职责分组。"},{"senses":"05 · 08","en":"ABSTRACT SYSTEMS: mathematics, programming and grammar all explain forms by the mappings or jobs they perform.","cn":"抽象系统：数学、编程与语法都用“执行的映射或任务”来解释形式。"},{"senses":"06","en":"MEDICINE: functional marks real symptoms without structural damage, the same 'performance' focus.","cn":"医学：functional 标记真实症状而无结构损害，仍是同一种“执行”焦点。"}]},"affixes":{"intro":{"en":"Functional is function plus -al. The funct- stem means 'perform', -ion makes an action noun and -al makes the relational adjective.","cn":"functional 是 function 加 -al。funct- 词干意为“履行”，-ion 构成动作名词，-al 构成关系形容词。"},"latinIntro":{"en":"The family runs from fungi 'perform' through functio 'performance' to English function. Relatives include functional, malfunction, defunct and functionary.","cn":"这个词族从 fungi“履行”经 functio“执行”到英语 function。同族词包括 functional、malfunction、defunct、functionary。"},"items":[{"word":"function","structure":"functio + -ion (action noun)","meaning":"a role, purpose or mapping","meaningCN":"功能；职责；函数（-ion 动作名词）","example":"The function of the valve is to release pressure.","exampleCN":"阀门的功能是释放压力。"},{"word":"functional","structure":"function + -al (relational adjective)","meaning":"relating to function; practical","meaningCN":"功能的；实用的（-al 关系形容词）","example":"The design is purely functional.","exampleCN":"这个设计完全以功能为主。"},{"word":"functionality","structure":"functional + -ity (quality noun)","meaning":"the set or quality of functions","meaningCN":"功能；功能性（-ity 性质名词）","example":"The update improved functionality.","exampleCN":"这次更新提升了功能。"},{"word":"functionally","structure":"functional + -ly (manner adverb)","meaning":"in terms of function","meaningCN":"功能上（-ly 方式副词）","example":"The two switches are functionally equivalent.","exampleCN":"两个开关在功能上等效。"},{"word":"functionalism","structure":"functional + -ism (system noun)","meaning":"the principle that form should follow use","meaningCN":"功能主义（-ism 体系名词）","example":"Functionalism dominated architecture in the 1920s.","exampleCN":"功能主义在 1920 年代主导建筑界。"},{"word":"malfunction","structure":"mal- (badly) + function","meaning":"a failure to perform","meaningCN":"故障（mal-“坏地”+ function）","example":"The malfunction was traced to a loose wire.","exampleCN":"故障追查到一根松动的电线。"},{"word":"defunct","structure":"de- (away) + functus (performed)","meaning":"no longer performing or existing","meaningCN":"已废止的（de-“离开”+ functus“已履行”）","example":"The defunct railway is now a path.","exampleCN":"废弃的铁路如今成了一条小路。"},{"word":"dysfunctional","structure":"dys- (badly) + functional","meaning":"working badly or abnormally","meaningCN":"功能失调的（dys-“不良”+ functional）","example":"The dysfunctional team missed every deadline.","exampleCN":"这个功能失调的团队错过了每个截止期。"}],"latinEntries":[{"word":"fungi","structure":"fungi (to perform)","meaning":"to perform, discharge","meaningCN":"履行；执行"},{"word":"functio","structure":"funct- + -io (action noun)","meaning":"a performance, a discharge","meaningCN":"执行；履行"},{"word":"functus","structure":"past participle of fungi","meaning":"having performed","meaningCN":"已履行的（过去分词）"},{"word":"functio officii","structure":"functio + officii (of a duty)","meaning":"the discharge of a duty","meaningCN":"职责的履行（拉丁搭配）"}]}},{"word":"fundamentally","ipa_uk":"/ˌfʌndəˈmentəli/","ipa_us":"/ˌfʌndəˈmentəli/","definition_zh":"根本上；基本上；彻底地","definition_en":"in a way that concerns the basic nature or underlying structure of something","core_image":"一座房子的地梁被挖开，露出决定整栋楼稳不稳的那一层","scene":"The two proposals differ fundamentally on who pays for maintenance.","sceneCN":"这里 fundamentally 是「根本上」（第 1 个义项：涉及最底层的性质或结构）；句意：两份提案在“谁承担维护费”这一点上根本不同。图中可辨识物件：地基剖面、两份文件、对比标记、计算器。","pos":[{"tag":"adv.","zh":"根本上；基本上；彻底地"}],"collocations":[{"phrase":"fundamentally different","zh":"根本不同的"},{"phrase":"fundamentally change","zh":"从根本上改变"},{"phrase":"fundamentally flawed","zh":"根本上有缺陷的"},{"phrase":"fundamentally about","zh":"本质上是关于……的"},{"phrase":"fundamentally important","zh":"至关重要的"},{"phrase":"fundamentally sound","zh":"从根本上稳固的"}],"forms":[{"label":"比较级","form":"more fundamentally"},{"label":"最高级","form":"most fundamentally"}],"derivatives":[{"word":"fundamental","pos":"adj./n.","zh":"根本的；基本原理"},{"word":"fundament","pos":"n.","zh":"基础；臀部（古义）"},{"word":"foundation","pos":"n.","zh":"基础；地基"},{"word":"fundamentally","pos":"adv.","zh":"根本上"},{"word":"fundamentals","pos":"n.","zh":"基本原理；基本面"}],"senses":[{"no":"01","title":"In essence","titleCN":"本质上：说到底是什么","definition":"in terms of the essential nature of something, apart from surface details","definitionCN":"就某物的本质而言，撇开表面细节","example":"The dispute is fundamentally about who controls the water.","exampleCN":"这场争端本质上是关于谁控制水源。","why":"fundamentum is a foundation. Fundamentally moves the statement down to the base, where the real difference lies.","whyCN":"fundamentum 是地基。fundamentally 把陈述移到基座处，真正的差别就在那里。"},{"no":"02","title":"At the base","titleCN":"从根本上：从底上动","definition":"at the level of the underlying structure rather than its surface","definitionCN":"在底层结构层面，而非表面层面","example":"The reform changed the tax system fundamentally.","exampleCN":"这项改革从根本上改变了税制。","why":"The adverb keeps the building image: a change at the base spreads to everything above it, unlike a change to the paint.","whyCN":"这个副词保留建筑意象：基座处的变化会传到上方一切，而不像刷一层漆。"},{"no":"03","title":"Thoroughly, completely","titleCN":"彻底地：一点没剩","definition":"to a complete degree, so that little of the original remains","definitionCN":"达到完全的程度的，以致原状所剩无几","example":"The discovery fundamentally altered our understanding of the disease.","exampleCN":"这一发现彻底改变了我们对这种病的理解。","why":"A base change is necessarily total: if the foundation moves, the whole building moves. Hence the sense 'completely'.","whyCN":"基座的变化必然是整体的：地基一动，整栋楼都动。因此引申出“彻底地”。"},{"no":"04","title":"Structurally","titleCN":"结构上：骨架层面","definition":"with respect to the structure or framework of a system","definitionCN":"就系统的结构或框架而言","example":"The two economies are fundamentally similar despite different politics.","exampleCN":"尽管政治不同，两个经济体在结构上相似。","why":"Here the base is a framework rather than a physical foundation. The adverb compares skeletons, not surfaces.","whyCN":"这里的地基是框架而非实物基础。这个副词比较的是骨架，不是表面。"},{"no":"05","title":"In principle","titleCN":"原则上：道理上说得通","definition":"according to the basic principles rather than the practical details","definitionCN":"依据基本原则，而非实际细节","example":"Fundamentally, the method is sound; the failures are in execution.","exampleCN":"原则上这个方法站得住，失败出在执行上。","why":"Principles are the foundation of an argument. Saying 'fundamentally sound' separates the base from the work built on it.","whyCN":"原则是论证的地基。说 fundamentally sound，就是把基座与其上所建的工作分开。"},{"no":"06","title":"At the most basic level","titleCN":"最基础层面上：再往下没有了","definition":"at the lowest level of explanation, beyond which there is nothing more basic","definitionCN":"在解释的最低层级，再往下没有更基础的东西","example":"Fundamentally, all these machines obey the same three laws.","exampleCN":"在最基础的层面上，所有这些机器都遵循同样三条定律。","why":"This sense marks the floor of an explanation. The adverb says: stop digging, you have reached the bottom.","whyCN":"这个义项标记解释的地板。这个副词等于说：别挖了，到底了。"},{"no":"07","title":"Irreconcilably different","titleCN":"根本对立地：谈不拢的那种不同","definition":"describing differences so deep that no compromise can bridge them","definitionCN":"指分歧深到任何妥协都无法弥合","example":"Their views on the role of the state are fundamentally opposed.","exampleCN":"他们对国家角色的看法根本对立。","why":"When two foundations sit in different places, no amount of building joins them. The adverb signals a gap at the base, not at the surface.","whyCN":"当地基在两处不同位置，再多的建造也接不上。这个副词标记的是基座处的裂缝，不是表面的。"},{"no":"08","title":"In terms of fundamentals","titleCN":"就基本面而言","definition":"judged by basic economic or technical conditions rather than by mood or price swings","definitionCN":"按基本经济或技术条件来评判，而非按情绪或价格波动","example":"Fundamentally, the company is healthy; the share price says otherwise.","exampleCN":"就基本面而言，公司是健康的；股价说的却是另一回事。","why":"Finance uses fundamentals for the base conditions. The adverb sets the market's noise against the structure underneath.","whyCN":"金融用 fundamentals 指基础条件。这个副词把市场的噪音与底下的结构对照起来。"}],"etymology":{"intro":{"en":"Fundamentally is fundamental plus -ly. Fundamental comes from Latin fundamentalis, from fundamentum 'foundation', from fundare 'to lay a base', from fundus 'bottom'. The word points down to the base.","cn":"fundamentally 是 fundamental 加 -ly。fundamental 来自拉丁 fundamentalis，出自 fundamentum“地基”，而 fundamentum 又源自 fundare“打地基”与 fundus“底部”。这个词指向下面的基座。"},"items":[{"era":"LATIN FUNDUS","en":"fundus meant 'bottom, base', and also 'a piece of land'. The base of anything is what everything else rests on, which is why the word also means the ground itself.","cn":"fundus 意为“底部、基底”，也指“一块土地”。任何东西的底部都是其余部分赖以支撑之处，因此这个词也指土地本身。"},{"era":"LATIN FUNDARE","en":"fundare 'to lay a base, to found' is the verb. It applies to buildings, cities and institutions alike, since all of them need a base.","cn":"fundare“铺底、奠基”是动词。它同样适用于建筑、城市与制度，因为三者都需要基座。"},{"era":"LATIN FUNDAMENTUM","en":"fundamentum is the noun for a foundation, built with the means suffix -mentum. English fundamental comes from its adjective fundamentalis, not from foundation.","cn":"fundamentum 是表示地基的名词，带手段后缀 -mentum。英语 fundamental 来自其形容词 fundamentalis，而不是来自 foundation。"},{"era":"ENGLISH FUNDAMENTAL","en":"English fundamental appears in the 15th century meaning 'serving as a foundation'. It is used for principles as well as physical bases.","cn":"英语 fundamental 于 15 世纪出现，意为“作为基础的”。它既用于物理基座，也用于原则。"},{"era":"ENGLISH -LY","en":"Fundamentally adds -ly to the adjective, forming an adverb of manner or viewpoint. It becomes common in academic argument in the 18th and 19th centuries.","cn":"fundamentally 在形容词后加 -ly，构成方式或视角副词。18 至 19 世纪它成为学术论证中的常用词。"}]},"similar":{"note":{"en":"The look-alike group shares the fund- root; the near-meaning group all intensify a statement about what something really is.","cn":"形近组共享 fund- 词根；近义组都强化“某物究竟是什么”的陈述。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"fundamental","ipa":"/ˌfʌndəˈmentl/","tag":"same root, adjective","definition":"forming the base or essence. It is the adjective; fundamentally is its adverb.","definitionCN":"根本的；基本的。它是形容词；fundamentally 是其副词。"},{"word":"fundament","ipa":"/ˈfʌndəmənt/","tag":"same root, base noun","definition":"the base or foundation of something; also the buttocks in older use. It is the direct noun behind fundamental.","definitionCN":"基础；基座；旧义亦指臀部。它是 fundamental 背后的直接名词。"},{"word":"foundational","ipa":"/faʊnˈdeɪʃənl/","tag":"sibling form","definition":"serving as a foundation. It comes through foundation rather than fundamentum, so it is a cousin of fundamental.","definitionCN":"基础的；奠基性的。它经 foundation 而非 fundamentum 而来，因此是 fundamental 的表亲。"}]},{"heading":"NEAR MEANING","entries":[{"word":"essentially","ipa":"/ɪˈsenʃəli/","tag":"in essence","definition":"in terms of the basic nature of something. It is close to the first sense of fundamentally.","definitionCN":"就某物的基本性质而言。它接近 fundamentally 的第一个义项。"},{"word":"basically","ipa":"/ˈbeɪsɪkli/","tag":"at the simple level","definition":"in the simplest or most important respects. It is more informal and can sound dismissive.","definitionCN":"就最简单或最重要的方面而言。它更口语化，也可能显得轻慢。"},{"word":"radically","ipa":"/ˈrædɪkli/","tag":"down to the root","definition":"in a way that affects the root or whole. It stresses change, while fundamentally stresses the level of the claim.","definitionCN":"影响根部或整体的方式。它强调变化，而 fundamentally 强调陈述的层级。"},{"word":"profoundly","ipa":"/prəˈfaʊndli/","tag":"deeply","definition":"to a great depth or degree. It stresses intensity, not structural position.","definitionCN":"深深地；极度地。它强调强度，而非结构位置。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"fundus 'bottom' + -mentum 'means' + -alis 'relating to' + -ly: the word walks all the way down to the base.","cn":"fundus“底部”+ -mentum“手段”+ -alis“与……有关”+ -ly：这个词一路走到基座。"},{"en":"fundamentally different, fundamentally change and fundamentally flawed are the three strongest collocations.","cn":"fundamentally different、fundamentally change、fundamentally flawed 是三个最强搭配。"},{"en":"fundamental and foundational are cousins: one comes through fundamentum, the other through foundation.","cn":"fundamental 与 foundational 是表亲：一个经 fundamentum，一个经 foundation。"},{"en":"In finance, fundamentals are the base conditions, so fundamentally means 'ignoring the market noise'.","cn":"金融里 fundamentals 是基础条件，因此 fundamentally 意为“撇开市场噪音”。"},{"en":"Do not confuse fundamentally with functional: fund- is bottom, fung- is perform.","cn":"别把 fundamentally 与 functional 混淆：fund- 是底部，fung- 是执行。"}],"abstract":[{"en":"Think of digging under a house until you reach the layer that carries the whole weight.","cn":"想象在房子下面挖，直到碰到承住全部重量的那一层。"},{"en":"Think of two buildings whose foundations sit in different places, so no bridge can join them.","cn":"想象两栋楼的地基在位置不同，因此没有桥能接上。"},{"en":"Think of peeling an onion until nothing but the core is left, and the core is the answer.","cn":"想象一层层剥洋葱，直到只剩核心，而核心就是答案。"}]},"examples":[{"en":"The two systems are fundamentally incompatible, not merely different in detail.","cn":"这两个系统根本不相容，不只是细节不同。"},{"en":"Fundamentally, the problem is one of trust, not of technology.","cn":"从根本上说，问题在信任，而不在技术。"},{"en":"The discovery fundamentally changed how the disease is treated.","cn":"这一发现彻底改变了这种病的治疗方式。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“翻（fun）到地基（fund）下面去看”——挖到最底层，才看清根子 → fundamentally 根本上","word":"fundamentally"},"root":"拉丁 fundus“底部” → fundare“打地基” → fundamentum“地基” → fundamentalis → 英语 fundamental + -ly。","sensesIntro":{"en":"Eight senses share one direction: the statement is pushed down to the base, where the real difference or cause sits.","cn":"八个义项共享一个方向：把陈述压到基座处，真正的差别或原因就在那里。"},"semanticMap":{"core":{"en":"CORE IMAGE: a foundation exposed beneath a house.","cn":"核心意象：房子下面露出的地基。"},"chain":["GO TO THE BASE","IN ESSENCE","AT THE STRUCTURE","IN PRINCIPLE","AT THE FLOOR OF EXPLANATION","BEYOND COMPROMISE"],"branches":[{"senses":"01 · 03","en":"ESSENCE AND TOTALITY: a base change is both 'what it really is' and 'completely', because moving the base moves everything.","cn":"本质与整体：基座的变化既是“它到底是什么”，也是“彻底地”，因为地基一动全都动。"},{"senses":"02 · 04","en":"STRUCTURE: changing the base and comparing skeletons are two ways of looking below the surface.","cn":"结构：改变基座与比较骨架，是两种看穿表面的方式。"},{"senses":"05 · 06","en":"PRINCIPLES: the sound-in-principle sense and the floor-of-explanation sense both stop at the lowest support.","cn":"原则：“原则上站得住”与“解释的地板”两个义项，都停在最低的支撑处。"},{"senses":"07","en":"INCOMPATIBILITY: foundations in different places cannot be joined by any amount of surface building.","cn":"不相容：位于不同处的地基，靠任何表面建造都接不上。"},{"senses":"08","en":"FINANCE: fundamentals are base conditions, set against the noise of price.","cn":"金融：fundamentals 是基础条件，与价格噪音相对。"}]},"affixes":{"intro":{"en":"Fundamentally is fundamental plus -ly. The fund- stem means 'bottom', -mentum marks a means, -alis makes a relational adjective and -ly makes the adverb.","cn":"fundamentally 是 fundamental 加 -ly。fund- 词干意为“底部”，-mentum 标记手段，-alis 构成关系形容词，-ly 构成副词。"},"latinIntro":{"en":"The family runs from fundus 'bottom' through fundare 'found' and fundamentum 'foundation' to fundamentalis. English relatives include found, foundation, fundamental and profound.","cn":"这个词族从 fundus“底部”经 fundare“奠基”与 fundamentum“地基”到 fundamentalis。英语同族词包括 found、foundation、fundamental、profound。"},"items":[{"word":"fundamental","structure":"fundamentum + -al (relational adjective)","meaning":"forming the base or essence","meaningCN":"根本的；基本的（-al 关系形容词）","example":"Freedom of thought is a fundamental right.","exampleCN":"思想自由是一项基本权利。"},{"word":"fundamentally","structure":"fundamental + -ly (manner adverb)","meaning":"at the base; in essence","meaningCN":"根本上；基本上（-ly 方式副词）","example":"The two approaches are fundamentally the same.","exampleCN":"这两种方法根本上相同。"},{"word":"fundament","structure":"fundare + -mentum (means noun)","meaning":"a base or foundation","meaningCN":"基础；基座（-mentum 手段名词）","example":"The fundament of the argument is a single assumption.","exampleCN":"这一论证的基础是一个单一假设。"},{"word":"fundamentals","structure":"fundamental + -s (plural noun)","meaning":"the basic principles of a subject","meaningCN":"基本原理；基本面（复数名词）","example":"The course teaches the fundamentals of accounting.","exampleCN":"这门课教授会计的基本原理。"},{"word":"foundation","structure":"fundare + -tio (action noun)","meaning":"the base; the act of founding","meaningCN":"地基；创立（-tio 动作名词）","example":"The foundation took two months to set.","exampleCN":"地基花了两个月凝固。"},{"word":"found","structure":"fundare (verb)","meaning":"to establish or lay a base","meaningCN":"创立；奠基","example":"The city was founded on the river bank.","exampleCN":"这座城市建在河岸上。"},{"word":"profound","structure":"pro- (forward, down) + fundus (bottom)","meaning":"deep; reaching far down","meaningCN":"深刻的（pro- + fundus“底”，同一词根）","example":"The lecture had a profound effect.","exampleCN":"这场讲座产生了深刻的影响。"},{"word":"fund","structure":"fundus (bottom, land)","meaning":"money set aside as a base; to finance","meaningCN":"基金；资助（fundus“土地、底”，金融义另分）","example":"They funded the study for three years.","exampleCN":"他们资助这项研究三年。"}],"latinEntries":[{"word":"fundus","structure":"fundus (bottom, base)","meaning":"bottom, base; a piece of land","meaningCN":"底部；基底；一块土地"},{"word":"fundare","structure":"fundus + -are (verb)","meaning":"to lay a base, to found","meaningCN":"打地基；创立"},{"word":"fundamentum","structure":"fundare + -mentum (means noun)","meaning":"a foundation, a base","meaningCN":"地基；基础"},{"word":"fundamentalis","structure":"fundamentum + -alis (adjective)","meaning":"relating to a foundation","meaningCN":"与地基有关的（fundamental 的直接来源）"}]}},{"word":"generalization","ipa_uk":"/ˌdʒenrələˈzeɪʃn/","ipa_us":"/ˌdʒenrələˈzeɪʃn/","definition_zh":"概括；归纳；泛化；通则","definition_en":"a broad statement drawn from particular cases, or the act of extending a finding beyond the cases observed","core_image":"从一堆不同的果子中抽出一条共同特征，写在标签上贴到箱外","scene":"One successful trial does not justify a generalization about the whole population.","sceneCN":"这里 generalization 是「概括、推广结论」（第 1 个义项：把个别案例推成普遍说法）；句意：一次成功试验不足以支撑对整个群体的概括。图中可辨识物件：样本箱、标签、统计图表、放大镜。","pos":[{"tag":"n.","zh":"概括；归纳；泛化；通则"}],"collocations":[{"phrase":"broad generalization","zh":"宽泛的概括"},{"phrase":"make a generalization","zh":"作出概括"},{"phrase":"sweeping generalization","zh":"以偏概全的笼统结论"},{"phrase":"generalization from","zh":"由……得出的概括"},{"phrase":"generalization error","zh":"泛化误差"},{"phrase":"hasty generalization","zh":"草率概括"}],"forms":[{"label":"复数","form":"generalizations"}],"derivatives":[{"word":"general","pos":"adj./n.","zh":"一般的；普遍的；将军"},{"word":"generalize","pos":"v.","zh":"概括；推广；泛化"},{"word":"generality","pos":"n.","zh":"普遍性；概论"},{"word":"generally","pos":"adv.","zh":"一般地；通常"},{"word":"generalizable","pos":"adj.","zh":"可推广的"}],"senses":[{"no":"01","title":"A broad statement","titleCN":"概括性说法：从几件事推成一类事","definition":"a statement that applies to many cases but is drawn from only some of them","definitionCN":"适用于许多情形、却只由其中部分情形得出的陈述","example":"The claim that all teenagers dislike school is a broad generalization.","exampleCN":"“所有青少年都讨厌上学”是一个宽泛的概括。","why":"genus means 'kind'. Generalization gathers many particulars under one kind, and in doing so leaves detail behind.","whyCN":"genus 意为“类”。generalization 把许多个别事物收进一个“类”，也因此丢下了细节。"},{"no":"02","title":"The act of inducing","titleCN":"归纳：从例子走到规则","definition":"the mental act of moving from observed examples to a general rule","definitionCN":"从观察到的例子走向一般规则的心智行为","example":"Generalization from three cases is weaker than generalization from three hundred.","exampleCN":"从三个案例归纳，比从三百个案例归纳要弱。","why":"Induction is the method; generalization is the move it makes. The word names the leap from the sample to the class.","whyCN":"归纳法是方法，generalization 是它做出的那一跳。这个词命名从样本跳到类的那一步。"},{"no":"03","title":"Machine learning: working on new data","titleCN":"泛化：换一批数据还管用","definition":"in machine learning, the ability of a model to perform well on data it was not trained on","definitionCN":"机器学习中模型在未训练过的数据上仍表现良好的能力","example":"The model's generalization was poor because it had memorized the training set.","exampleCN":"这个模型的泛化很差，因为它把训练集背了下来。","why":"Learning theory borrows the word for the leap from seen to unseen. A model that only fits its examples has not generalized at all.","whyCN":"学习理论借这个词指从“见过”跳到“未见过”。只拟合样例的模型，根本没有泛化。"},{"no":"04","title":"Overgeneralization","titleCN":"以偏概全：一条规则套到所有","definition":"the act of applying a rule beyond the cases where it holds","definitionCN":"把一条规则用到它并不成立的情形","example":"Treating every quiet student as disengaged is a harmful generalization.","exampleCN":"把每个安静的学生都当作不投入，是一种有害的以偏概全。","why":"A generalization always exceeds its evidence. When the excess becomes damaging, the word carries a negative tone and takes the prefix over-.","whyCN":"概括总是超出证据。当超出造成伤害时，这个词就带负面色彩，并加上 over- 前缀。"},{"no":"05","title":"Mathematical extension","titleCN":"推广：把定理搬到更大范围","definition":"in mathematics, the extension of a result to a wider class of objects","definitionCN":"数学中把某结果扩展到更广的对象类","example":"The generalization of the theorem covers curved surfaces as well as flat ones.","exampleCN":"该定理的推广同时涵盖曲面与平面。","why":"Mathematics uses the word for a legitimate widening. The proof must carry over, so this is generalization with a guarantee.","whyCN":"数学用这个词指合法的拓宽。证明必须能随之搬过去，因此这是有保证的推广。"},{"no":"06","title":"Making something general","titleCN":"普遍化：从特例变成通例","definition":"the process of making a rule, term or practice apply to more situations","definitionCN":"使规则、术语或做法适用于更多情境的过程","example":"The generalization of the policy to rural districts took five years.","exampleCN":"把该政策普遍化到农村地区花了五年。","why":"Here the word is administrative rather than logical: a specific arrangement is widened until it becomes the standard.","whyCN":"这里的词是行政性的而非逻辑性的：一项具体安排被拓宽，直到成为标准。"},{"no":"07","title":"A rule of thumb","titleCN":"通则：日常可用的经验说法","definition":"a rough everyday rule that is useful without being strictly true","definitionCN":"日常可用、但不严格为真的粗略规则","example":"As a generalization, cheaper flights leave earlier in the day.","exampleCN":"作为一条通则，较便宜的航班通常在一天中更早起飞。","why":"The phrase as a generalization is a warning label: it admits exceptions while still offering the rule.","whyCN":"as a generalization 这一说法是个警示标签：承认例外，同时仍给出规则。"},{"no":"08","title":"Generalization error","titleCN":"泛化误差：换数据后差多少","definition":"the gap between a model's performance on training data and on new data","definitionCN":"模型在训练数据与新数据上表现的差距","example":"Regularization reduced the generalization error by a third.","exampleCN":"正则化把泛化误差降低了三分之一。","why":"The error measures the cost of the leap. A small gap means the model truly generalized; a large one means it memorized.","whyCN":"这个误差衡量那一跳的代价。差距小说明模型真的泛化了；差距大说明它只是背下来。"}],"etymology":{"intro":{"en":"Generalization is generalize plus -ation. General comes from Latin generalis 'of a whole kind', from genus 'kind, race'. The word is about grouping many particulars under one kind.","cn":"generalization 是 generalize 加 -ation。general 来自拉丁 generalis“属于整个类的”，源头是 genus“类、族”。这个词讲的是把许多个别事物归入一个类。"},"items":[{"era":"LATIN GENUS","en":"genus meant 'kind, race, birth'. Its stem gener- gives generate, generation and generosity, all built on the idea of birth or kind.","cn":"genus 意为“类、族、出生”。其词干 gener- 生出 generate、generation、generosity，都建立在“出生”或“类”的观念上。"},{"era":"LATIN GENERALIS","en":"generalis 'relating to a whole kind' is built on genus. It contrasts with specialis 'relating to a species', so general and specific are paired from the start.","cn":"generalis“属于整个类的”建立在 genus 上。它与 specialis“属于某个种的”相对，因此 general 与 specific 从一开始就是一对。"},{"era":"ENGLISH GENERAL","en":"English general arrives through French in the 13th century. It means 'covering the whole class', and the military noun 'general' is a separate development from the same adjective.","cn":"英语 general 于 13 世纪经法语进入，意为“覆盖整个类的”；军事名词“将军”是同一形容词的另一条发展线。"},{"era":"ENGLISH GENERALIZE","en":"Generalize appears in the 17th century with the sense 'to bring under a general rule'. The -ize suffix marks making or converting.","cn":"generalize 于 17 世纪出现，意为“归入一般规则”。-ize 后缀标记“使成为、转换”。"},{"era":"ENGLISH -ATION","en":"Generalization adds -ation, from Latin -atio, naming the process. The word is common in logic, social science and later in statistics.","cn":"generalization 加 -ation（来自拉丁 -atio），命名过程。这个词常见于逻辑学、社会科学，后来也进入统计学。"},{"era":"LEARNING THEORY","en":"In the 20th century machine learning adopts generalization for performance on unseen data, giving the technical phrase generalization error.","cn":"20 世纪机器学习采用 generalization 指在未见数据上的表现，形成技术说法 generalization error。"}]},"similar":{"note":{"en":"The look-alike group shares the gener- stem; the near-meaning group all involve moving from particulars to something wider, with different validity.","cn":"形近组共享 gener- 词干；近义组都涉及从个别走向更广，但有效性不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"general","ipa":"/ˈdʒenrəl/","tag":"same root, adjective","definition":"covering a whole class; not detailed. It describes scope, while generalization names the move or the statement.","definitionCN":"覆盖整个类的；不具体的。它描述范围，而 generalization 命名那一跳或那条陈述。"},{"word":"generalize","ipa":"/ˈdʒenrəlaɪz/","tag":"same root, verb","definition":"to draw a general rule or to widen the application. It is the action behind the noun.","definitionCN":"作出一般规则或拓宽适用范围。它是名词背后的动作。"},{"word":"generic","ipa":"/dʒəˈnerɪk/","tag":"same root, different suffix","definition":"shared by a whole class, often without a brand. It comes from genus through gener- but with -icus, and means 'of the class', not 'the act of generalizing'.","definitionCN":"整个类共有的，常指无品牌。它经 gener- 与 -icus 来自 genus，意为“属于该类的”，而非“概括行为”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"abstraction","ipa":"/æbˈstrækʃn/","tag":"pulling out a common feature","definition":"a general idea separated from particular examples. It stresses the resulting concept, while generalization stresses the leap and its breadth.","definitionCN":"从具体例子中抽出的普遍观念。它强调所得概念，而 generalization 强调那一跳及其广度。"},{"word":"induction","ipa":"/ɪnˈdʌkʃn/","tag":"the logical method","definition":"reasoning from particular cases to a general rule. It is the method; generalization is its conclusion or act.","definitionCN":"从个别案例推出一般规则的推理。它是方法；generalization 是其结论或行为。"},{"word":"sweeping statement","ipa":"/ˈswiːpɪŋ ˈsteɪtmənt/","tag":"too broad to be safe","definition":"a claim that covers far too much. It is a criticism, while generalization can be neutral or technical.","definitionCN":"涵盖过多的断言。它是批评用语，而 generalization 可中性或技术化。"},{"word":"extrapolation","ipa":"/ɪkˌstræpəˈleɪʃn/","tag":"projecting beyond data","definition":"the extension of a trend beyond the observed range. It is about range, while generalization is about class membership.","definitionCN":"把趋势外推到观察范围之外。它关乎范围，而 generalization 关乎类的归属。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"genus 'kind' gives general: generalization puts many particulars into one kind.","cn":"genus“类”生出 general：generalization 把许多个别事物放进一个类。"},{"en":"generalize, generalization and generality share the gener- stem; generic is the cousin meaning 'of the class'.","cn":"generalize、generalization、generality 共享 gener- 词干；generic 是意为“属于该类的”的表亲。"},{"en":"sweeping generalization and broad generalization are the critical collocations; they warn about excess breadth.","cn":"sweeping generalization 与 broad generalization 是批评性搭配，都在警告“广度过头”。"},{"en":"In machine learning, generalization error measures the leap from training data to new data.","cn":"机器学习中，generalization error 衡量从训练数据跳到新数据的代价。"},{"en":"As a generalization is a warning label: the rule follows, but exceptions are admitted.","cn":"as a generalization 是警示标签：规则照给，但承认例外。"}],"abstract":[{"en":"Think of picking one shared feature from a heap of different fruit and writing it on a label.","cn":"想象从一堆不同的果子里挑出一条共同特征，写在标签上。"},{"en":"Think of a single footprint used to describe a whole animal you have never seen.","cn":"想象用一个脚印去描述一头你从未见过的动物。"},{"en":"Think of a map drawn at a scale so small that every street becomes one line.","cn":"想象一张比例尺极小的地图，每条街都缩成一条线。"}]},"examples":[{"en":"The study warns against generalization from a sample of only twenty patients.","cn":"该研究警告不要从仅二十名患者的样本作概括。"},{"en":"A model that memorizes its training data shows poor generalization.","cn":"把训练数据背下来的模型泛化能力很差。"},{"en":"As a generalization, older buildings need more maintenance.","cn":"作为一条通则，老建筑需要更多维护。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“general（一般）+ 化”——把个别例子“化”成一般说法 → generalization 概括","word":"generalization"},"root":"拉丁 genus“类、族”（词干 gener-）→ generalis“属于整个类的” → 英语 general → generalize + -ation；核心是“把个别归入一个类”。","sensesIntro":{"en":"Eight senses share one leap: from a few observed cases to a class that reaches beyond them, sometimes with proof and sometimes without.","cn":"八个义项共享同一跳：从少数观察到的案例跳到超出它们的类，有时有证明，有时没有。"},"semanticMap":{"core":{"en":"CORE IMAGE: one shared feature lifted from a heap and written on a label.","cn":"核心意象：从一堆事物中抽出一条共同特征写在标签上。"},"chain":["GATHER INTO A KIND","STATE A BROAD RULE","MAKE THE LEAP","EXTEND TOO FAR","APPLY TO NEW DATA","WIDEN THE SCOPE"],"branches":[{"senses":"01 · 02","en":"THE LEAP: a broad statement and the act of inducing are the product and the move that produces it.","cn":"那一跳：宽泛陈述与归纳行为，是产物与产生它的动作。"},{"senses":"03 · 08","en":"UNSEEN DATA: generalization and generalization error measure whether the leap still holds on cases never observed.","cn":"未见数据：泛化与泛化误差，衡量这一跳在从未观察的案例上是否仍成立。"},{"senses":"04","en":"EXCESS: overgeneralization is the same leap made past the evidence, which is why it is criticized.","cn":"过度：以偏概全就是把同一跳跳过了证据，因此受到批评。"},{"senses":"05","en":"MATHEMATICS: extension to a wider class is the same widening, but with a proof that carries over.","cn":"数学：扩展到更广的类是同一种拓宽，但带着能搬过去的证明。"},{"senses":"06 · 07","en":"ADMINISTRATION AND THUMB RULES: widening a policy and offering a rough rule are practical versions of the same move.","cn":"行政与经验法则：把政策普遍化、给出粗略规则，是同一跳的实用版本。"}]},"affixes":{"intro":{"en":"Generalization is generalize plus -ation. The gener- stem means 'kind', -al makes a relational adjective, -ize makes a verb and -ation names the process.","cn":"generalization 是 generalize 加 -ation。gener- 词干意为“类”，-al 构成关系形容词，-ize 构成动词，-ation 命名过程。"},"latinIntro":{"en":"The family runs from genus 'kind' through generalis 'of the whole kind' to English general. Relatives include generate, generation, generosity, generic and generality.","cn":"这个词族从 genus“类”经 generalis“属于整个类的”到英语 general。同族词包括 generate、generation、generosity、generic、generality。"},"items":[{"word":"general","structure":"gener- + -al (relational adjective)","meaning":"covering a whole class","meaningCN":"一般的；普遍的（-al 关系形容词）","example":"The general rule has exceptions.","exampleCN":"这条一般规则有例外。"},{"word":"generalize","structure":"general + -ize (make verb)","meaning":"to form a general rule; to widen","meaningCN":"概括；推广（-ize 使动动词）","example":"Do not generalize from one bad experience.","exampleCN":"别从一次糟糕的经历就下普遍结论。"},{"word":"generalization","structure":"generalize + -ation (process noun)","meaning":"a broad statement or the act of making one","meaningCN":"概括；泛化（-ation 过程名词）","example":"That is a generalization, not a law.","exampleCN":"那只是概括，不是定律。"},{"word":"generality","structure":"general + -ity (quality noun)","meaning":"the quality of being general; a broad statement","meaningCN":"普遍性；概论（-ity 性质名词）","example":"The generality of the rule limits its use.","exampleCN":"这条规则的普遍性限制了它的用途。"},{"word":"generally","structure":"general + -ly (manner adverb)","meaning":"usually; in general terms","meaningCN":"一般地；通常（-ly 方式副词）","example":"The weather is generally mild here.","exampleCN":"这里天气通常温和。"},{"word":"generalizable","structure":"generalize + -able (capable of being)","meaning":"able to be extended to other cases","meaningCN":"可推广的（-able“能够被……”）","example":"The finding is generalizable to other regions.","exampleCN":"这一发现可推广到其他地区。"},{"word":"generic","structure":"gener- + -ic (belonging to)","meaning":"shared by a whole class; without a brand","meaningCN":"通用的；无品牌的（-ic“属于……”）","example":"Generic drugs cost much less.","exampleCN":"仿制药便宜得多。"},{"word":"generate","structure":"gener- + -ate (verb)","meaning":"to bring into being","meaningCN":"产生；生成（同一词根，-ate 动词）","example":"The panels generate enough power for the village.","exampleCN":"这些板子发的电足够全村使用。"}],"latinEntries":[{"word":"genus","structure":"genus (kind, race, birth)","meaning":"kind, race, birth","meaningCN":"类；族；出生"},{"word":"generalis","structure":"genus + -alis (adjective)","meaning":"relating to a whole kind","meaningCN":"属于整个类的"},{"word":"generare","structure":"gener- + -are (verb)","meaning":"to beget, to produce","meaningCN":"生育；产生"},{"word":"generatio","structure":"generat- + -io (action noun)","meaning":"a begetting, a generation","meaningCN":"生育；世代"}]}}]);
